INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('29582b64-f8fd-50fa-a6ca-6d235692eaad', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 10, 53, 'ምርኮአቸውንም እመልሳለሁ፤ የሰዶምና የሴቶች ልጆችዋን ምርኮ፥ የሰማርያንና የሴቶች ልጆችዋን ምርኮ እመልሳለሁ፤ በመካከላቸውም ያሉትን የምርኮኞችሽን ምርኮ እመልሳለሁ።'),
  ('c40df30f-0133-52f4-aa88-7c16b8eeead3', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 11, 54, 'ፍዳሽንም ትቀበዪ ዘንድ በአስቈጣሽኝ ሥራሽ ሁሉ ታፍሪያለሽ።'),
  ('7eaadc21-7ed5-5235-a390-68356b8078b8', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 12, 55, 'እኅቶችሽም ሰዶምና ሴቶች ልጆችዋ ወደ ቀድሞ ሁኔታቸው ይመለሳሉ፤ ሰማርያና ሴቶች ልጆችዋም ወደ ቀድሞ ሁኔታቸው ይመለሳሉ፤ አንቺና ሴቶች ልጆችሽም ወደ ቀድሞ ሁኔታችሁ ትመለሳላችሁ።'),
  ('144293cc-9cda-5998-a772-5388ba461fed', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 13, 56, 'እኅትሽ ሰዶምም በትዕቢትሽ ቀን በአፍሽ አልተወሳችም።'),
  ('4ae1cc85-dc9d-59ec-a7c9-3fe6fdf6c1bb', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 14, 57, 'ክፋትሽ እንደ ዛሬው ሳይገለጥ ለሶርያ ሴቶች ልጆችና ለጐረቤቶችዋ ሁሉ በዙሪያሽም ለሚከቡሽ ፍልስጥኤማውያት ሴቶች ልጆች መሰደቢያ ሆነሻል።'),
  ('87fcac3b-8498-5d78-a151-bab59bdb2641', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 15, 58, 'ኀጢአትሽንና በደልሽን ተሽክመሻል፥ ይላል እግዚአብሔር።'),
  ('fa2aa3ed-4d20-5d00-aa6d-e5170ba5a4ee', '8144132e-6311-5911-a58b-9a7566d6fd07', 'ca272ad0-02cd-58fb-a4ba-1f26b566435b', 1, 59, '“ጌታ እግዚአብሔርም እንዲህ ይላል፦ አንቺ ቃል ኪዳንን በማፍረስ መሐላን የናቅሽ ሆይ! አንቺ እንዳደረግሽ እኔ ደግሞ አደርግብሻለሁ።'),
  ('28aedce2-45f9-52c5-ae22-8fd54df0bbe4', '8144132e-6311-5911-a58b-9a7566d6fd07', 'ca272ad0-02cd-58fb-a4ba-1f26b566435b', 2, 60, 'ነገር ግን በሕፃንነትሽ ወራት ከአንቺ ጋር ያደረግሁትን ቃል ኪዳኔን ዐስባለሁ፤ የዘለዓለምንም ቃል ኪዳን አጸናልሻለሁ።'),
  ('37b9fcd9-357f-50bf-ae57-2528d2676b72', '8144132e-6311-5911-a58b-9a7566d6fd07', 'ca272ad0-02cd-58fb-a4ba-1f26b566435b', 3, 61, 'ታላቆቹንና ታናሾቹን እኅቶችሽንም በተቀበልሽ ጊዜ መንገድሽን ታስቢያለሽ፤ ታፍሪማለሽ፤ ለአንቺም ልጆች ይሆኑ ዘንድ እሰጣቸዋለሁ፤ ስለ ቃል ኪዳንሽ ግን አይደለም።'),
  ('f894cdad-eee1-58e9-a35e-75ebf4442bb4', '8144132e-6311-5911-a58b-9a7566d6fd07', 'ca272ad0-02cd-58fb-a4ba-1f26b566435b', 4, 62, 'እኔም ቃል ኪዳኔን ከአንቺ ጋር አጸናለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቂያለሽ።'),
  ('fb46be3e-12f8-56f6-a352-52d551cc7482', '8144132e-6311-5911-a58b-9a7566d6fd07', 'ca272ad0-02cd-58fb-a4ba-1f26b566435b', 5, 63, 'ታስቢ ዘንድ፥ ታፍሪም ዘንድ፥ ደግሞም ስላደረግሽው ነገር ሁሉ ይቅር ባልሁሽ ጊዜ፥ስለ ኀፍረትሽ አፍሽን ትከፍቺ ዘንድ አይቻልሽም፤” ይላል ጌታ እግዚአብሔር።'),
  ('0b727828-29e5-5b66-acca-60663587d6a0', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 1, 1, 'የእግዚአብሔር ቃል ወደኔ እንዲህ ሲል መጣ፦'),
  ('a27f0acf-bdeb-5d98-a923-54531c8ee7c6', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 2, 2, '“የሰው ልጅ ሆይ! ለእስራኤል ቤት ምሳሌ መስለህ ንገር፤ እንዲህም በል፦'),
  ('6ca026f5-4203-5ad0-a394-796d932f53e9', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 3, 3, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ታላቅ ክንፍ፥ ረጅምም ጽፍር ያለው፥ ላባንም የተሞላ፥ መልከ ዝንጉርጉር የሆነ ታላቅ ንስር ወደ ሊባኖስ መጣ፤ የዝግባንም ጫፍ ወሰደ።'),
  ('5f06735d-36b9-5262-a70d-29362ea469fb', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 4, 4, 'ቀንበጡንም ቀነጠበ፤ ወደ ከነዓንም ምድር ወሰደው፤ ቅጥር ባለው ከተማም አኖረው።'),
  ('81fb6bc7-f36a-57c2-a6dc-042f52aa26c3', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 5, 5, 'ከምድርም ዘር ወሰደ፤ በፍሬያማ እርሻም ዘራው፤ በብዙም ውኃ አጠገብ እንደ አኻያ ዛፍ አኖረው።'),
  ('1c856df9-b13e-5283-a5bd-a52fae69a445', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 6, 6, 'በበቀለም ጊዜ ቁመቱ ያጠረ፥ ሐረጉም ወደ እርሱ የሚመለስ፥ ሥሩም በበታቹ የነበረ ሰፊ ወይን ሆነ፤ እንዲሁ ወይን ሆነ፤ ሐረግም ሰደደ፤ ቀንበጥም አወጣ።'),
  ('97d0659a-9407-5552-ae68-2838bef2f8f1', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 7, 7, '“ታላቅ ክንፍና ብዙ ጽፍርም ያለው ሌላ ታላቅ ንስር ነበረ፤ እነሆም ያጠጣው ዘንድ ይህ ወይን ሥሩን ወደ እርሱ ሰደደ፤ ሐረጉንም ከተተከለበት ከመደቡ ወደ እርሱ አዘነበለ።'),
  ('46f2c88e-2f40-50f2-a7ad-ceeaa781f620', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 8, 8, 'ሐረግም ያወጣ፥ ፍሬም ያፈራ፥ የከበረ ወይንም ይሆን ዘንድ በመልካም መሬት ውስጥ፥ በብዙም ውኃ አጠገብ ተተክሎ ነበር።'),
  ('9a1641ea-0bf6-5272-a52d-89fff18c109e', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 9, 9, 'እንዲህም በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ በውኑ ይከናወንለት ይሆን? ይደርቅስ ዘንድ፥ አዲስ የበቀለውስ ቅጠሉ ይጠወልግ ዘንድ ሥሩን አይነቅለውምን? ፍሬውንስ አይለቅመውምን? ሥሩም የተነቀለው በብርቱ ክንድና በብዙ ሕዝብ አይደለም።'),
  ('16dce72e-9ea8-5572-ab0a-4d86d5026a52', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'ad6f50b9-db6e-5141-a565-6fe8c1bb6ecc', 10, 10, 'ተተክሎስ፥ እነሆ ይከናወንለት ይሆን? የምሥራቅ ነፋስ ባገኘው ጊዜ ፈጽሞ አይደርቅምን? በተተከለበት መደብ ላይ ይደርቃል።”'),
  ('1a42df2e-3d90-55fe-a158-2c299a55e53e', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 1, 11, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('9fccd5f5-d255-5bf6-a4f2-f252a4456e22', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 2, 12, '“የሰው ልጅ ሆይ፥ ለአስቈጡኝ ለእስራኤል ቤት ይህ ትርጓሜ ምን እንደ ሆነ አታውቁምን? በላቸው። እንዲህም ብለህ ንገራቸው፦ እነሆ የባቢሎን ንጉሥ ወደ ኢየሩሳሌም መጣ፤ ንጉሥዋንና መኳንንቶችዋንም ማረከ፤ ወደ ሀገሩም ወደ ባቢሎን ወሰዳቸው።'),
  ('50422571-1a03-5d32-a5a0-1ad439046f7d', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 3, 13, 'ከመንግሥትም ዘር ወስዶ ከእርሱ ጋር ቃል ኪዳን አደረገ፤ አማለውም፤ የምድሪቱንም ኀያላን ወሰደ፤'),
  ('6e640477-0b4f-55c4-a8ba-80757657c68c', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 4, 14, 'ይኸውም መንግሥቱ እንድቷረድና ከእንግዲህም ከፍ እንዳትል፥ ቃል ኪዳኑን በመጠበቅ ጸንታ እንድትኖር ነው።'),
  ('6ddd921b-a747-5df1-ad17-f2e11ae5ae38', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 5, 15, 'እርሱ ግን በእርሱ ላይ ሸፈተ፤ ፈረሶችንና ብዙንም ሕዝብ ይሰጡት ዘንድ መልእክተኞችን ወደ ግብፅ ላከ። በውኑ ይከናወንለት ይሆን? ይህንስ ያደረገ ያመልጣልን? ቃል ኪዳንንስ ያፈረሰ ያመልጣልን?'),
  ('639cc05d-78f4-5694-aba1-83641cabf69a', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 6, 16, '“እኔ ሕያው ነኝ! ያነገሠውና መሐላውን የናቀበት፥ ቃል ኪዳኑንም ያፈረሰበት ንጉሥ በሚኖርበት ስፍራ ከእርሱ ጋር በባቢሎን መካከል በርግጥ ይሞታል፥ ይላል ጌታ እግዚአብሔር።'),
  ('d18f8726-32d4-52dc-af12-18515df0a711', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 7, 17, 'ብዙዎችን ነፍሳት ለማስወገድ ምሽግን በመሸጉ፥ ቅጥርንም በሠሩ ጊዜ፥ ፈርዖን በታላቅ ኀይልና በብዙ ሕዝብ በጦርነት አይረዳውም።'),
  ('8bb6e6a8-9ea4-54bf-acf2-7824bfe2e6a3', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 8, 18, 'ቃል ኪዳኑንም በማፍረስ መሐላውን ንቆአል፤ እነሆም እጁን አሳልፌ ሰጠሁ፤ ይህንም ሁሉ አድርጎአል፤ ስለዚህም አያመልጥም።'),
  ('3a34b51c-731b-560b-ad91-8809a8b2c869', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 9, 19, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እኔ ሕያው ነኝ! የናቀውን መሐላዬንና ያፈረሰውን ቃል ኪዳኔን በራሱ ላይ አመጣለሁ በላቸው።'),
  ('bc213787-e29d-58e9-a244-9d35e5920c46', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 10, 20, 'መረቤንም በእርሱ ላይ እዘረጋለሁ፤ በወጥመድም ይያዛል፤ ወደ ባቢሎንም አመጣዋለሁ፤ በእኔም ላይ ስላደረገው ዐመፅ በዚያ ከእርሱ ጋር እፋረዳለሁ።'),
  ('de26b93a-3b66-5700-afb8-667182fa5120', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'd129e916-5fee-558c-a021-7f190910bdd1', 11, 21, 'ያመለጡትም ሁሉ በሰይፍ ይወድቃሉ፤ የቀሩትም ሁሉ ወደ እየነፋሳቱ ይበተናሉ፤ እኔም እግዚአብሔር እንደ ተናገርሁ ታውቃላችሁ።'),
  ('f0ac9467-85b1-5367-ac2e-3c7b8fb5bb6c', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'a45ba8a1-6295-5a4d-a65a-0990eb6c9370', 1, 22, '“ጌታ እግዚአብሔር እንዲህ ይላል፦ ከረዥሙ ዝግባ ጫፍ ላይ ቀንበጥን ወስጄ አኖረዋለሁ፤ ከጫፎቹም አንዱን ቀንበጥ እቀነጥበዋለሁ፤ በረዥምና በታላቅ ተራራም ላይ እተክለዋለሁ።'),
  ('5962cf51-c352-5e47-a713-274dc7332240', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'a45ba8a1-6295-5a4d-a65a-0990eb6c9370', 2, 23, 'ከፍ ባለው በእስራኤል ተራራ ላይ እተክለዋለሁ፤ ቅርንጫፎችንም ያወጣል፤ ፍሬም ያፈራል፤ ታላቅም ዝግባ ይሆናል፤ በበታቹም ወፎች ሁሉ ያርፋሉ፤ በቅርንጫፎቹም ጥላ በክንፍ የሚበርር ሁሉ ይጠጋል፤ ቅርንጫፉም ይሰፋል።'),
  ('2cf96fbc-cdb5-5e03-a2a2-087c35247f95', 'ad3d8412-58b4-5885-ad4b-ee123f708141', 'a45ba8a1-6295-5a4d-a65a-0990eb6c9370', 3, 24, 'የዱር ዛፎች ሁሉ፥ ረዥሙን ዛፍ ዝቅ ያደረግሁ፥ አጭሩንም ዛፍ ከፍ ያደረግሁ፥ የለመለመውንም ዛፍ ያደረቅሁ፥ የደረቀውንም ዛፍ ያለመለምሁ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ፤ እኔ እግዚአብሔር ተናገርሁ፤ እኔም አደረግሁ።”'),
  ('cd3bec9e-0aa4-55ea-a0a1-98d45123cb81', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('9efe76c4-b97f-556c-ab60-0fabb995c1bb', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 2, 2, '“በእስራኤል ልጆች፦ ‘አባቶች ጨርቋ የወይን ፍሬ በሉ፥ የልጆችም ጥርሶች ጠረሱ’ ብላችሁ በመካከላችሁ የምትመስሉት ምሳሌ ምንድን ነው?'),
  ('a3b682eb-a3e8-5af8-ad8f-ce2a8fb52211', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 3, 3, 'እኔ ሕያው ነኝ! እንግዲህ ወዲህ ይህን ምሳሌ በእስራኤል ዘንድ አትመስሉትም፥ ይላል ጌታ እግዚአብሔር።'),
  ('3f318c5e-cb3e-5898-a06c-c1aba840b481', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 4, 4, 'እነሆ ነፍሳት ሁሉ የእኔ ናቸው፤ የአባት ነፍስ የእኔ እንደ ሆነች እንዲሁ የልጅ ነፍስ የእኔ ናት፤ ኀጢአት የምትሠራ ነፍስ እርስዋ ትሞታለች።'),
  ('04396d40-c79e-566d-a860-1c0654894b58', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 5, 5, '“ሰውም ጻድቅ ቢሆን ፍርድንና ቅን ነገርንም ቢያደርግ፤'),
  ('5c98a0e9-87c7-575a-a714-be51235b6a6e', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 6, 6, 'በተራራም ላይ ባይበላ፥ ዐይኖቹንም ወደ እስራኤል ቤት ጣዖታት ባያነሣ፥ የባልንጀራውንም ሚስት ባያረክስ፥ አደፍም ወዳለባት ሴት ባይቀርብ፤'),
  ('9885d6b8-482c-5e2e-a774-f21306441e21', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 7, 7, 'ሰውንም ባያስጨንቅ፥ ለባለ ዕዳም መያዣውን ቢመልስ፥ ፈጽሞም ባይቀማ፥ ከእንጀራውም ለተራበ ቢሰጥ፥ የተራቈተውንም ከልብሱ ቢያለብስ፤'),
  ('afd0e196-ed6a-5597-ad6a-275f52c2d2d1', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 8, 8, 'በአራጣ ባያበድር፥ አትርፎም ባይወስድ፥ እጁንም ከኀጢአት ቢመልስ፥ በሰውና በሰው መካከልም የእውነትን ፍርድ ቢፈርድ፥'),
  ('e476fae5-3b0a-5e47-a960-8b20831fb72f', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 9, 9, 'በትእዛዜም ቢሄድ፥ እውነትንም ለማድረግ ፍርዴን ቢጠብቅ፥ እርሱ ጻድቅ ነው፤ ፈጽሞ በሕይወት ይኖራል፥” ይላል ጌታ እግዚአብሔር።'),
  ('c8db34be-2bca-548e-a37f-114f0fd366db', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 10, 10, '“እርሱም ቀማኛና ደም አፍሳሽ ልጅን፥ ከዚህም ሁሉ አንዳቸውን የሚያደርገውን ቢወልድ፥'),
  ('83c04423-4b26-58b2-a6dd-69d059c4ab20', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 11, 11, 'እርሱም በጻድቅ አባቱ መንገድ ባይሄድ፥ በተራራም ላይ ቢበላ፥ የባልንጀራውንም ሚስት ቢያረክስ፥'),
  ('dcb06976-f3ff-5a2d-ac08-a0f52ad0355f', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 12, 12, 'ድሀውንና ችግረኛውን ቢያስጨንቅ፥ ቢቀማም፥ መያዣውንም ባይመልስ፥ ዐይኖቹንም ወደ ጣዖታት ቢያነሣ፥ ርኩስንም ነገር ቢያደርግ፥'),
  ('88d0cd87-669d-5f9a-a9f8-93cc0a2350e5', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 13, 13, 'በአራጣ ቢያበድር፥ አትርፎም ቢወስድ፥ እንደዚህ ያለ ሰው በሕይወት አይኖርም፤ ይህን ርኵሰት ሁሉ አድርጎአልና ፈጽሞ ይሞታል፤ ደሙም በላዩ ይሆናል።'),
  ('7b34a24b-ec1f-5749-a07c-d6d1b6672cfa', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 14, 14, '“እነሆም ልጅ ቢወልድ፥ እርሱም አባቱ የሠራውን ኀጢአት አይቶ ቢፈራ፥ እንደርሱም ባይሠራ፥'),
  ('7a608b37-e7a6-5379-add6-aa60fa0b02f7', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 15, 15, 'በተራራ ላይ ባይበላ፥ ዐይኖቹንም ወደ እስራኤል ቤት ጣዖታት ባያነሣ፥ የባልንጀራውንም ሚስት ባያረክስ፤'),
  ('4b8d8e0d-b1a3-5ba6-a81a-1a5bb3f13549', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 16, 16, 'ሰውንም ባያስጨንቅ፥ መያዣውንም ባይወስድ፥ ባይቀማም፥ ከእንጀራውም ለተራበ ቢሰጥ፥ ለተራቈተውም ልብስን ቢያለብስ፥'),
  ('5556f5ec-8335-57e9-aca0-15108d9b05e7', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 17, 17, 'እጁንም ከዐመፅ ቢመልስ፥ አራጣንም አትርፎ ባይወስድ፥ ፍርዴንም ቢያደርግ፥ በትእዛዜም ቢሄድ፥ እርሱ ፈጽሞ በሕይወት ይኖራል እንጂ በአባቱ ኀጢአት አይሞትም።'),
  ('5d789c00-dfd3-5f1b-afe5-86f207a5e2dd', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 18, 18, 'አባቱ ግን ፈጽሞ በድሎአልና፥ ወንድሙንም ቀምቶአልና፥ በሕዝቡም መካከል ክፉን ነገር አድርጎአልና እነሆ እርሱ በበደሉ ይሞታል።'),
  ('24104e7a-a8be-58d8-af81-3c84c19bbd1a', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 19, 19, '“እናንተ ግን፦ ልጅ የአባቱን ኀጢአት ስለ ምን አይሸከምም? ትላላችሁ። ልጅ ፍርድንና ቅን ነገርን በአደረገ፥ ትእዛዜንም ሁሉ በጠበቀና በአደረገ ጊዜ ፈጽሞ በሕይወት ይኖራል።'),
  ('35942eab-ce82-5bd8-a9a2-42197e04f4da', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 20, 20, 'ኀጢአትን የምትሠራ ነፍስ እርስዋ ትሞታለች፤ ልጅ የአባቱን ኀጢአት አይሸከምም፤ አባትም የልጁን ኀጢአት አይሸከምም፤ የጻድቁ ጽድቅ በራሱ ላይ ይሆናል፤ የኀጢአተኛውም ኀጢአት በራሱ ላይ ይሆናል።'),
  ('da583d40-87a0-5491-af2f-358f13371ebe', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 21, 21, '“ኀጢአተኛውም ከአደረጋት ኀጢአት ሁሉ ቢመለስ፥ ትእዛዜንም ሁሉ ቢጠብቅ፥ ፍርድንና ቅን ነገርንም ቢያደርግ ፈጽሞ በሕይወት ይኖራል እንጂ አይሞትም።'),
  ('21ff8edf-9f2a-52a8-a236-b236bd37810b', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 22, 22, 'የበደለው በደል ሁሉ አይታሰብበትም፤ በሠራው ጽድቅ በሕይወት ይኖራል።'),
  ('ac409c04-e4a6-56c1-ad8f-1d587b041d9e', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 23, 23, 'በውኑ ኀጢአተኛ ይሞት ዘንድ መፍቀድን እፈቅዳለሁን? ይላል ጌታ እግዚአብሔር፤ ከክፉ መንገዱ ይመለስና በሕይወት ይኖር ዘንድ ነው እንጂ።'),
  ('e335c288-34f1-5097-ae5d-abfbf2eda0c7', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 24, 24, 'ጻድቁ ግን ከጽድቁ ቢመለስ፥ ኀጢአትንም ቢሠራ፥ ኀጢአተኛውም እንደሚያደርገው ርኵሰት ሁሉ ቢያደርግ፥ በሕይወት ይኖራልን? የሠራው ጽድቅ ሁሉ አይታሰብለትም፤ በአደረገው ዐመፅና በሠራት ኀጢአት በዚያች ይሞታል።'),
  ('e484aacc-2fe7-5170-a3c2-4350301a80c5', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 25, 25, '“እናንተ ግን፦ የጌታ መንገድ የቀናች አይደለችም ትላላችሁ። የእስራኤል ቤት ሆይ! እንግዲህ ስሙ፤ በውኑ መንገዴ የቀናች አይደለችምን? ይልቅስ የእናንተ መንገድ ያልቀናች አይደለችምን?'),
  ('4cab6862-7d71-5ae9-a602-c8864328a0a3', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 26, 26, 'ጻድቁ ከጽድቁ ቢመለስ፥ ኀጢአትንም በሠራ ጊዜ፥ በዚያ ቢሞት፥ እርሱ በአደረገው በደል ይሞታል።'),
  ('fede9e35-74b8-5a69-ab3b-f2e0101ec19a', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 27, 27, 'ኀጢአተኛውም ከሠራው ኀጢአት ቢመለስ፥ ፍርድንና ቅን ነገርንም ቢያደርግ ነፍሱን ይጠብቃል።'),
  ('59307624-c600-5d8e-ac85-bd74ddf1fb08', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 28, 28, 'ከሠራው ሁሉ በደል አይቶ ተመልሶአልና ፈጽሞ በሕይወት ይኖራል እንጂ አይሞትም።'),
  ('9fb7f003-3301-5ebc-a3b3-72c3e650c9a1', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 29, 29, 'ነገር ግን የእስራኤል ቤት፦ የጌታ መንገድ የቀናች አይደለችም ይላሉ። የእስራኤል ቤት ሆይ! በውኑ መንገዴ የቀናች አይደለችምን? ይልቅስ የእናንተ መንገድ ያልቀናች አይደለችምን?'),
  ('e0b56871-892e-55b6-a67b-0a3ddc56ee80', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 30, 30, 'የእስራኤል ቤት ሆይ! ስለዚህ እንደ መንገዱ በየሰዉ ሁሉ እፈርድባችኋለሁ፥ ይላል ጌታ እግዚአብሔር፤ ንስሓ ግቡ፤ ኀጢአትም ዕንቅፋት እንዳይሆንባችሁ ከኀጢአታችሁ ሁሉ ተመለሱ።'),
  ('93a8e530-afde-5943-ab4b-2e9af14e128b', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 31, 31, 'የበደላችሁትን በደል ሁሉ ከእናንተ ጣሉ፤ አዲስ ልብና አዲስ መንፈስንም ለእናንተ አድርጉ፤ የእስራኤል ቤት ሆይ! ስለ ምን ትሞታላችሁ?'),
  ('f431c1cd-327a-55e8-ae65-1c6848590423', '25de0d69-d7b8-5a00-ae03-90a973d15930', 'd1a5a1f2-f509-5ea2-a08f-43eeef4641aa', 32, 32, 'የምዋቹን ሞት አልፈቅድምና፥ ይላል ጌታ እግዚአብሔር፤ ስለዚህ በንስሓ ተመለሱና በሕይወት ኑሩ።'),
  ('8b6c57f7-2fe7-5928-a49a-5e20d38cc54e', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 1, 1, '“አንተም ለእስራኤል አለቃ ይህን ሙሾ አሙሽለት፤'),
  ('6820a28a-178b-5f59-a8a7-ac44d0efc93e', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 2, 2, 'እንዲህም በል፦ እናትህ ምን ነበረች? እንስት አንበሳ ነበረች፤ በአንበሶች መካከል ተጋደመች፤ በደቦል አንበሶችም መካከል ግልገሎችዋን አሳደገች።'),
  ('760306b9-9256-50e9-a52c-2fb72c14b7a0', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 3, 3, 'ከግልገሎችዋም አንዱን አወጣች፤ እርሱም ደቦል አንበሳ ሆነ፤ ንጥቂያንም ተማረ፤ ሰዎችንም ነጥቆ በላ።'),
  ('11897ca3-a632-59ff-a7e0-b19ea270877f', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 4, 4, 'አሕዛብም ስለ እርሱ ሰሙ፤ እርሱም በጕድጓዳቸው ተያዘ፤ በሰንሰለትም አስረው ወደ ግብፅ ምድር ወሰዱት።'),
  ('dfac256e-bf22-5bfe-a7f9-b768830f8b20', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 5, 5, 'እርስዋም ከእርስዋ እንደ ወሰዱት ባየች ጊዜ ኀይልዋ ጠፋ፤ ከግልገሎችዋም ሌላን ወስዳ ደቦል አንበሳ አደረገችው።'),
  ('cc2ff9f6-8d95-55fe-ad0a-5171a850796a', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 6, 6, 'እርሱም በአንበሶች መካከል አደገ፤ ደቦል አንበሳም ሆነ፤ ንጥቂያም ተማረ፤ ሰዎችንም ነጥቆ በላ።'),
  ('7b93d053-8833-591d-a59f-be982c3b1572', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 7, 7, 'ተዘልሎም ይኖራል፤ ከተሞቻቸውንም አጠፋ፤ ሀገራቸውንም አፈረሰ፤ ከግሣቱም ድምፅ የተነሣ ምድርና ሞላዋ ጠፋች።'),
  ('89bb164a-fe6d-553d-ae8e-6e0b859f0fc1', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 8, 8, 'አሕዛብም በዙሪያው ከየሀገሩ ሁሉ ተሰበሰቡበት፤ መረባቸውንም በእርሱ ላይ ዘረጉ፤ በወጥመዳቸውም ተያዘ።'),
  ('3ed92696-4013-5138-a461-1724ab8a6c48', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 9, 9, 'በሰንሰለትም አስረው በቀፎ ውስጥ አኖሩት፤ ወደ ባቢሎንም ንጉሥ አመጡት፤ ድምፁም በእስራኤል ተራሮች ላይ ከዚያ ወዲያ እንዳይሰማ ወደ ግዞት ቤት አገቡት።'),
  ('fa09176b-4ccb-5b08-a832-c03627b35b67', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 10, 10, '“እናትህ በውኃ አጠገብ እንደ ተተከለች እንደ ወይን ግንድና እንደ ጽጌረዳ ነበረች፤ ከውኃም ብዛት የተነሣ የምታፈራና የምትሰፋ ሆነች።'),
  ('b3af6f56-0dac-5d16-a48a-c4ecbb97d739', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 11, 11, 'ከእርስዋም የጸናች በትር ወጣች፤ ለገዥዎችም በትር ሆነች፤ በዛፎችም መካከል ቁመቷ ረዘመ፤ በቅርንጫፎችዋም ርዝመቷ ታየ።'),
  ('99673491-9893-5fa1-a63a-66a26f6445f1', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 12, 12, 'ነገር ግን በመዓት ተነቀለች፤ ወደ መሬትም ተጣለች፤ የሚያቃጥልም ነፋስ ፍሬዋን አደረቀ፤ ብርቱዎች በትሮችዋም ተሰበሩና ደረቁ፤ እሳትም በላቻቸው።'),
  ('6cc42010-e9cd-567c-a742-061c3b841a6d', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 13, 13, 'አሁንም በምድረ በዳ፥ በደረቅና በተጠማች መሬት ተተከለች።'),
  ('a0ac13ce-cbff-52d3-a3a3-d0592a891299', 'd7ebbc2d-9e56-5c6c-a839-a0d6d07fe10c', 'aeb7a2df-93c9-5553-a6e7-45e9230a0767', 14, 14, 'ከተመረጡት ጫፎችዋም በትር እሳት ወጣች፤ ፍሬዋንም በላች፤ የነገሥታትም በትር ይሆን ዘንድ የበረታ በትር የለባትም።” ይህ ሙሾ ነው፤ ለልቅሶም ይሆናል።'),
  ('d9dad760-78a5-5b76-a489-5ef1774638a6', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 1, 1, 'እንዲህም ሆነ፥ በሰባተኛው ዓመት በአምስተኛው ወር ከወሩም በዐሥረኛው ቀን እግዚአብሔርን ይጠይቁ ዘንድ ከእስራኤል ሽማግሌዎች ሰዎች መጡ፤ በፊቴም ተቀመጡ።'),
  ('54e426bf-5a06-575f-adaa-9e95b1f75866', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 2, 2, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('e464aa26-0f07-5110-a2a3-186ac4f894a7', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 3, 3, '“የሰው ልጅ ሆይ! ለእስራኤል ሽማግሌዎች ተናገር፤ እንዲህም በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ እኔን ትጠይቁ ዘንድ መጥታችኋልን? እኔ ሕያው ነኝ! አልመልስላችሁም፥” ይላል ጌታ እግዚአብሔር።'),
  ('54645ee6-5207-5a06-aeec-4c20154b233f', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 4, 4, 'ነገር ግን በቀልን እበቀላቸዋለሁ፤ የሰው ልጅ ሆይ! የአባቶቻቸውን ኀጢአት አስታውቃቸው።'),
  ('cb9dbbc2-bfd8-5b8f-aa69-b17bb95a7e3a', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 5, 5, 'እንዲህም በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ የእስራኤልን ቤት በመረጥሁበት፥ ለያዕቆብም ቤት ዘር በታወቅሁበት ቀን፥ በግብፅም ምድር በተገለጥሁላቸው ጊዜ እጄን አንሥቼ፦ እኔ እግዚአብሔር አምላካችሁ ነኝ አልኋቸው።'),
  ('b6fcf4ad-8772-5875-aeef-db2c892c9ac1', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 6, 6, 'በዚያ ቀን ከግብፅ ምድር ወዳዘጋጀሁላቸው፥ ወተትና ማር ወደምታፈስሰው፥ ከምድር ሁሉ ወደምትበልጥ ምድር አወጣቸው ዘንድ እጄን አነሣሁ።'),
  ('a3757d41-8c01-5f11-a280-51f2abbbebbb', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 7, 7, 'እኔም፦ ከእናንተ እያንዳንዱ ርኵሰቱን ከፊቱ ያስወግድ፤ በግብፅም ጣዖታት አትርከሱ፤ እኔ እግዚአብሔር አምላካችሁ ነኝ አልኋቸው።'),
  ('cc18c556-32ae-5190-adfd-f3eef8e8afd2', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 8, 8, 'እነርሱ ግን ዐመፁብኝ፤ ይሰሙኝም ዘንድ አልወደዱም፤ ሁሉም እያንዳንዱ ርኵሰቱን ከፊቱ አላስወገደም፤ የግብጽንም ጣዖታት አልተወም፤ በዚህም ጊዜ በግብፅ ምድር መካከል ቍጣዬን እፈጽምባቸው ዘንድ መዓቴን አፈስስባቸዋለሁ አልሁ።'),
  ('b2a47ea3-b8d0-5a87-a82c-a6e6fc44baef', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 9, 9, 'ነገር ግን በመካከላቸው በአሉ፥ ከግብጽም ምድር አወጣቸው ዘንድ በፊታቸው በተገለጥሁላቸው በአሕዛብ ፊት ስሜ እንዳይረክስ ብዬ ስለ ስሜ ሠራሁ።'),
  ('48071ff4-a0ba-591c-a83d-fe90937648f0', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 10, 10, '“ከግብፅም ምድር አወጣኋቸው ወደ ምድረ በዳም አመጣኋቸው።'),
  ('001da4cb-16f8-577b-a29e-c4435c7936c9', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 11, 11, 'ሰው ቢያደርገው በሕይወት የሚኖርበትን ሥርዐቴንም ሰጠኋቸው፤ ፍርዴንም አስታወቅኋቸው።'),
  ('bfdc1e68-4ef3-5c3e-a72e-c3e372420d2d', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 12, 12, 'የምቀድሳቸውም እኔ እግዚአብሔር እንደ ሆንሁ ያውቁ ዘንድ፥ በእኔና በእነርሱ መካከል ምልክት ይሆኑ ዘንድ ሰንበታቴን ሰጠኋቸው።'),
  ('77c348c3-06c1-5be4-a03d-d25002ef2af4', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 13, 13, 'ነገር ግን የእስራኤልን ቤት በምድረ በዳ በትእዛዜ ሂዱ አልኋቸው፤ አልሄዱምም፤ ሰው ቢያደርገው ኖሮ በሕይወት የሚኖርበትንም ሕጌን አፈረሱ፤ ሰንበታቴንም ፈጽመው አረከሱ። በዚህም ጊዜ አጠፋቸው ዘንድ ቍጣዬን በምድረ በዳ አፈስስባቸዋለሁ አልሁ።'),
  ('8ef58bfa-84e5-5d82-a7a4-1a736e4cc5ce', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 14, 14, 'ነገር ግን በፊታቸው ባወጣኋቸው በአሕዛብ ፊት ከሁሉ በላይ የሚሆን ስሜን እንዳያረክሱ አደረግሁ።'),
  ('19dbb7b1-fcc6-5242-a19a-6d456af7a228', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 15, 15, 'ወተትና ማርም ወደምታፈስሰው ከምድር ሁሉ ወደምታምር ወደ ሰጠኋቸው ምድር እንዳላገባቸው በምድረ በዳ በእነርሱ ላይ ፈጽሜ እጄን አነሣሁ።'),
  ('6363a320-909f-54b2-a29e-f22c769152c1', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 16, 16, 'ፍርዴንም ጥሰዋልና፥ በሥርዐቴም አልሄዱምና፥ ሰንበታቴንም አርክሰዋልና በልባቸው ዐሳብ ሄዱ።'),
  ('5f20abe8-b5d4-5dee-a3db-aa78baa70482', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 17, 17, 'ነገር ግን እኔ እንደ አላጠፋቸው፥ በምድረ በዳም ፈጽሜ እንደ አልጨርሳቸው ዐይኔ ራራችላቸው።'),
  ('8c8364a5-3af7-532a-ad4d-db894b619d76', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 18, 18, '“ለልጆቻቸውም በምድረ በዳ እንዲህ አልኋቸው፦ በአባቶቻችሁ ልማድ አትሂዱ፤ ሥርዐታቸውንም አትጠብቁ፤ በበደላቸውም አንድ አትሁኑ፤ አትርከሱም።'),
  ('b9bd4737-000c-50e2-a178-fc0e9ca39a90', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 19, 19, 'እኔ እግዚአብሔር አምላካችሁ ነኝ፤ በትእዛዜ ሂዱ፤ ፍርዴንም ጠብቁ፤ አድርጓትም።'),
  ('5fb71336-bc84-58c6-a574-dc9d09801f61', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 20, 20, 'ሰንበታቴንም ቀድሱ፤ እኔም እግዚአብሔር አምላካችሁ እንደ ሆንሁ ታውቁ ዘንድ በእኔና በእናንተ መካከል ምልክት ይሁኑ።'),
  ('75669b11-2325-562b-a227-49e1cb613a37', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 21, 21, 'ልጆቻቸው ግን አማረሩኝ፤ ሰው ቢያደርገው ኖሮ በሕይወት የሚኖርበትን ፍርዴን ጠብቀው አላደረጉትም፤ በሥርዐቴም አልሄዱም፤ ሰንበታቴንም አረከሱ፤ በዚህም ጊዜ፦ መዓቴን አፈስስባቸዋለሁ፤ ቍጣዬንም በምድረ በዳ እፈጽምባቸዋለሁ አልሁ።'),
  ('a6d66964-228a-5ee0-acc6-681e0fbeb610', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 22, 22, 'ነገር ግን በፊታቸው ባወጣኋቸው በአሕዛብ ፊት ከሁሉ የሚበልጠው ስሜ እንዳይረክስ አደረግሁ።'),
  ('101dd560-f3b6-50c4-abf3-6888290b6933', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 23, 23, 'ደግሞም ወደ አሕዛብ እበትናቸው ዘንድ፥ በሀገሮችም እበትናቸው ዘንድ በምድረ በዳ በእነርሱ ላይ እጄን አነሣሁ።'),
  ('59739258-c570-5b6e-a511-e88a71036063', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 24, 24, 'ፍርዴን አላደረጉምና፥ ሥርዐቴንም ጥሰዋልና፥ ሰንበታቴንም አርክሰዋልና፥ ዐይኖቻቸውም የአባቶቻቸውን ዐሳብ ተከትለዋልና።'),
  ('46fae58e-a78c-52e1-a072-e902bc4377eb', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 25, 25, 'ደግሞም መልካም ያልሆነውን ሥርዐት፥ በሕይወት የማይኖሩበትንም ፍርድ ሰጠኋቸው።'),
  ('2e41c0e3-9530-5176-a4aa-1c63ec56c51c', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 26, 26, 'እኔም እግዚአብሔር እንደ ሆንሁ እንዲያውቁ አጠፋቸው ዘንድ ማኅፀን የሚከፍተውን ሁሉ በአመጡልኝ ጊዜ፥ በመባቸው አረከስኋቸው።'),
  ('0368675c-a32b-50bc-a775-3d621cf5299f', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 27, 27, '“ስለዚህ የሰው ልጅ ሆይ! ለእስራኤል ቤት ተናገር፤ እንዲህም በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ በዚህም ደግሞ አባቶቻችሁ በአደረጉት ዐመፅ አስቈጡኝ።'),
  ('a82dfb3f-0696-5d6c-a1e1-2aa1473ab153', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 28, 28, 'እሰጣቸውም ዘንድ እጄን ወደ አነሣሁላቸው ምድር አገባኋቸው፤ ከፍ ያለውን ኮረብታ ሁሉ፥ ቅጠላማውንም ዛፍ ሁሉ አዩ፤ በዚያም ለጣዖቶቻቸው መሥዋዕታቸውን ሠዉ፤ በዚያም የሚያስቈጣኝን፤ ቍርባናቸውን አቀረቡ፤ በዚያም ደግሞ ጣፋጩን ሽታቸውን አደረጉ፤ በዚያም የመጠጥ ቍርባናቸውን አፈሰሱ።'),
  ('bb19a09d-84fe-5743-a0c4-b1c60ff1d813', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 29, 29, 'እኔም፦ እናንተ ወደ እርሱ የምትሄዱበት ከፍታ ምንድን ነው? አልኋቸው። እስከ ዛሬም ድረስ ስሙ ባማ ተብሎ ተጠርቶአል።'),
  ('2a8490ae-dd38-54f9-a07b-30bf6813d9cb', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 30, 30, 'ስለዚህ ለእስራኤል ቤት እንዲህ በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ እናንተ በአባቶቻችሁ ኀጢአት ረከሳችሁ፤ አመነዘራችሁ፤ ርኵሰታቸውንም ተከተላችሁ።'),
  ('507a5e7a-b9e9-597e-a663-ed94e379c10e', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 31, 31, 'ቍርባናችሁን በአቀረባችሁ ጊዜ፥ ልጆቻችሁንም በእሳት ባሳለፋችሁ ጊዜ፥ እስከ ዛሬ ድረስ በዐሳባችሁ ሁሉ ረከሳችሁ፤ የእስራኤል ቤት ሆይ! እኔስ እመልስላችኋለሁን? እኔ ሕያው ነኝ! አልመልስላችሁም፥” ይላል ጌታ እግዚአብሔር።'),
  ('f2e34227-371c-5ae1-aae3-256cfbdaa2a1', 'aed92190-de9d-5f36-a289-314cc0e7c231', '8f276e31-02d1-5fe0-aeab-48fdd69d5c90', 32, 32, 'ለእናንተም፦ እንደ አሕዛብና እንደ ምድር ወገኖች እንሆናለን፤ እንጨትና ድንጋይም እናመልካለን የሚል ከልባችሁ የወጣ ዐሳብ አይፈጸምላችሁም።'),
  ('7eb24b0c-ccbd-5c87-af77-b5b170228b45', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 1, 33, '“እኔ ሕያው ነኝ! በበረታች እጅና በተዘረጋች ክንድ፥ በፈሰሰችም መዓት እነግሥባችኋለሁ፥ ይላል ጌታ እግዚአብሔር።'),
  ('31c70169-46de-5f2b-abad-5b6e2a60514f', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 2, 34, 'ከአሕዛብም ዘንድ አወጣችኋለሁ፤ ከተበተናችሁባትም ሀገር ሁሉ በበረታች እጅና በተዘረጋች ክንድ፥ በፈሰሰችም መዓት እሰበስባችኋለሁ።'),
  ('5a9d0251-b3e2-543e-a1e9-ba895654045f', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 3, 35, 'ወደ አሕዛብም ምድረ በዳ አመጣችኋለሁ፤ በዚያም ፊት ለፊት ከእናንተ ጋር እፋረዳለሁ።'),
  ('f0de1f1e-59e4-5758-ac23-418656ea9c25', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 4, 36, 'በግብፅ ምድረ በዳ ከአባቶቻችሁ ጋር እንደ ተፋረድሁ እንዲሁ ከእናንተ ጋር እፋረዳለሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('72c40e6a-ac55-5495-a424-75ae7cc4d760', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 5, 37, 'ከበትሬም በታች አሳልፋችኋለሁ፤ በቍጥርም እወስዳችኋለሁ።'),
  ('f61beb4d-e5bb-5861-afae-19ae9dcc35e3', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 6, 38, 'ከእናንተም ዘንድ ዐመፀኞችንና የበደሉኝን እለያለሁ፤ ከኖሩባትም ምድር አወጣቸዋለሁ፤ ወደ እስራኤል ምድር ግን አይገቡም፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('b40f656b-747e-5124-a28c-905044494448', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 7, 39, 'እናንተ የእስራኤል ቤት ሆይ፥ ጌታ እግዚአብሔር እንዲህ ይላል፦ ሁላችሁ ኀጢአታችሁን ተዉ፤ ከዚህ በኋላ ስሙኝ፤ ቅዱሱን ስሜንም ከእንግዲህ ወዲህ በኀጢአታችሁና በመባችሁ አታርክሱ።'),
  ('20ecc9ef-e81a-574f-a0cf-52d248f531ce', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 8, 40, '“በቅዱሱ ተራራዬ፥ ከፍ ባለው በእስራኤል ተራራ ላይ፥ ይላል ጌታ እግዚአብሔር፤ በዚያ የእስራኤል ቤት ሁሉ ሁላቸው ለዘለዓለም ይገዙልኛል፤ በዚያም እቀበላችኋለሁ፤ በዚያም ቀዳምያታችሁን፥ በኵራታችሁንም፥ የቀደሳችሁትንም ነገር ሁሉ እጐበኛለሁ።'),
  ('049960d1-9cd6-5033-aeda-68a307170888', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 9, 41, 'ከአሕዛብ ዘንድ ባወጣኋችሁ ጊዜ፥ ከተበተናችሁባትም ሀገር ሁሉ በሰበሰብኋችሁ ጊዜ እንደ ጣፋጭ ሽታ እቀበላችኋለሁ፤ በአሕዛብም ፊት እቀደስባችኋለሁ።'),
  ('d678c8bd-d677-5e70-a008-6c300b818c42', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 10, 42, 'ለአባቶቻችሁም እሰጣት ዘንድ እጄን ወደ አነሣሁላቸው ምድር ወደ እስራኤል ሀገር ባገባኋችሁ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('f1a88d95-ccf7-5dd7-a980-db1a08e4f02c', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 11, 43, 'በዚያም የረከሳችሁባትን መንገዳችሁንና ሥራችሁን ሁሉ ታስባላችሁ፤ በፊታችሁም አይታችሁ ስለ ሠራችሁት ክፋታችሁ ሁሉ ታፍራላችሁ።'),
  ('f358c459-b502-53ca-acdc-83849e611701', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 12, 44, 'የእስራኤል ቤት ሆይ! እንደ ክፉ መንገዳችሁና እንደ ርኩስ ሥራችሁ ሳይሆን ስለ ስሜ ስል በሠራሁላችሁ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('d60b5ef9-4fdd-5de5-ab3c-917fd321e51f', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 13, 45, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፤'),
  ('51dccf79-84e2-555c-a04a-d2649b1b55f4', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 14, 46, '“የሰው ልጅ ሆይ! ፊትህን ወደ ቴማን አቅና፤ ወደ ዳሮምም ተመልከት፤ በናጌብም ምድረ በዳ ዱር ንጉሥ ላይ ትንቢት ተናገር።'),
  ('297fb0a2-3b62-5622-a2af-42f957686ddb', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 15, 47, 'ለናጌብም ዱር እንዲህ በለው፦ የእግዚአብሔርን ቃል ስማ፤ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ በአንተ ውስጥ እሳትን አነድዳለሁ፤ በውስጥህም ያለውን የለመለመውንና የደረቀውን ዛፍ ሁሉ ይበላል፤ የሚቃጠለውም ነበልባል አይጠፋም፤ ከደቡብም ጀምሮ እስከ ሰሜን ድረስ ፊት ሁሉ ይቃጠልበታል።'),
  ('221e08d3-7aea-5d88-a687-fd0fd144a1ad', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 16, 48, 'እኔም እግዚአብሔር እንዳነደድሁት ሥጋ ለባሽ ሁሉ ያያል፥ እርሱም አይጠፋም።'),
  ('dd8a5f01-1899-5227-a155-6b3bdb9408bd', 'aed92190-de9d-5f36-a289-314cc0e7c231', '4e0365e7-4d0c-5be4-a2e1-5e6aa4d7c3a2', 17, 49, 'እኔም፦ ጌታ እግዚአብሔር ሆይ፥ ይህ አይሁን አልሁ፤ እነርሱ ግን፦ ይህ የነገረን ምሳሌ አይደለምን? ይሉኛል።”'),
  ('1017a4dd-5d26-5dc6-a6fb-2afb5fd87274', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('30b396dc-6ebe-5b15-a6bc-6c921108fb5a', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 2, 2, '“የሰው ልጅ ሆይ! ስለዚህ ትንቢት ተናገር፤ ፊትህን ወደ ኢየሩሳሌም አቅና፤ ወደ መቅደሶችም ተመልከት፤ በእስራኤልም ምድር ላይ ትንቢት ተናገር።'),
  ('b830fc9f-c1cf-50b6-a678-fed4f4666764', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 3, 3, 'ለእስራኤልም ምድር እንዲህ በል፦ እግዚአብሔር እንዲህ ይላል፦ እነሆ በአንቺ ላይ ነኝ፤ ሰይፌንም ከሰገባው እመዝዘዋለሁ፤ ጻድቁንና ኃጥኡን ከአንቺ ዘንድ አጠፋለሁ።'),
  ('c6cfa333-5c20-5911-a47f-48c131d88ceb', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 4, 4, 'እኔም ጻድቁንና ኃጥኡን ከአንቺ ዘንድ ስለማጠፋ፥ ስለዚህ ሰይፌ ከደቡብ ጀምሮ እስከ ሰሜን ድረስ በአለ በሥጋ ለባሽ ሁሉ ላይ ከሰገባው ይመዘዛል።'),
  ('35fd898e-1075-52bb-a822-a130b5226c65', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 5, 5, 'ሥጋ ለባሹም ሁሉ እኔ እግዚአብሔር ሰይፌን ከሰገባው እንደ መዘዝሁ ያውቃል፤ እርሱም ደግሞ አይመለስም።'),
  ('7dd6b81d-19e9-519e-ac59-bc963a4962ac', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 6, 6, 'ስለዚህ አንተ የሰው ልጅ ሆይ! ወገብህን በማጕበጥ አልቅስ፤ በፊታቸውም ምርር ብለህ አልቅስ።'),
  ('bc7d2d49-ab22-53d7-aa66-c5e200d0f7ec', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 7, 7, 'እነርሱም፦ ስለ ምን ታለቅሳለህ? ቢሉህ አንተ እንዲህ በላቸው፦ ስለሚመጣው ወሬ ነው፤ ልብም ሁሉ ይቀልጣል፤ እጆችም ሁሉ ይዝላሉ፤ ሥጋና መንፈስ ሁሉ ይደክማል፤ ከጕልበትም እዥ ይፈስሳል፤ እነሆ ይመጣል፤ ይፈጸማልም፥” ይላል ጌታ እግዚአብሔር።'),
  ('c52be9ac-68b4-539d-a7da-d909dc1b8ea8', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 8, 8, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('0b172a9a-03f3-557f-a28e-dba46f5dad55', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 9, 9, '“የሰው ልጅ ሆይ! እግዚአብሔር እንዲህ ይላል ብለህ ትንቢት ተናገር፤ ሰይፍ ሰይፍ የተሳለች፥ የተሰነገለችም ሁኚ።'),
  ('7ba1537f-34fb-521b-a810-5b002c27641a', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 10, 10, 'ወግተሽ ትገድሊ ዘንድ፥ ታብረቀርቂም ዘንድ ተሳዪ፤ ትገድሊም ዘንድ፥ ዕንጨቱንም ሁሉ ትጥዪ ዘንድ ጨክኚ፤'),
  ('ab30d4be-e609-5d46-a832-0e5ba43daf9d', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 11, 11, 'በእጁም ይይዛት ዘንድ ለአርበኛ ተሰጠች፤ ሰይፍ በገዳይ እጅ እንድትሰጥ ተሳለችና ተዘጋጀች።'),
  ('b82c92d9-c2e9-54b9-a2b7-d7962be6e17f', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 12, 12, 'የሰው ልጅ ሆይ! በሕዝቤ ላይ ነውና፥ በእስራኤልም አለቆች ሁሉ ላይ ነውና ጩኽ፤ ዋይም በል፤ እነርሱ ከሕዝቤ ጋር ለሰይፍ ተሰጥተዋል፤ ስለዚህ እጅህን ጽፋ።'),
  ('ad0052ea-d4c9-5ad0-a765-400b66689505', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 13, 13, 'እውነት ሆኖአልና፤ የራቁ ሕዝቤ ምን ሆኑ? የሉምና፥ ይላል ጌታ እግዚአብሔር።'),
  ('fddbedae-a924-59b2-a305-2e8585f6a7b2', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 14, 14, 'ስለዚህ አንተ የሰው ልጅ ሆይ! ትንቢት ተናገር፤ እጅህን በእጅህ ላይ አጨብጭብ፤ የተገደሉ ሰዎች ሰይፍ ሦስት ጊዜ ይደጋግም፤ ይኸውም የታላቅ ግድያ ሰይፍ ነው፤ ያስደነግጣቸዋልም።'),
  ('4281262d-051c-5ef7-a632-2c139f55cf32', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 15, 15, 'ልባቸው እንዲቀልጥ፥ መሰናክላቸውም እንዲበዛ የሚገድለውን ሰይፍ በበሮቻቸው ሁሉ ላይ አድርጌአለሁ፤ ወዮ! ያብረቀርቅ ዘንድ ተሰንግሏል፤ ይገድልም ዘንድ ተስሏል።'),
  ('807f84a8-b5ab-5a96-ae45-3e211b482215', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 16, 16, 'ፊትህ ወደ አቀናው ወደ ቀኝ ወይም ወደ ግራ ሂድ።'),
  ('d2c4e22d-b6c4-5049-a981-173d88141c25', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 17, 17, 'እኔ ደግሞ እጄን በእጄ ላይ አጨበጭባለሁ፤ መዓቴንም እልካለሁ፤ እኔ እግዚአብሔር ተናግሬአለሁ።”'),
  ('29717fde-5c30-5c2f-a1e7-4e9ddba61c2b', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 18, 18, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('a3226fc4-28e9-5853-a60a-1624a813f263', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 19, 19, '“አንተም የሰው ልጅ ሆይ! የባቢሎን ንጉሥ ሰይፍ የምትገባባቸው ሁለት መንገዶችን አድርግ፤ ሁለቱም ከአንዲት ምድር ይውጡ፤ ምልክትንም አድርግ፤ በከተማዪቱ መንገድ ራስ ላይም አድርገው።'),
  ('9ffbbc49-568d-5381-ae44-f56b4f6957aa', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 20, 20, 'ሰይፍ ወደ አሞን ልጆች ሀገር፥ ወደ ራባት፥ ወደ ይሁዳም፥ ወደ ኢየሩሳሌምም፥ በመካከልዋ ይገባ ዘንድ መንገድን አድርግ።'),
  ('d5f7f895-3f31-5b6f-a737-9f7f6e86d7b3', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 21, 21, 'የባቢሎን ንጉሥ ምዋርቱን ያምዋርት ዘንድ፥ በትሩን ያነሣ ዘንድ፥ ጣዖቱንም ይጠይቅ ዘንድ በሁለት መንገዶች ራስ ላይ ይቆማል።'),
  ('3222e29d-9c03-5f36-ae69-d96650515c47', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 22, 22, 'የቅጥሩን ማፍረሻ ያደርግ ዘንድ፥ አፍንም በጩኸት ይከፍት ዘንድ፥ በውካታም ድምፅን ከፍ ያደርግ ዘንድ፥ የቅጥሩን ማፍረሻ በበሮች ላይ ያደርግ ዘንድ፥ አፈርን ይደለድል ዘንድ፥ ምሽግም ይሠራ ዘንድ የኢየሩሳሌም ምዋርት በቀኝ እጁ ውስጥ ነበረ።'),
  ('c57a7f0b-8daf-53f4-ac46-fc92ef6db4e8', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 23, 23, 'እርሱ በፊታቸው ምዋርትን ያምዋርታል፤ ኀጢአታቸውንም ዐስቦ ሰባት ሱባዔ ይቈጥርባቸዋል።'),
  ('4235b1bc-064e-5906-a7d6-bf2d3b48fbfa', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 24, 24, '“ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ኀጢአታችሁን ስለ ዐሰባችሁ፥ መተላለፋችሁም ስለ ተገለጠ፥ ኀጢአታችሁም በሥራችሁ ሁሉ ስለ ታየ፥ እናንተም ስለ ታሰባችሁ፥ በእርሱ ትያዛላችሁ።'),
  ('49554c2f-2157-5ccd-aae6-2d794f4dab01', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 25, 25, 'አንተም ቀንህና የኀጢአትህ ቀጠሮ ጊዜ የደረሰብህ፥ ርኩስ ኀጢአተኛ የእስራኤል አለቃ ሆይ!'),
  ('e6f4d51f-c026-5e58-ac1d-49c32fb110a4', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 26, 26, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ መጠምጠሚያውን አውልቅ፤ ዘውዱንም አርቅ፤ ይህ እንዲህ አይሆንም፤ የተዋረደውን ከፍ አድርግ፤ ከፍ ያለውንም አዋርድ።'),
  ('98127c69-7b3b-5cf1-aa3f-bf1b8c30e69d', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 27, 27, 'ባድማ፥ ባድማ፥ ባድማ አደርጋታለሁ፤ ፍርድ ያለው እስኪመጣ ድረስ ይህች ደግሞ አትሆንም፤ ለእርሱም እሰጣታለሁ፤'),
  ('36fb63c2-e196-5b33-a5df-e987a2b80343', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 28, 28, '“አንተም የሰው ልጅ ሆይ! ጌታ እግዚአብሔር ስለ አሞን ልጆችና ስለ ስድባቸው እንዲህ ይላል ብለህ ትንቢት ተናገር፤ ሰይፍ ሰይፍ ለመግደል ተመዝዞአል፤ ጨርሶም ያርድ ዘንድ ተሰንግሎአል በል።'),
  ('e88a5ecb-4606-5a21-a6f3-9df9eabb0847', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 29, 29, 'በተገደሉት ኀጢአተኞች አንገት ላይ ያኖሩህ ዘንድ ከንቱ ራእይን ሲያዩልህ፥ በሐሰት ምዋርትም ሲናገሩልህ፥ በኀጢአታቸው ቀጠሮ ጊዜ ቀናቸው ደረሰ።'),
  ('ffff009f-7c01-5685-af33-ea8f4a521f7b', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 30, 30, 'ወደ ሰገባውም መልሰው፤ በተፈጠርህባት ስፍራ አትደር፤ በተወለድህባትም ምድር እፈርድብሃለሁ።'),
  ('80cbbe11-9262-5cc8-a5f9-c65bf32b80de', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 31, 31, 'ቍጣዬንም አፈስስብሃለሁ፤ በመዓቴም እሳት አናፋብሃለሁ፤ ማጥፋትንም ለሚያውቁ ለጨካኞች ሰዎች እጅ አሳልፌ እሰጥሃለሁ።'),
  ('cd75e1b7-aeb3-5fa6-a136-09fccd3c477b', '4883fb31-9f8d-5510-a9bd-78714e0efcaf', 'eb585d89-55ee-5f1e-af46-b6efb142e8b0', 32, 32, 'ለእሳት ማገዶ ትሆናለህ፤ ደምህም በምድር መካከል ይፈስሳል፤ ደግሞም አትታሰብም፤ እኔ እግዚአብሔር ተናግሬአለሁና።”'),
  ('77178d06-ea9f-5656-acc7-0c09340dd1e8', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('afa04ec6-4e14-5dd3-a0af-f02ad3701a64', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 2, 2, '“አንተም የሰው ልጅ ሆይ! ደም በምታፈስስ ከተማ ላይ ትፈርዳለህን? ርኵሰቷን ሁሉ አስታውቃት።'),
  ('9987d614-4474-5a8b-addc-aae7e3366421', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 3, 3, 'እንዲህም በላት፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ጊዜሽ እንዲደርስ በመካከልሽ ደምን የምታፈስሺ፥ እንድትረክሺም በራስሽ ላይ ጣዖታትን የምታደርጊ ከተማ ሆይ!'),
  ('532eb8bd-8f88-565a-a4ad-6334402b94ee', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 4, 4, 'ባፈሰስሽው ደም በድለሻል፤ ባደረግሻቸውም ጣዖታት ረክሰሻል፤ ቀንሽንም አቀረብሽ፤ ዘመንሽንም አሳጠርሽ፤ ስለዚህ ለአሕዛብ መሰደቢያ፥ ለሀገሮችም ሁሉ መሳለቂያ አደረግሁሽ።'),
  ('728b9925-4b46-53c0-a376-fa6b144da480', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 5, 5, 'አንቺ ስምሽ የረከሰ፥ ኀጢአትም የሞላብሽ ሆይ! ወደ አንቺ የቀረቡና ከአንቺ የራቁ ይሳለቁብሻል።'),
  ('7ad6395c-4095-5562-a7c2-1d207f37c5ac', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 6, 6, '“እነሆ የእስራኤል ቤት አለቆች እያንዳንዳቸው ከዘመዶቻቸው ጋር ደም ያፈስሱ ዘንድ በአንቺ ውስጥ ተባበሩ።'),
  ('1ed9a757-bbb5-55e8-ab58-6d906ade3bd8', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 7, 7, 'በአንቺ ውስጥ አባትንና እናትን አቃለሉ፤ በመካከልሽ በመጻተኛው ላይ በደልን አደረጉ፤ በአንቺ ውስጥ ድሀ አደጉንና መበለቲቱን አስጨነቁ።'),
  ('0cbf9041-5508-53b5-a3ec-151505509898', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 8, 8, 'ቅድሳቴንም ናቁ፤ ሰንበታቴንም አረከሱ።'),
  ('d288a2cc-d8c2-5d1f-aab8-64f03f190909', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 9, 9, 'በውስጥሽ ደምን ያፈስሱ ዘንድ ሌቦች ሰዎች በአንቺ ውስጥ ነበሩ፤ በአንቺ ውስጥ በተራሮች ላይ በሉ፤ በመካከልሽም የማይገባ ነገርን አደረጉ።'),
  ('12750e91-8ca0-507b-a62e-9b8365d10488', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 10, 10, 'በአንቺ ውስጥ የአባቶቻቸውን ኀፍረተ ሥጋ ገለጡ፤ በአንቺም ውስጥ አደፍ ያለባትን አዋረዱ።'),
  ('a754740a-85f1-59ea-a814-8953be89c21b', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 11, 11, 'ሰውም ከባልንጀራው ሚስት ጋር ሰሰነ፤ አባትም የልጁን ሚስት በኀጢአት አረከሰ፤ በአንቺም ዘንድ ወንድም የአባቱን ልጅ እኅቱን አስነወረ።'),
  ('03a1eca0-5125-5c44-a79f-6dd1a590b175', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 12, 12, 'በአንቺ ውስጥ ደምን ያፈስሱ ዘንድ መማለጃን ተቀበሉ፤ በአንቺም አራጣና ትርፍ ወስደዋል፤ ቀማኛነትሽንና ኀጢአትሽን ፈጸምሽ፤ እኔንም ረሳሽኝ፥ ይላል ጌታ እግዚአብሔር።'),
  ('9957600a-b76b-5bf2-a0c8-287a510bd6a2', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 13, 13, '“ስለዚህ እነሆ አንቺ ባደረግሽው ሥራ፥ በመካከልሽም በነበረው ደም ላይ በእጄ አጨበጨብሁ።'),
  ('6ee7e1c2-0bfa-5074-a9d1-70788f4d20db', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 14, 14, 'እኔ በማደርግብሽ ወራት ልብሽ ይታገሣልን? ወይስ እጆችሽ ይጸናሉን? እኔ እግዚአብሔር ተናግሬአለሁ፤ አደርገውማለሁ።'),
  ('0deebff9-d586-5a00-afa5-ae4bda9b7e1c', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 15, 15, 'ወደ አሕዛብም እበትንሻለሁ፤ በሀገሮችም እዘራሻለሁ፤ ከአንቺም ርኵሰትሽ ይጠፋል።'),
  ('72f8b6ef-b13b-5ff5-ac42-3d9d67adbd7c', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 16, 16, 'በአሕዛብም ፊት ከአንቺ እወርሳለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('9bdfbe46-ced2-59ff-a990-b00050338245', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 17, 17, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('dcb1fe0a-73f1-5d92-ad86-ddacc6d8f1a3', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 18, 18, '“የሰው ልጅ ሆይ! የእስራኤል ቤት ሁሉ የተቀላቀሉ ናስና ቆርቆሮ፥ ብረትና እርሳስ ሆኑብኝ፤ በማጣሪያም መካከል የተቀላቀለ ብር ሆኑ።'),
  ('46f6a98a-018d-5be9-aed1-9487fbbeb52b', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 19, 19, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ሁላችሁ አተላ ሆናችኋልና ስለዚህ እነሆ በኢየሩሳሌም ውስጥ እሰበስባችኋለሁ።'),
  ('ce7d9d69-b95a-51cb-ab9a-aba53c774014', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 20, 20, 'እንዲያቀልጡት እሳት ያናፉበት ዘንድ ብርንና መዳብን፥ ብረትንና እርሳስን፥ ቆርቆሮንም በከውር እንደሚሰበስቡ፥ እንዲሁ በቍጣዬና በመዓቴ እሰበስባችኋለሁ፤ በዚያም ውስጥ እጨምራችኋለሁ፤ አቀልጣችሁማለሁ።'),
  ('8c1a4dcb-8396-5edf-ae00-1d8ae4a66e04', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 21, 21, 'በላያችሁ የመዓቴን እሳት አነድድባችኋለሁ፤ በመካከሉም ትቀልጣላችሁ።'),
  ('fb8201a6-c995-5842-aab5-609a5d89f7c6', '4de93347-f958-53d0-aa3d-6660803b74b6', '17364fbc-9a94-5681-a515-a93215ea44c2', 22, 22, 'ብርም በከውር ውስጥ እንደሚቀልጥ፥ እንዲሁ በውስጥዋ ትቀልጣላችሁ፤ እኔም እግዚአብሔር መዓቴን እንዳፈሰስሁባችሁ ታውቃላችሁ።”'),
  ('d742876d-6e45-5a81-ab06-bd244c9474c3', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 1, 23, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('c859aaf8-ba61-5e40-ae48-70b4ecc2c4c6', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 2, 24, '“የሰው ልጅ ሆይ! አንቺ ዝናም የማይዘንብብሽ፥ በቍጣ ቀን ጠል የማይወርድብሽ ምድር ነሽ በላት።'),
  ('7e0df97a-64f4-5861-ac90-f0298805bba8', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 3, 25, 'በመካከሏ ያሉ ነቢያት እንደ አንበሳ ያገሳሉ፤ ይነጥቃሉ፤ ፈጽመውም ይቀማሉ፤ ሰውነትንም ያጠፋሉ፤ መማለጃንም ይቀበላሉ፤ በመካከልዋም መበለቶችዋ ይበዛሉ።'),
  ('67a3c53c-7ba3-5256-af41-38513088167c', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 4, 26, 'ካህናቷም ሕጌን ጣሱ፤ በመቅደሴም መካከል ቅድሳቴን አረከሱ፤ ከርኵሰትም አልራቁም፤ በንጹሕና በርኩስ መካከል ያለውንም ልዩነት አላወቁም፤ ዐይናቸውንም ከሰንበታቴ ሸፈኑ፤ እኔም በመካከላቸው ረከስሁ።'),
  ('e20c15eb-fbd8-561a-ab26-c1bbca62c5b4', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 5, 27, 'በውስጥዋ ያሉ አለቆችዋ የስስትን ትርፍ ለማግኘት ሲሉ ደምን ያፈስሱ ዘንድ፥ ነፍሶችንም ያጠፉ ዘንድ እንደሚናጠቁ ተኵላዎች ናቸው።'),
  ('6ec24149-e8d4-5528-ab7e-a7d033c8d8f0', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 6, 28, 'ነቢያቶቻቸውም ይቀቡአቸዋል፤ ከንቱ ነገርንም ያዩላቸዋል፤ እግዚአብሔር እንዲህ አለ እያሉም በሐሰት ያምዋርቱላቸዋል፤ እግዚአብሔር ግን አልነገራቸውም።'),
  ('e2ea7d8d-7d87-572d-a85c-4b3842368efe', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 7, 29, 'የምድር ሕዝብ ግፍን አደረጉ፤ ቅሚያንም ሠሩ፤ ድሆችንና ችግረኞችን አስጨነቁ፤ ለመጻተኛውም አልፈረዱለትም።'),
  ('d7b7e082-fde8-5f82-ace2-1adf831d9805', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 8, 30, 'ቅጥርን የሚጠግንን፥ ምድሪቱንም እንዳላጠፋት በፈረሰበት በኩል በፊቴ የሚቆምላትን ሰው ከእነርሱ መካከል ፈለግሁ፤ ነገር ግን አላገኘሁም።'),
  ('3c65dc9f-27eb-5ef2-aa81-8bd248b3aee3', '4de93347-f958-53d0-aa3d-6660803b74b6', 'c0f58db7-75dc-52f1-a85d-a8a2c7c8ae0e', 9, 31, 'ስለዚህ ቍጣዬን አፈሰስሁባቸው፤ በመዓቴም እሳት አጠፋኋቸው፤ መንገዳቸውንም በራሳቸው ላይ መለስሁ፥ ይላል ጌታ እግዚአብሔር።”'),
  ('657b00b8-7a35-5837-a996-fa9219aa32ba', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 1, 1, 'የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('500c386f-dc14-5806-a07d-c103e21cb446', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 2, 2, '“የሰው ልጅ ሆይ፥ የአንዲት እናት ልጆች የሆኑ ሁለት ሴቶች ነበሩ።'),
  ('269e7766-724e-5448-a829-b96e666c939a', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 3, 3, 'በግብፅ ሀገር አመነዘሩ፤ በኮረዳነታቸው ሳሉ አመነዘሩ፤ በዚያም ጡቶቻቸው ወደቁ፤ በዚያም ድንግልናቸውን አጡ።'),
  ('c4f94373-bb8b-55fb-a589-1e392bb4ec78', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 4, 4, 'ስማቸውም የታላቂቱ ሐላ የታናሽ እኅቷም ሐሊባ ነበረ፤ እኔም አገባኋቸው፤ ወንዶችና ሴቶች ልጆችንም ወለዱ። ስማቸውም ሐላ ሰማርያ ናት፤ ሐሊባ ደግሞ ኢየሩሳሌም ናት።'),
  ('bf4062e0-b45e-5205-ae0b-9d6f0162dc4d', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 5, 5, '“ሐላም አመነዘረችብኝ፤ ወዳጆችዋንም የሚቀርቡአትን አሦራውያንን በፍቅር ተከተለቻቸው።'),
  ('1922378a-e565-55d9-a993-7284eafda4bf', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 6, 6, 'እነርሱም ሰማያዊ ሐር የለበሱ መሳፍንትና መኳንንት፥ መልከ መልካሞች ጐበዛዝት፥ በፈረስ ላይ የሚቀመጡ የተመረጡ ፈረሰኞች ነበሩ።'),
  ('bc1118d0-0245-5de0-ad23-fb1af28cc895', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 7, 7, 'ዝሙቷንም ከተመረጡ ከአሦር ሰዎች ሁሉ ጋር አደረገች፤ በፍቅር በተከተለቻቸውም ጣዖቶቻቸው ሁሉ ረከሰች።'),
  ('34bbedb4-c497-5387-aae0-c8f553867829', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 8, 8, 'በግብፅም የነበረውን ዝሙቷን አልተወችም፤ በዚያም በኮረዳነቷ ጊዜ ከእርስዋ ጋር ተኝተው ነበር፤ የድንግልናዋንም ጡቶች ዳብሰው ነበር፤ ዝንየታቸውንም አፍስሰውባት ነበር።'),
  ('14588898-7210-5b50-a463-daff13c78cc9', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 9, 9, 'ስለዚህ በፍቅር በተከተለቻቸው በወዳጆችዋ በአሦራውያን እጆች አሳልፌ ሰጠኋት።'),
  ('4af38c1a-1869-56a2-a120-4d2ef12c3598', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 10, 10, 'እነርሱም ኀፍረተ ሥጋዋን ገለጡ፤ ወንዶችና ሴቶች ልጆችዋንም ማርከው ወሰዱ፤ እርስዋንም በሰይፍ ገደሉ፤ በእርስዋና በሴቶች ልጆችዋ ላይ በቀልን ስላደረጉባቸው በሴቶች መካከል መተረቻ ሆነች።'),
  ('55b3102a-db66-58f9-a46a-308dd39da007', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 11, 11, '“እኅቷም ሐሊባ ይህን አየች፤ ሆኖም ከእርስዋ ይልቅ በፍቅር በመከተልዋ ረከሰች፤ ዝሙቷንም ከእኅቷ ዝሙት ይልቅ አበዛች።'),
  ('6f89fd21-d9f1-5082-af73-ecdee9ac5395', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 12, 12, 'የሚቀርቡአትን መሳፍንቱንና መኳንንቱን ጌጠኛ ልብስ የለበሱትን፥ በፈረሶች ላይ የሚቀመጡትን ፈረሰኞች፥ ሁሉንም መልከ መልካሞችን ጐበዛዝት አሦራውያንን በፍቅር ተከተለቻቸው።'),
  ('1929269b-10e0-5a84-a6f6-5855cd18155b', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 13, 13, 'እንደ ረከሱም አየሁ፤ ሁለቱም አንድ መንገድ ሄደዋል።'),
  ('6a75f179-570d-5e7a-a848-7c23aa657ef2', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 14, 14, 'ዳግመኛም ዝሙቷን አበዛች፤ በግንብ ላይ የተሣሉ የከለዳውያን ሰዎች ሥዕልንም አየሁ።'),
  ('736f67af-4f4a-5eab-ab3d-cd4bcd17dacf', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 15, 15, 'በጥቍር ቀለም የተሣሉ የከለዳውያንን መልክ አየሁ፤ በወገባቸው ዝናር የታጠቁ ናቸው፤ በራሳቸውም ላይ ጥልፍ ሰበን የጠመጠሙ ናቸው፤ ፊታቸውም ሦስት ወገን ነው፤ ሁሉም በትውልድ ሀገራቸው የሚኖሩ የባቢሎን ሰዎችን ከለዳውያንን ይመስላሉ።'),
  ('ed47304a-0fe0-5d4d-ae52-09ed7bc05509', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 16, 16, 'ዐይንዋንም ወደ እነርሱ አቅንታ አየቻቸው፤ ወደ ከላውዴዎንም ምድር ወደ እነርሱ መልእክተኞችን ላከች።'),
  ('8aa393d0-67ec-5cd7-a046-2c8760f09488', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 17, 17, 'የባቢሎንም ልጆች ወደ እርስዋ መጥተው በመኝታዋ ከእርስዋ ጋር ተኙ፤ በዝሙታቸውም አረከሱአት፤ እርስዋም ከእነርሱ ጋር ረከሰች፤ ነፍስዋም ከእነርሱ ተለየች።'),
  ('ef98c7a3-3994-5761-a19f-39b17763b872', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 18, 18, 'ዝሙቷንም ገለጠች፤ ኀፍረተ ሥጋዋንም ገለጠች፤ ነፍሴም ከእኅቷ እንደ ተለየች እንዲሁ ነፍሴ ከእርስዋ ተለየች።'),
  ('c8a48ed7-95a6-53f8-a35e-824a266f75a8', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 19, 19, 'ነገር ግን በግብፅ ምድር ያመነዘረሽበትን የወጣትነትሽን ዘመን አስበሽ ዝሙትሽን አበዛሽ።'),
  ('b71ee6f4-d080-52e8-af22-cea99d22cff8', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 20, 20, 'አካላቸውም እንደ አህዮች አካል፤ ዘራቸውም እንደ ፈረሶች ዘር የሆነውን እነዚያን የከለዳውያን ልጆች በፍቅር ተከተልሻቸው።'),
  ('1c00a566-0a48-5210-ad43-34e275468d65', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 21, 21, 'ጡትሽ በአጐጠጐጠ ጊዜ በማደሪያሽ በግብፅ ሀገር የሠራሽውን የወጣትነትሽን ኀጢአት አሰብሽ።”'),
  ('3966b682-6405-5dc0-a155-3b8cbb8ff909', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 22, 22, 'ስለዚህ ሐሊባ ሆይ! ጌታ እግዚአብሔር እንዲህ ይላል፥ “ነፍስሽ ከእነርሱ የተለየች ወዳጆችሽን አስነሣብሻለሁ፤ በዙሪያሽም በአንቺ ላይ አመጣቸዋለሁ።'),
  ('400427a4-73dc-5995-ae94-b363700afcb5', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 23, 23, 'እነርሱም የባቢሎን ልጆች፥ ከለዳውያንም ሁሉ፥ ፋቁድ፥ ሱሔ፥ ቆዓ፥ ከእነርሱም ጋር አሦራውያን ሁሉ፥ መልከ መልካሞች ጐበዛዝት፥ መሳፍንትና መኳንንት ሁሉ፥ መሳፍንትና አማካሪዎች ሁሉ፥ በሦስት ወገን በፈረስ ላይ የተቀመጡ ናቸው።'),
  ('33a19a4e-299c-509c-a68d-ecc29d02e7b8', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 24, 24, 'ስማቸውን ያስጠሩ ሰዎች ሁሉ በመንኰራኵርና በሠረገላ፥ በአሕዛብም ጉባኤ ይመጡብሻል፤ ጋሻና አላባሽ ጋሻ፥ ራስ ቍርም ይዘው በዙሪያሽ ጥበቃ ያደርጋሉ፤ ፍርድንም እሰጣቸዋለሁ፤ እንደ ፍርዳቸውም ይፈርዱብሻል።'),
  ('9bc95e00-5b03-59e2-ac37-7ed1a8fd29a8', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 25, 25, 'ቅንአቴንም በአንቺ ላይ አደርጋለሁ፤ በመዓትም ያደርጉብሻል፤ አፍንጫሽንና ጆሮሽንም ከአንቺ ይቈርጣሉ፤ ከአንቺም የቀረ በሰይፍ ይወድቃል፤ ወንዶችና ሴቶች ልጆችሽንም ማርከው ይወስዳሉ፤ ከአንቺም የቀሩትን እሳት ትበላቸዋለች።'),
  ('1597dd24-cb55-586d-a106-23bf0738c202', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 26, 26, 'ልብስሽንም ይገፍፉሻል፤ የክብርሽንም ጌጥ ይወስዳሉ።'),
  ('54f05fe5-6020-51db-a165-0fa30795807f', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 27, 27, 'ሴሰኝነትሽንም፥ ከግብፅ ምድር ያወጣሽውን ዝሙትሽንም ከአንቺ አስቀራለሁ፤ ዐይንሽንም ከእንግዲህ ወዲህ ወደ እነርሱ አታነሺም፤ ግብፅንም ከዚያ ወዲያ አታስቢም።'),
  ('fe789579-3961-504f-a2d5-c14c628361e0', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 28, 28, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ በጠላሻቸው እጅ፥ ነፍስሽም በተለየቻቸው እጅ አሳልፌ እሰጥሻለሁ፤'),
  ('2708daa4-272f-5c59-a778-39f0cfaddeee', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 29, 29, 'እነርሱም በጥል ያደርጉብሻል፤ የደከምሽበትንም ሁሉ ይወስዳሉ፤ ዕራቁትሽንና ዕርቃንሽን አድርገውም ይተዉሻል፤ የግልሙትናሽንም ነውር፥ ሴሰኝነትሽንና ግልሙትናሽንም ሁሉ ይገልጣሉ።'),
  ('1b567746-67c4-5d06-a56b-9466338d6492', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 30, 30, 'ከአሕዝብ ጋር ስላመነዘርሽ፤ በበደላቸውም ስለ ረከስሽ ይህን ያደርጉብሻል።'),
  ('27025053-405a-5d32-ae3f-54e35c01a5e5', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 31, 31, 'በእኅትሽ መንገድ ሄደሻል፤ ስለዚህ ጽዋዋን በእጅሽ እሰጥሻለሁ።'),
  ('ebb90bb1-2cc4-5dfe-afd0-1ce29ecabb93', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 32, 32, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ የጠለቀውንና የሰፋውን፥ ብዙም የሚይዘውን የእኅትሽን ጽዋ ትጠጪአለሽ፤ ብዙ መጠጥን በሚጠጡ ሰዎችም ዘንድ መሳቂያና መሳለቂያ ትሆኛለሽ።'),
  ('3d65e34c-c915-5744-a8f8-4ef3b1f5d855', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 33, 33, 'በእኅትሽ በሰማርያ ጽዋ፥ በድንጋጤና በጥፋት ጽዋ፥ በስካርና በውርደት ትሞሊያለሽ።'),
  ('cf4b1b55-fd35-56f5-a02e-a80dd48cf830', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 34, 34, 'ትጠጪዋለሽ፥ ትጨልጪውማለሽ፤ በዓላትሽንና መባቻዎችሽን እሽራለሁ፤ እኔ ተናግሬአለሁና ይላል እግዚአብሔር።'),
  ('97c9930c-38c2-5e86-a0bb-ab3d2502509a', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 35, 35, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ዘንግተሽኛልና፥ ወደ ኋላሽም ጥለሽኛልና አንቺ ደግሞ ሴሰኝነትሽንና ኀጢአትሽን ተሸከሚ።”'),
  ('317f55fd-244f-5faa-a6a8-dc9542a9397c', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 36, 36, 'እግዚአብሔርም እንዲህ አለኝ፥ “የሰው ልጅ ሆይ! ሐላንና ሐሊባን ተፋረዳቸው፤ ኀጢአታቸውንም አስታውቃቸው፤'),
  ('1bc9619c-5ca9-5b7b-a0c7-975d1aceba2f', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 37, 37, 'አመንዝረዋልና፥ ደምም በእጃቸው አለና፥ ዝሙታቸውንም ወድደዋልና፥ ለእኔም የወለዱአቸውን ልጆቻቸውን መብል እንዲሆኑላቸው በእሳት አሳልፈዋቸዋልና።'),
  ('9584e20c-e52b-54db-ab2b-c9e1c6250362', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 38, 38, 'ይህን ደግሞ አድርገውብኛል፤ በዚያ ቀን መቅደሴን አርክሰዋል፤ ሰንበታቴንም ሽረዋል።'),
  ('7f3c6867-bcfa-57c1-a16f-0ea765590db6', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 39, 39, 'ልጆቻቸውንም ለጣዖቶቻቸው በሠዉ ጊዜ ፥ በዚያው ቀን ያረክሱት ዘንድ ወደ መቅደሴ ገቡ፤ እነሆም በቤቴ ውስጥ እንደዚህ አደረጉ።'),
  ('8eba9822-34e7-5c8d-a424-7d34f7548223', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 40, 40, 'ከሩቅ ሀገርም ወደመጡ ሰዎች መልእክተኞችን ላኩ፤ እነርሱም በደረሱ ጊዜ ይታጠባሉ፤ ዐይኖቻቸውንም ይኳላሉ፤ ያጌጣሉም።'),
  ('19050c1b-8b0b-5f31-ab5e-a1f862f30588', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 41, 41, 'በክብር አልጋ ላይ ይቀመጣሉ፤ በፊት ለፊታቸውም ማዕድ ተዘጋጅታ ነበር፤ በዕጣኔና በዘይቴም ደስ ይላቸዋል።'),
  ('fd35e3dc-a2cd-5277-a42d-18e55fefd4fb', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 42, 42, 'የበገናውን አውታር ድምፅ ይቃኛሉ፤ ከብዙ ሰዎችም ጉባኤ ጋር ሰካራሞቹ ከምድረ በዳ መጡ፤ በእጃቸው አንባር፥ በራሳቸውም የተዋበ አክሊል አደረጉ።'),
  ('27512fe8-ad95-594f-ad62-1f40c194a77a', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 43, 43, 'እኔም፦ ‘አሁን ከእርስዋ ጋር ያመነዝራሉ፤ እርስዋም ከእነርሱ ጋር ታመነዝራለች፤’ አልሁ።'),
  ('ddded80a-4691-5f89-a829-4cf19f649497', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 44, 44, 'ወደ ጋለሞታ እንደሚገቡም ወደ እርስዋ ገቡ፤ እንዲሁ ይሰስኑ ዘንድ ወደ ሐላና ወደ ሐሊባ ገቡ።'),
  ('09e251f3-1473-552a-a2eb-629beb1cccb1', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 45, 45, 'ሴቶቹ አመንዝሮች ናቸውና፥ በእጃቸውም ደም አለና ጻድቃን ሰዎች በአመንዝሮቹና በደም አፍሳሾቹ ሴቶች ላይ በሚፈረደው ፍርድ ይፈርዱባቸዋል።”'),
  ('f7b5bb03-14fa-54ae-a638-6bc291c41f96', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 46, 46, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “ጉባኤን አመጣባቸዋለሁ፤ ለመበተንና ለመበዝበዝም አሳልፌ እሰጣቸዋለሁ።'),
  ('19968eb2-c121-5300-a45e-259b6f3cf6f9', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 47, 47, 'ጉባኤውም በድንጋይ ይወግሩአቸዋል፤ በሰይፋቸውም ይቈርጡአቸዋል፤ ወንዶችና ሴቶች ልጆቻቸውንም ይገድላሉ፤ ቤቶቻቸውንም በእሳት ያቃጥላሉ።'),
  ('0d9d6c81-e00d-56ba-af3c-aca20f1e7330', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 48, 48, 'ሴቶችም ሁሉ እንደ ኀጢአታችሁ እንዳይሠሩ ይማሩ ዘንድ ሴሰኝነትን ከምድር ላይ አጠፋለሁ።'),
  ('54a904eb-61d7-5e0c-ae43-f9eda36d4137', '036ea8c7-fca1-583f-aa2d-4bc5d266b001', 'e5443c84-ff04-5c4d-afac-44a54b79bf39', 49, 49, 'እንግዲህ በደላችሁ በላያችሁ ላይ ይመለሳል፤ እናንተም የጣዖቶቻችሁን ኀጢአት ትሸከማላችሁ፤ እኔም ጌታ እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።”'),
  ('2c36f8b1-31dc-5b69-aa58-a8feb271fae9', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 1, 1, 'በዘጠነኛው ዓመት በዐሥረኛው ወር ከወሩም በዐሥረኛው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('57ff3bb1-c459-5805-a2aa-fdeb95858bbf', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 2, 2, '“የሰው ልጅ ሆይ! የዚህን ቀን፥ የዛሬን ቀን ስም ጻፍ፤ በዚህ ቀን የባቢሎን ንጉሥ ወደ ኢየሩሳሌም ይመጣልና።'),
  ('8ade0f1c-ab6c-5369-a2c1-571231c4ec92', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 3, 3, 'ለዐመፀኛውም ቤት ምሳሌን ተናገር እንዲህም በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ጣድ፥ ድስቲቱን ጣድ፥ ውኃም ጨምርባት።'),
  ('bdee2eac-0881-53b0-add7-2aaa2ead8dfc', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 4, 4, 'ቍራጭዋንም፥ መልካሙን ቍራጭ ሁሉ፥ ጭኑንና ወርቹን በእርስዋ ውስጥ ጨምር፤ የተመረጡትንም አጥንቶች ሙላባት።'),
  ('e6d6ecc3-6f6b-5004-ada6-eb7b072a6d86', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 5, 5, 'ከመንጋው የተመረጠውን ውሰድ፤ አጥንቶቹም እንዲበስሉ በበታችዋ እሳት አንድድ፤ አፍላው፤ በእጅጉ ይፍላ፤ አጥንቶቹም በውስጥዋ ይቀቀሉ።'),
  ('1dbc6960-558b-5cbd-a494-a8af206d53d8', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 6, 6, '“ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ዝገቷ ላለባት፥ ዝገቷም ከእርስዋ ላልወጣ ድስት፥ ለደም ከተማ ወዮላት! ቍራጭ ቍራጩን አውጣ፤ ዕጣ አልወደቀባትም።'),
  ('3e202b27-68a2-5bd8-a15f-cfbc26fdeb65', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 7, 7, 'ደምዋም በመካከልዋ አለ። በተራቈተ ድንጋይ ላይ አደረገችው እንጂ በአፈር ይከደን ዘንድ በመሬት ላይ አላፈሰሰችውም።'),
  ('f2ccac92-9ee6-5671-ab61-c8778cd65ded', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 8, 8, 'መዓቴን አወጣ ዘንድ፥ በቀሌንም እበቀል ዘንድ፥ ደምዋ እንዳይከደን በተራቈተ ድንጋይ ላይ አደረግሁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('52223f98-17b5-5c93-acba-ae2c323f586d', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 9, 9, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ለደም ከተማ ወዮላት! እኔ ደግሞ ማገዶዋን ታላቅ አደርገዋለሁ።'),
  ('f9988831-77df-51df-a056-681b9ce3fcdc', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 10, 10, 'ደሟ እስኪያልቅ ድረስ ሥጋዋ ያርር ዘንድ፥ አጥንቶችዋም ይቀጠቀጡ ዘንድ፤ እንጨቱን አበዛለሁ፤ እሳቱንም አነድዳለሁ፥'),
  ('4e571aac-5dbe-58ea-ac00-d92a1eeb8cb8', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 11, 11, 'ድስቷም እስክትፈላና እስክትሰበር ድረስ በፍሙ ላይ አኖራታለሁ፤ ርኵሰትዋም በመካከሏ እንደ ሰም ይቀልጣል፤ ዝገትዋም ይጠፋል፤'),
  ('221b8481-4715-52e0-a337-bda461ce3367', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 12, 12, 'በከንቱ ደከመች፤ ሆኖም ብዙ ዝገቷ ከእርስዋ አልለቀቀም።'),
  ('def48c7c-fb59-50c3-a948-5ba7a1c69e42', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 13, 13, 'በርኵሰትሽ ሴሰኝነት አለ፤ አነጻሁሽ፤ አልነጻሽምና መዓቴን በላይሽ እስክጨርስ ድረስ እንግዲህ ከርኵሰትሽ አትነጺም።'),
  ('caac44e7-5289-5152-aa74-f2df8defbec2', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '5e0ff96a-894f-5e02-aaa9-6e3661c90dfb', 14, 14, 'እኔ እግዚአብሔር ተናግሬአለሁ፤ እመጣለሁ፤ እኔም አደርገዋለሁ፤ አልተውም፤ አልራራም፤ አልጸጸትም፤ እንደ መንገድሽና እንደ ሥራሽም እፈርድብሻለሁ፥ ይላል ጌታ እግዚአብሔር። ስለዚህ የሰውን ደም እንደ አፈሰስሽ እኔ እፈርድብሻለሁ፤ እንደ ኀጢአትሽም ተበቅዬ አጠፋሻለሁ፤ ስምሽም ጐሰቈለ፥ ብዙ ኀዘንንም ታዝኛለሽ።”'),
  ('3803ff9c-5425-5890-a70d-27b068a722af', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 1, 15, 'የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('1c843cd7-e027-543d-ac6c-95097b6babd5', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 2, 16, '“የሰው ልጅ ሆይ! እነሆ የዐይንህን አምሮት በመቅሠፍት እወስድብሃለሁ፤ አንተም ዋይ አትበል፤ አታልቅስም፤ እንባህንም አታፍስስ።'),
  ('b97aca45-7efe-58b0-a6f3-8c963daecaed', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 3, 17, 'በቀስታ ተክዝ፤ ነገር ግን የሙታንን ልቅሶ አታልቅስ፤ መጠምጠሚያህን በራስህ ላይ አድርግ፤ ጫማህንም በእግርህ አጥልቅ፤ ከንፈሮችህንም አትሸፍን፤ የዕዝን እንጀራንም አትብላ።”'),
  ('018d7d72-4f7b-5e66-a9da-ae0aa6a24b63', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 4, 18, 'እኔም በማለዳ ለሕዝቡ ተናገርሁ፤ ወደ ማታም ሚስቴ ሞተች፤ በነጋውም እንደ ታዘዝሁ አደረግሁ።'),
  ('1e452a91-fc41-5276-a4a4-9b4eee907747', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 5, 19, 'ሕዝቡም፥ “ይህ የምታደርገው ነገር ለእኛ ምን እንደ ሆነ አትነግረንምን?” አሉኝ።'),
  ('bbfef003-fb13-52a3-a88a-ea06237fa7c1', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 6, 20, 'እኔም እንዲህ አልኋቸው፥ “የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('8a3ffd76-0136-5f0a-a0d6-ee049fe8d8b8', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 7, 21, 'ለእስራኤል ቤት ተናገር፤ እንዲህም በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ የኀይላችሁን ትምክሕት፥ የዐይናችሁን አምሮት፥ የነፍሳችሁንም ምኞት፥ መቅደሴን አረክሳለሁ፤ ያስቀራችኋቸውም ወንዶችና ሴቶች ልጆቻችሁ በሰይፍ ይወድቃሉ።'),
  ('2b740363-0061-5d9f-abdc-57a5b3a9cdd6', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 8, 22, 'እኔም እንዳደረግሁ እናንተ ታደርጋላችሁ፤ በአንደበታቸው አትጽናኑም፤ የዕዝን እንጀራንም አትበሉም።'),
  ('44ad6f38-be19-5b8f-a6ef-db65635ca193', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 9, 23, 'መጠምጠሚያችሁም በራሳችሁ፥ ጫማችሁም በእግራችሁ ይሆናል፤ ዋይ አትሉም፤ አታለቅሱምም፤ በኀጢአታችሁም ትሰለስላላችሁ፤ ሁላችሁም ጓደኞቻችሁን ታጽናናላችሁ።'),
  ('2e607c3c-7d4d-5bb0-aaaf-565e8f4dfa03', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 10, 24, 'ሕዝቅኤልም ምልክት ይሆናችኋል፤ እርሱ እንደ አደረገ ሁሉ እናንተ ታደርጋላችሁ፤ ይህም በመጣ ጊዜ እኔ ጌታ እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('ca2789d7-ce9e-5e10-a030-09003480ae39', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 11, 25, '“አንተም የሰው ልጅ ሆይ! ኀይላቸውን፥ የተመኩበትንም ደስታ፥ የዐይናቸውንም አምሮት፥ የነፍሳቸውንም ምኞት፥ ወንዶችና ሴቶች ልጆቻቸውን በወሰድሁባቸው ቀን፥'),
  ('25208a54-22e3-51e8-a109-3ca7da255f5e', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 12, 26, 'በዚያ ቀን ያመለጠው ይህን ነገር በጆሮህ ያሰማ ዘንድ ወደ አንተ ይመጣል።'),
  ('67ae5466-b239-5343-ac4a-b6e32c66d318', 'cf907637-e472-5a7f-ae97-44e72a918eb0', '96376d68-df78-5bbf-a2d1-2535208d674d', 13, 27, 'በዚያ ቀን አፍህ ላመለጠው ይከፈታል፤ አንተም ትናገራለህ፤ ከዚያም ወዲያ ዲዳ አትሆንም፤ ምልክትም ትሆናቸዋለህ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('9c17d717-d7cc-5a20-a0dd-527152d59a26', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', '40a51932-02cd-54b0-a48c-5da67a73ce55', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('0898e160-c844-5f5e-af16-3abdf7d3f550', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', '40a51932-02cd-54b0-a48c-5da67a73ce55', 2, 2, '“የሰው ልጅ ሆይ! ፊትህን ወደ አሞን ልጆች አቅንተህ ትንቢት ተናገርባቸው።'),
  ('460091ca-fef7-5a50-a56d-5693d536f53a', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', '40a51932-02cd-54b0-a48c-5da67a73ce55', 3, 3, 'ለአሞንም ልጆች እንዲህ በል፦ የጌታን የእግዚአብሔርን ቃል ስሙ፤ ጌታ እግዚአብሔር እንዲህ ይላል፦ መቅደሴ በረከሰ ጊዜ የእስራኤልም ምድር ባድማ በሆነች ጊዜ፥ የይሁዳም ቤት በተማረኩ ጊዜ ስለ እነርሱ ደስ ብሎሃልና፤'),
  ('77fd2d02-0243-5781-a21a-f7079eebbbf3', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', '40a51932-02cd-54b0-a48c-5da67a73ce55', 4, 4, 'ስለዚህ እነሆ ርስት አድርጌ ለምሥራቅ ልጆች አሳልፌ እሰጥሃለሁ፤ እነርሱም ማደሪያዎቻቸውን በአንተ ዘንድ ይሠራሉ፤ ድንኳኖቻቸውንም በአንተ ውስጥ ይተክላሉ፤ ፍሬህን ይበላሉ፤ ወተትህንም ይጠጣሉ።'),
  ('c53cf2e0-1811-5887-a9db-2b01b6779bb3', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', '40a51932-02cd-54b0-a48c-5da67a73ce55', 5, 5, 'የአሞንን ከተማ ለግመሎች ማሰማሪያ፥ የአሞንንም ልጆች ለመንጋ መመሰጊያ አደርጋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('d385811f-a3d1-5485-a166-bcd5c2907241', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', '40a51932-02cd-54b0-a48c-5da67a73ce55', 6, 6, 'ጌታ እግዚአብሔር እንዲህ ይላልና፦ በእጆችህ አጨብጭበሃልና፥ በእግሮችህም አሸብሽበሃልና፥ ሰውነትህም በእስራኤል ምድር ላይ ደስ ብሎአታልና፤'),
  ('fc10d885-eb70-522e-a104-24c622f0a5b6', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', '40a51932-02cd-54b0-a48c-5da67a73ce55', 7, 7, 'ስለዚህ እነሆ እጄን ዘርግቼብሃለሁ፤ ለአሕዛብም አስበዘብዝሃለሁ፤ ከአሕዛብም ለይች እቈርጥሃለሁ፤ ከሀገሮችም እደመስስሃለሁ፤ አጠፋሃለሁም፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃለህ።”'),
  ('5643dfa1-3a0c-5995-aed4-dbedd154b016', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'f8b35e4a-f5a1-5e81-aea4-cbe1db1bf849', 1, 8, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “ሞአብና ሴይር፦ እነሆ የይሁዳ ቤት እንደ አሕዛብ ሁሉ ነው ብለዋልና፤'),
  ('e4c50d89-21c1-5247-a8ab-de4e0a829307', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'f8b35e4a-f5a1-5e81-aea4-cbe1db1bf849', 2, 9, 'ስለዚህ እነሆ የሞአብን ጫንቃ ከከተሞቹ፥ በዳርቻው ካሉት የምድሩ ትምክሕት ከሆኑት ከተሞቹ፥ ከቤትየሺሞት፥ ከባኣልሜዎን፥ ከቂርያታይም አደክማለሁ።'),
  ('5ac73423-9e8e-5b64-ace7-6071e6b3f5e9', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'f8b35e4a-f5a1-5e81-aea4-cbe1db1bf849', 3, 10, 'የአሞን ልጆች በአሕዛብ መካከል ከእንግዲህ ወዲህ እንዳይታሰቡ የአሞንን ልጆች ለምሥራቅ ልጆች ርስት አድርጌ እሰጣቸዋለሁ።'),
  ('bc5bf958-c742-5706-a186-b65caf20e6c3', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'f8b35e4a-f5a1-5e81-aea4-cbe1db1bf849', 4, 11, 'በሞአብም ላይ በቀልን አደርጋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('8d827b5a-3e86-51cc-a218-7a1fdf77c67c', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'b06b2ace-09fd-58cf-a6ad-bb0b158de5f3', 1, 12, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ኤዶምያስ በይሁዳ ቤት ላይ በቀል አድርጎአልና፥ ቂምም ይዞአልና፥ በቀልንም ተበቅሎአልና፤'),
  ('5a99e71d-5520-5f7e-afc0-597ac9cf2051', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'b06b2ace-09fd-58cf-a6ad-bb0b158de5f3', 2, 13, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እጄን በኤዶምያስ ላይ እዘረጋለሁ፤ ከእርስዋም ዘንድ ሰውንና እንስሳን አጠፋለሁ፤ ባድማም አደርጋታለሁ፤ ከቴማንና ከድዳንም ያመለጡ በሰይፍ ይወድቃሉ።'),
  ('f7d3a387-f506-5a2e-a10b-abf017d316b5', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'b06b2ace-09fd-58cf-a6ad-bb0b158de5f3', 3, 14, 'በሕዝቤ በእስራኤል እጅ ኤዶምያስን እበቀላለሁ፤ እንደ ቍጣዬና እንደ መዓቴም መጠን በኤዶምያስ ያደርጋሉ፤ በቀሌንም ያውቃሉ፥” ይላል ጌታ እግዚአብሔር።'),
  ('13c1e121-f001-5a9d-a3d2-6344e0686fb3', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'db3fb0f9-9164-5b39-a698-4ed10cc0f193', 1, 15, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “ፍልስጥኤማውያን በቀልን አድርገዋልና፥ በቀላቸውንም አጽንተዋልና፥ እስራኤልም ለዘለዓለም ይጠፉ ዘንድ ነፍሳቸው ደስ ይላታልና፤'),
  ('258c1326-e4cf-5591-aeeb-ca2a31a00c82', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'db3fb0f9-9164-5b39-a698-4ed10cc0f193', 2, 16, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ እጄን በፍልስጥኤማውያን ላይ እዘረጋለሁ፤ መኳንንቱንም እቈርጣለሁ፤ የባሕሩንም ዳር ቅሬታ አጠፋለሁ።'),
  ('cc29c58d-590d-559b-a079-0a35bfd58ec2', '1b5f79b1-b300-5d10-ab42-d768fbffa38f', 'db3fb0f9-9164-5b39-a698-4ed10cc0f193', 3, 17, 'በመዓት መቅሠፍትም ታላቅ በቀል አደርግባቸዋለሁ፤ በቀሌንም በላያቸው በአደረግሁ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('8c379011-ba86-55c2-ae9a-b6396fbb501b', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 1, 1, 'እንዲህም ሆነ፤ በዐሥራ አንደኛው ዓመት ከወሩ በመጀመሪያው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('07a9ac4b-96f4-5c7a-a324-6a4b4aa14db3', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 2, 2, '“የሰው ልጅ ሆይ፥ ጢሮስ በኢየሩሳሌም ላይ፦ እሰይ፥ ተሰበረች፥ ጠፋችም፥ ሕዝቧም ወደ እርስዋ ተመለሱ፤ ሞልታ የነበረች አለቀች ብላለችና፤'),
  ('bda48414-c733-514b-ae7a-16377b914b83', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 3, 3, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ጢሮስ ሆይ! እነሆ በአንቺ ላይ ነኝ፤ ባሕርም ሞገድዋን እንደምታወጣ እንዲሁ ብዙ አሕዛብን አወጣብሻለሁ።'),
  ('963ab546-56d5-5015-a22b-ae1d030bb88a', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 4, 4, 'የጢሮስንም ቅጥሮች ያፈርሳሉ፤ ግንቦችዋንም ያፈርሳሉ፤ ትቢያዋንም ከእርስዋ እፍቃለሁ፤ እንደ ተራቈተ ድንጋይም አደርጋታለሁ።'),
  ('4663f4fd-3c16-5bcc-a346-a720e31c10fb', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 5, 5, 'በባሕር ውስጥ የመረብ ማስጫ ትሆናለች፤ እኔ ተናግሬአለሁና፥” ይላል እግዚአብሔር፤ ለአሕዛብም ብዝበዛ ትሆናለች።'),
  ('215135aa-0fd7-583f-a826-d77cc2bea147', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 6, 6, 'በሜዳ ያሉትም ሴቶች ልጆችዋ በሰይፍ ይገደላሉ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('5f8cc54a-ba4d-54e4-a24e-42d959ee8082', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 7, 7, '“ጌታ እግዚአብሔር እንዲህ ይላልና፦ ጢሮስ ሆይ! እነሆ ከሰሜን የነገሥታት ንጉሥ የባቢሎንን ንጉሥ ናቡከደነፆርን ከፈረሶችና ከሰረገሎች፥ ከፈረሰኞችም፥ ከጉባኤና ከብዙ ሕዝብም ጋር በአንቺ ላይ አመጣለሁ።'),
  ('a78c48d6-47d2-549b-a54b-10f71eed9a8a', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 8, 8, 'እርሱ በምድረ በዳ ያሉ ሴቶች ልጆችሽን በሰይፍ ይገድላቸዋል፤ ጠባቂዎችንም በአንቺ ላይ ያስቀምጣል፤ በዙሪያሽም ግንብ ይሠራል፤ የጦር መሣሪያም ይዘው ይከቡሻል፤ በጦራቸውም ይወጉሻል፤'),
  ('1ca1021c-2ef0-50ca-ae1e-ca616f16e34a', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 9, 9, 'ግንቦችሽንና ቅጥርሽን በምሳር ያፈርሳል።'),
  ('e3058afa-818b-5bec-a3a0-a6eef75759a0', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 10, 10, 'ከፈረሶቹም ብዛት የተነሣ በትቢያ ይሸፍንሻል፤ ከሠረገላ መንኰራኵርና ከፈረሶቹ ድምፅ የተነሣም ቅጥሮችሽን ያፈርሳል፤ ወንበዴ መሣሪያውን ይዞ ወደ ምድረ በዳ ቦታ እንዲገባ በሮችሽን ይገቡባቸዋል።'),
  ('f2131f34-7ae1-5c0a-a4b2-918a8f03fc76', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 11, 11, 'ፈረሶቹ አደባባይሽን ይረግጣሉ፤ ሠራዊቶችሽንም በሾተል ይገድሏቸዋል፤ የጸና አርበኛሽንም በምድር ላይ ይጥለዋል።'),
  ('47a44d97-8e5f-5ae7-a679-3a843c7970a4', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 12, 12, 'ገንዘብሽን ይበረብራሉ፤ መንጋሽንም ይዘርፋሉ፤ አምባሽንም ይንዳሉ፤ የተወደዱ ቤቶችሽንም ያፈርሳሉ፤ እንጨቶችሽንና ድንጋይሽን፥ መሬትሽንም በባሕሩ ጥልቅ ውስጥ ይጥሉታል።'),
  ('f58b6421-8502-5b99-af52-137ac61593f8', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 13, 13, 'የዘፋኞችሽንም ብዛት ዝም አሰኛለሁ፤ የመሰንቆሽም ድምፅ ከዚያ ወዲያ አይሰማም።'),
  ('15ca4291-8e44-5aa1-afbd-41dee4346cb8', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 14, 14, 'እንደ ተራቈተ ድንጋይ አደርግሻለሁ፤ የመረብም ማስጫ ትሆኛለሽ፤ ከእንግዲህ ወዲህ አትሠሪም፤ እኔ እግዚአብሔር ተናግሬአለሁና፥” ይላል እግዚአብሔር።'),
  ('af793d72-9c1e-574b-aff0-9c28a9544661', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 15, 15, '“ስለ ጢሮስ ጌታ እግዚአብሔር እንዲህ ይላል፦ ሾተላቸውን በመካከልሽ በመዘዙ ጊዜ ከውድቀትሽ፥ ከቈሰሉትም ጩኸት የተነሣ፤ ደሴቶች የሚነዋወጡ አይደለምን?'),
  ('45892775-d29b-5013-ae00-40c5130579a7', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 16, 16, 'የባሕርም አለቆች ሁሉ ከዙፋኖቻቸው ይወርዳሉ፤ ዘውዳቸውን ከራሳቸው ያወርዳሉ፤ ወርቀ ዘቦ ልብሳቸውን ያወልቃሉ፤ በመሬትም ላይ ተቀምጠው ይደነግጣሉ፤ ሞታቸውንም ይፈራሉ፤ ስለ አንቺም ያለቅሳሉ።'),
  ('9d2436de-54f0-5744-a313-1de15615095b', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 17, 17, 'በአንቺም ላይ ሙሾ ያሞሻሉ፤ እንዲህም ይሉሻል፦ በባሕር የተቀመጥሽ፥ በባሕርም ውስጥ የጸናሽ፥ ከሚቀመጡብሽም ጋር በዙሪያሽ የሚኖሩትን ሁሉ ያስፈራሽ፥ የከበርሽ ከተማ ሆይ! እንዴት ጠፋሽ!'),
  ('5ae3afe3-d1fd-5257-a617-1523a48647ed', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 18, 18, 'አሁን በውድቅትሽ ቀን ደሴቶች ይፈራሉ፥ በባሕርም ውስጥ ያሉ ደሴቶች ከመውጣትሽ የተነሣ ይደነግጣሉ።'),
  ('b177a7c9-6b73-5b0b-a8de-1ce473eaa7ab', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 19, 19, '“ጌታ እግዚአብሔር እንዲህ ይላልና፦ ሰው እንደሌለባቸው ከተሞች ባድማ ከተማ ባደረግሁሽ ጊዜ፥ ቀላዩንም ባወጣሁብሽ ጊዜ፥ ብዙ ውኆችም በከደኑሽ ጊዜ፥'),
  ('d6dfa8a9-450f-5454-ac4d-42ac1b744345', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 20, 20, 'ወደ ጥልቁ ከሚወርዱት ጋር ወደ ቀደሙት ሕዝብ አወርድሻለሁ። በምድርም ላይ በሕይወትሽ ጸንተሽ እንዳትኖሪም ወደ ጕድጓድ ከሚወርዱ ሰዎች ጋር ቀድሞ በፈረሰው ቤት ከምድር በታች አኖርሻለሁ።'),
  ('7b60c1a6-02d1-57e7-a56e-a79d3116b0d3', 'feef0617-4f85-5000-a9ac-454badc84a9d', '4f93be5e-3f5e-5ba2-a0ce-06e55c700e45', 21, 21, 'ለሞት እሰጥሻለሁ፤ ከእንግዲህም አትኖሪም፤ ይፈልጉሻል፥ ለዘለዓለምም አያገኙሽም፤ ይላል ጌታ እግዚአብሔር።”'),
  ('a2ecd67c-0fdd-5006-a9b9-211ad940b453', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('3e588521-f676-582c-a128-11c9dcb788dd', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 2, 2, '“አንተ የሰው ልጅ ሆይ! ስለ ጢሮስ ሙሾ አድርግ።'),
  ('5b98e0f4-c2e5-5047-a7ac-4fd0599afe6a', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 3, 3, 'በባሕር መግቢያ የምትኖር፥ በብዙም ደሴቶች ላይ ከሚኖሩ አሕዛብ ጋር ንግድን የምታደርግ ጢሮስን እንዲህ በላት፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ጢሮስ ሆይ! አንቺ፦ በውበት ፍጹም ነኝ ብለሻል።'),
  ('e8ca8ab7-8d92-5e4d-a156-00853a205ac9', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 4, 4, 'ዳርቻሽ በባሕር ውስጥ ነው፤ ልጆችሽም ውበትሽን ፈጽመዋል።'),
  ('ec2a1e2f-30b3-5b60-a5c0-85ce004417f3', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 5, 5, 'ሳንቃዎችሽን ሁሉ ከሳኔር ጥድ ሠርተዋል፤ ምሰሶዎችሽንም ይሠሩልሽ ዘንድ ከሊባኖስ ዝግባን ወስደዋል።'),
  ('140c02ea-6886-5b41-a709-343ab352e66e', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 6, 6, 'ከባሳን ኮምቦል መቅዘፊያሽን ሠርተዋል፤ መቅደስሽንም በዝኆን ጥርስ ሠሩ፤ ከኪቲም ደሴቶች ዛፍም ቤቶችሽን ሠርተዋል።'),
  ('14a65baf-998a-5b61-a195-abfb3cb110fd', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 7, 7, 'ዓላማ እንዲሆንልሽ ሸራሽ ከግብፅ በፍታና ከወርቀ ዘቦ ተሠርቶአል፤ መደረቢያሽም ከኤሊሳ ደሴቶች ሰማያዊና ቀይ ሐር ተሠርቶአል።'),
  ('697dfa86-0d38-50de-a6b0-c1db3591e275', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 8, 8, 'አለቆችሽ በሲዶና ይኖሩ ነበር፤ የአራድ ሰዎችም ቀዛፊዎችሽ ነበሩ፤ ጢሮስ ሆይ! ጥበበኞችሽ በአንቺ ዘንድ ነበሩ፤ የመርከቦችሽም መሪዎች ነበሩ።'),
  ('a9c25743-da64-57d0-a93d-db9bcbee8a6a', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 9, 9, 'በአንቺ ውስጥ የነበሩ የጌባል ሽማግሌዎችና ጥበበኞችዋ ስብራትሽን ይጠግኑ ነበር፤ ከአንቺም ጋር ይነግዱ ዘንድ የባሕር መርከቦች ሁሉና መርከበኞቻቸው በመካከልሽ ነበሩ።'),
  ('1940a6da-c58a-5c8a-a8b0-757fd0c1d06f', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 10, 10, 'ፋርስና ሉድ፥ ሊብያም በሠራዊትሽ ውስጥ ሰልፈኞችሽ ነበሩ፤ ጋሻና ራስ ቍርም በአንቺ ውስጥ ያንጠለጥሉ ነበር፤ እነርሱም ክብርሽን ሰጡ።'),
  ('4617c3f1-b442-5ac0-a319-612dc0729c18', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 11, 11, 'የአራድ ልጆችና ሠራዊቶችሽ በቅጥሮችሽ ላይ በዙሪያ ነበሩ፤ ገማዳውያንም በግንቦችሽ ውስጥ ነበሩ፤ የጦር መሣሪያቸውንም በዙሪያ በቅጥርሽ ላይ አንጠለጠሉ፤ ውበትሽንም ፈጽመዋል።'),
  ('6dcc86ce-670d-5dc5-abe5-9624916d18f3', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 12, 12, '“ከኀይልሽ ሁሉ ብዛት የተነሣ የተርሴስ ሰዎች ነጋዴዎችሽ ነበሩ፤ ገበያሽን ብር፥ ወርቅና ብረት፥ ቆርቆሮና እርሳስም አደረጉ።'),
  ('40929f45-953a-503e-a1ac-19a47843f271', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 13, 13, 'ያዋንና ቶቤል፥ ሞሳሕም ነጋዴዎችሽ ነበሩ፤ ንግድሽንም በሰዎች ነፍሳትና በናስ ዕቃ አደረጉ።'),
  ('db683fa1-7505-5dc9-a016-a65f4b1b3a70', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 14, 14, 'ከቴርጋማ ቤትም የነበሩት ሰዎች ፈረሶችንና ፈረሰኞችን፥ በቅሎዎችንም ወደ ገበያሽ አመጡልሽ።'),
  ('11f1dcaa-e6f3-5490-a078-b2cde11537ef', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 15, 15, 'የሮድያን ልጆችም ነጋዴዎችሽ ነበሩ፥ ብዙ የሆኑ የደስያት ሰዎችም የዝኆን ጥርስ ይነግዱልሽ ነበር፤ ከዚያም የመጡ ሰዎች ዋጋሽን ይሰጡሽ ነበር።'),
  ('6e8b28d9-cd8d-5a3c-a72b-00ce62b4c478', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 16, 16, 'የሶርያም ሰዎች ከገንዘብሽ ብዛት የተነሣ ነጋዴዎችሽ ነበሩ፥ ከአንቺም ጋር አንድ ከሆኑ ከብዙ ሰዎች ጋር ትነግጂ ነበር፤ ነጭ ሐርንና ዕንቍን፥ ቀይ ሐርንና ወርቀ ዘቦን ከርከዴን የሚባል ዕንቍንና ልባንጃም የሚባል ሽቱን ከተርሴስ ያመጡልሽ ነበር፤ ገበያሽንም ረዓሙትና ቆርኮር መሉት።'),
  ('f65f8a2f-7d04-5c65-a699-22ad032ca360', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 17, 17, 'ይሁዳና እስራኤል ነጋዴዎችሽ ነበሩ፤ ስንዴንም ይሸምቱልሽ ነበር፤ ሰሊሆትንና በለሶንን፥ ዘይትንና የተወደደ ማርን፥ ርጢንንም ከአንቺ ጋር አንድ ይሆኑ ዘንድ ሰጡሽ።'),
  ('e4d1e393-b5c7-5b2d-a6cb-b2a489cde6c4', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 18, 18, 'ከሥራሽ ብዛትና ከብልጽግናሽ ሁሉ ብዛት የተነሣ የደማስቆ ሰዎች ነጋዴዎችሽ ነበሩ፤ በኬልቦን የወይን ጠጅ፥ በነጭም የበግ ጠጕር ይነግዱ ነበር።'),
  ('e0b213cb-87f6-5aa1-a8c4-9d2afdfd2c84', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 19, 19, 'ዳንና ያዋን፤ ከኦሴል የተሠራ ብረትንና ብርጕድን፥ ቀረፋንም ያመጡልሽ ነበር።'),
  ('61786bc0-73a2-5172-ab19-a496751bbe9e', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 20, 20, 'ድዳን በተመረጡ እንስሳትና በሠረገላቸው፥ በክብር ልብስም ነጋዴሽ ነበረች።'),
  ('15220cd0-0726-5ae6-a043-df45e0dd5cc1', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 21, 21, 'ዓረብና የቄዳር አለቆች ሁሉ የእጅሽ ነጋዴዎች ነበሩ፤ በግመሎችና በአውራ በጎች፥ በፍየሎችም በእነዚህ ከአንቺ ጋር ይነግዱ ነበር።'),
  ('45a9c238-083c-5ab3-ad93-0bbcc22eff0c', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 22, 22, 'የሳባና የራዕማ ነጋዴዎች እነዚህ ነጋዴዎችሽ ነበሩ፤ ንግድሽን በጥሩ ሽቱና በከበረ ድንጋይ ሁሉ፥ በወርቅም አደረጉ።'),
  ('4d766a0d-7345-5598-a692-e09b615633b1', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 23, 23, 'የካራንና የካኔ፥ የኤደንም ሰዎች ነጋዴዎችሽ ነበሩ፤ አሦርና ኪልማድም ነጋዴዎችሽ ነበሩ።'),
  ('3e39ee8c-d63b-51c1-ae93-4075951821ca', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 24, 24, 'እነዚህ በአማረ ልብስ፥ በሰማያዊ ካባ፥ በወርቀ ዘቦም፥ በዝግባ በተሠራች፥ በገመድም በታሰረች፥ በግምጃም በተሞላች ሣጥን በገበያሽ ይነግዱ ነበር።'),
  ('1f8dfdfb-d29d-516c-aac9-9a749bf6014f', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 25, 25, 'የተርሴስ መርከቦች ሸቀጥሽን የሚሸከሙ ነበሩ፤ አንቺም ተሞልተሽ ነበር፤ በባሕርም ውስጥ እጅግ ከበርሽ።'),
  ('3e51555f-d8da-5d43-a0bf-7d2cc1957e20', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 26, 26, '“ቀዛፊዎችሽ ወደ ትልቁ ውኃ አመጡሽ፤ የምሥራቅ ነፋስ በባሕር ውስጥ ሰበረሽ።'),
  ('3add8fba-dd80-5f92-ad24-5a58c9191980', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 27, 27, 'ኀይልሽና ዋጋሽ፥ ንግድሽም፥ መርከበኞችሽም፥ መርከብ መሪዎችሽም፥ ሰባራሽን የሚጠግኑ ነጋዴዎችሽም፥ በአንቺም ዘንድ ያሉ ሰልፈኞችሽ ሁሉ በውስጥሽ ከአሉት ጉባኤ ሁሉ ጋር በወደቅሽበት ቀን በባሕር ውስጥ ይጠፋሉ።'),
  ('f962c71a-a154-5143-a5a9-e7ae997638e9', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 28, 28, 'ከጩኸትሽ የተነሣ የመርከብሽ መሪዎች ፍርሀትን ፈሩ።'),
  ('17bd382f-8a02-5c3a-ab5e-0d14c2cf67f1', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 29, 29, 'ቀዛፊዎችም ሁሉ፥ በመርከብ የተጫኑትም መርከብ መሪዎችም ሁሉ ከመርከቦቻቸው ይወርዳሉ፤ በየብስም ላይ ይቆማሉ፤'),
  ('fcf9dc2b-29d3-52fe-a8ea-e37ecc179f44', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 30, 30, 'ድምፃቸውንም በአንቺ ላይ ያሰማሉ፤ ምርር ብለውም ይጮኻሉ፤ በራሳቸውም ላይ ትቢያ ይነሰንሳሉ፤ አመድም ያነጥፋሉ።'),
  ('d86105c3-56fe-58b4-ab66-e1799aef2964', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 31, 31, 'ስለ አንቺም የራሳቸውን ጠጕር ይላጫሉ፤ ማቅም ያሸርጣሉ፤ በነፍስም ምሬት ስለ አንቺ መራራ ልቅሶን ያለቅሳሉ።'),
  ('24533402-5e2f-5763-acbb-54bccaf5c1b7', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 32, 32, 'ልጆቻቸውም ሙሾን ያሞሹልሻል፤ በባሕር መካከል እንደ ታወከች እንደ ጢሮስ ያለ ማን ነበር? ይላሉ።'),
  ('b6a9f3ee-87d7-57aa-ae96-8c85d1dc477b', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 33, 33, 'በባሕር ውስጥ ምን ያህል ዋጋ ታገኚ ነበር? በብልጥግናሽ ብዛት ብዙ አሕዛብን አጠገብሽ፤ ከአንቺም ጋር አንድ ከሆኑት ለይተሽ የምድርን ነገሥታት ሁሉ ባለጸጎች አደረግሻቸው።'),
  ('5e459584-9af5-5d02-abb5-c4cd3bf4b51a', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 34, 34, 'አሁን ግን በጥልቅ ውኃ ውስጥ በባሕር ተሰብረሻል፤ ከአንቺ ጋር አንድ የሆኑ ሁሉ በመካከልሽ ወድቀዋል። ቀዛፊዎችሽም ሁሉ ይወድቃሉ፤'),
  ('5a50ef16-2f87-54ab-a1cb-5edd2b996165', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 35, 35, 'በደሴቶች የሚኖሩ ሁሉ አለቀሱልሽ፤ ነገሥታቶቻቸውም እጅግ ፈርተዋል ፊታቸውንም ነጭተው አለቀሱ።'),
  ('9836c770-a408-56a5-ab43-23fc092beb99', '0592acde-c06d-503c-aca7-981e7731d828', 'bc8a6eec-e8df-58a1-a5ac-e3de1d227927', 36, 36, 'የአሕዛብ ነጋዴዎችም አፍዋጩብሽ፤ አንቺም ፈጽመሽ ትጠፊያለሽ፤ ከእግዲህም ወዲያ እስከ ዘለዓለም አትኖሪም።”'),
  ('94d2c5b4-de32-5c63-a482-72e6954e2abb', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('bb8909d5-b65e-584c-a68b-743db3b0643b', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 2, 2, '“አንተ የሰው ልጅ ሆይ! የጢሮስን አለቃ እንዲህ በለው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ልብህ ኰርትዋል፥ አንተ እኔ እግዚአብሔር ነኝ፥ እግዚአብሔርም በባሕር መካከል እንዲቀመጥ እኔም ተቀምጫለሁ ብለሃልና፤ አንተ ሰው ስትሆን ልብህን እንደ እግዚአብሔር ልብ ብታደርግም አንተ እግዚአብሔር አይደለህም።'),
  ('4e44a083-8e43-5000-acbd-ccf490f11986', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 3, 3, 'ከዳንኤል ይልቅ አንተ ጥበበኛ ነህን? ብልሃተኞችም በጥበባቸው አላስተማሩህም።'),
  ('57a4f8ae-cc18-5981-a289-907a762938d6', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 4, 4, 'በጥበብህና በማስተዋልህ ብልጽግናን ለራስህ አግኝተሃልን? ወርቅንና ብርንም በግምጃ ቤትህ ውስጥ ሰብስበሃልን?'),
  ('e62182a9-ff82-5a9f-ae8e-5036b9e420b0', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 5, 5, 'በታላቅ ጥበብህና በንግድህ ብልጽግናህን አብዝተሃል፤ በብልጽግናህም ልብህ ኰርቶአል።'),
  ('17d2df40-fe82-59a4-abcf-f320cd7d2b06', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 6, 6, 'ሰለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ልብህን እንደ እግዚአብሔር ልብ አድርገሃልና፤'),
  ('8ab83eb1-36dc-5b42-af9e-c4446615524f', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 7, 7, 'ስለዚህ እነሆ የሌላ ሀገር ሰዎችን፥ የአሕዛብ ጨካኞችን አመጣብሃለሁ፤ ሰይፋቸውንም በጥበብህ ውበት ላይ ይመዝዛሉ፤ ክብርህንም ያረክሳሉ።'),
  ('43c54467-a6f0-5dc0-a684-75d7cc23c11f', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 8, 8, 'ወደ ጕድጓድ ያወርዱሃል፤ በሰይፍም ትሞታለህ፤ ሬሳህንም ወደ ባሕር ይጥሉታል።'),
  ('23468d8b-c918-52a4-a3e4-165f1ea0c8eb', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 9, 9, 'አንተ ሰው ስትሆን ለሚገድሉህ ሰዎች፦ እግዚአብሔር ነኝ ትላቸዋለህን? ሰው ነህ እንጂ እግዚአብሔር አይደለህም።'),
  ('65843684-a850-5699-aaa4-c07a22a35769', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 10, 10, 'የሚወጉህም ሰዎች ብዙዎች ናቸው፤ ያልተገረዙትን ሰዎች ሞት ትሞታለህ፤ የሚገድሉህም ሰዎች ያልተገረዙት ናቸው፤ በእጃቸውም ትሞታለህ። እኔ ተናግሬአለሁና ይላል እግዚአብሔር።”'),
  ('5e8ae275-f9e6-5832-aa60-6bd41c4a7e66', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 11, 11, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('ff2cf7a7-af2f-5545-ac8a-1b69f75ca956', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 12, 12, '“የሰው ልጅ ሆይ! በጢሮስ ንጉሥ ላይ ሙሾ አሙሽበት፤ እንዲህም በለው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ጥበብን የተሞላህ፥ ውበትህም የተፈጸመ መደምደሚያ አንተ ነህ።'),
  ('9485a333-b764-5718-a961-d06f82cf2168', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 13, 13, 'በእግዚአብሔር ገነት በዔድን ነበርህ፤ የከበረ ዕንቍስ ሁሉ፥ ሰርድዮን፥ ቶጳዝዮን፥ አልማዝ፥ ቢረሌ፥ መረግድ፥ ኢያሰጲድ፥ ሰንፔር፥ በሉር፥ የሚያብረቀርቅ ዕንቍ፥ ወርቅም ልብስህ ነበረ፤ የከበሮህና የእንቢልታህ ሥራ በአንተ ዘንድ ነበረ፤ በተፈጠርህበትም ቀን ተዘጋጅተው ነበር።'),
  ('f4fecaa1-7e3f-56f4-a660-5c9075db3adb', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 14, 14, 'አንተ ልትጋርድ የተቀባህ ኪሩብ ነበርህ፤ በተቀደሰው በእግዚአብሔር ተራራ ላይ አኖርሁህ፤ በእሳት ድንጋዮች መካከል ተመላለስህ።'),
  ('acd92a7a-38a0-5352-ab32-0bcf63067903', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 15, 15, 'ከተፈጠርህበት ቀን ጀምረህ በደል እስከሚገኝብህ ድረስ በመንገድህ ፍጹም ነበርህ።'),
  ('d59f6daf-d9d3-502e-a38f-b6444a0e7ee1', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 16, 16, 'በንግድህም ብዛት ግፍ በውስጥህ ተሞላ፤ ኀጢአትንም ሠራህ፤ ስለዚህ እንደ ርኩስ ነገር ከእግዚአብሔር ተራራ ጣልሁህ፤ የምትጋርድ ኪሩብ ሆይ! ከእሳት ድንጋዮች መካከል አጠፋሁህ።'),
  ('83d2b1d8-553c-5dde-a31e-7183b5c7d59a', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 17, 17, 'በውበትህ ምክንያት ልብህ ኰርቶአል፤ ከክብርህ የተነሣ ጥበብህን አረከስህ፤ በምድር ላይ ጣልሁህ፤ ያዩህም፥ ይዘብቱብህም ዘንድ በነገሥታት ፊት አሳልፌ ሰጠሁህ።'),
  ('d2ab66c6-125a-52e7-a63b-c4e6d4ae2668', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 18, 18, 'በበደልህ ብዛት፥ በንግድህም ኀጢአት መቅደስህን አረከስህ፤ ስለዚህ እሳትን ከውስጥህ አውጥቻለሁ፤ እርስዋም በልታሃለች፤ በሚያዩህም ሁሉ ፊት በምድር ላይ አመድ አድርጌሃለሁ።'),
  ('1d218045-4902-558f-a78d-8779559f045a', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 19, 19, 'በአሕዛብም ውስጥ የሚያውቁህ ሁሉ ያለቅሱልሃል፤ አንተም ለድንጋጤ ሆነሃል፤ እስከ ዘለዓለምም አትኖርም።”'),
  ('ab100c38-5369-56a9-a358-3778da79054d', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 20, 20, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('a13bcabf-c2c1-5a17-a9f2-d3ca5d37202e', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 21, 21, 'የሰው ልጅ ሆይ! ፊትህን ወደ ሲዶና አቅንተህ ትንቢት ተናገርባት፤ እንዲህም በል፦'),
  ('b6380beb-ffec-5602-aec4-e979240fca1b', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 22, 22, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ሲዶና ሆይ! እነሆ በአንቺ ላይ ነኝ፤ በውስጥሽም እከብራለሁ፤ ፍርድንም በአደረግሁብሽ ጊዜ፥ በተቀደስሁብሽም ጊዜ እኔ እግዚአብሔር እንደ ሆንሁ ታውቂያለሽ።'),
  ('bd0808a9-e5cd-5643-a71d-7b84378417ad', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 23, 23, 'ቸነፈርንም በአንቺ ላይ፥ ደምንም በጎዳናሽ ላይ እሰድዳለሁ፤ ከዙሪያሽም በላይሽ ባለ ሰይፍ የተወጉ በመካከልሽ ይወድቃሉ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('9c09d52e-337b-5c0f-a679-da9a85411dc1', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 24, 24, 'ከእንግዲህም ወዲያ ለእስራኤል ቤት የሚወጋ እሾህ፥ በዙሪያቸውም ከአሉ ከናቋቸው ሁሉ የሚያቈስል ኩርንችት አይሆንም፤ እኔም ጌታ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('88faed69-7f55-5c6c-a578-27ef27597307', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 25, 25, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ የእስራኤልን ቤት ከተበተኑባቸው አሕዛብ ዘንድ እሰበስባቸዋለሁ፤ በአሕዛብና በሕዝብ ፊትም እቀደስባቸዋለሁ፤ ለባሪያዬ ለያዕቆብም በሰጠኋት ምድራቸው ይቀመጣሉ።'),
  ('6d4d02a0-e16c-5868-a3ee-798c2992dba5', '539bbde8-5f4c-585c-a1cb-8183b344a864', '31cbbc2f-ea15-5b9f-a761-a1406fcbe327', 26, 26, 'ተዘልለውም ይቀመጡባታል፤ ቤቶችንም ይሠራሉ፤ ወይኑንም ይተክላሉ፤ በዙሪያቸውም በአሉ በሚንቋቸው ሁሉ ላይ ፍርድን በአደረግሁ ጊዜ ተዘልለው ይቀመጣሉ፤ እኔም እግዚአብሔር አምላካቸው፥ የአባቶቻቸውም አምላክ እንደ ሆንሁ ያውቃሉ።'),
  ('d9f09011-2e7c-528d-af9b-3fb20f62af67', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 1, 1, 'በዐሥረኛው ዓመት በዐሥረኛው ወር ከወሩም በዐሥራ ሁለተኛው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('d9738fa1-1760-5961-a1b9-d31606ed02b1', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 2, 2, '“የሰው ልጅ ሆይ! ፊትህን በግብጽ ንጉሥ በፈርዖን ላይ አድርግ፤ በእርሱና በግብፅ ሁሉ ላይም ትንቢት ተናገር፤'),
  ('b002e41c-cdfb-5907-aee8-6b221eaa9276', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 3, 3, 'እንዲህም በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ በወንዞች መካከል የሚተኛ፥ ወንዙ የእኔ ነው፤ ለራሴም ሠርቼዋለሁ የሚል ታላቅ ዘንዶ የግብፅ ንጉሥ ፈርዖን ሆይ! እነሆ በአንተ ላይ ነኝ።'),
  ('1d145b2c-61d5-5ace-afbb-b672fe90d11e', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 4, 4, 'በመንጋጋዎችህ መቃጥን አገባብሃለሁ፤ የወንዞችህንም ዓሦች ሁሉ ወደ ቅርፊትህ አጣብቃለሁ፤ ከወንዞችህም መካከል አወጣሃለሁ፤ የወንዞችህም ዓሦች ሁሉ ወደ ቅርፊትህ ይጣበቃሉ።'),
  ('b124c838-d2b5-5fc2-a0dc-1de142228429', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 5, 5, 'አንተንና የወንዞችህን ዓሦች ሁሉ ወደ ምድረ በዳ እጥላለሁ፤ በምድርም ፊት ላይ ትወድቃለህ እንጂ አትከማችም፤ አትሰበሰብምም፤ መብልም አድርጌ ለምድር አራዊትና ለሰማይ ወፎች ሰጥቼሃለሁ።'),
  ('62106c5e-a6dd-54ed-a85c-2ecf1bc57b29', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 6, 6, 'ለእስራኤል ቤት የሸንበቆ በትር ሁነሃቸዋልና በግብፅ የሚኖሩ ሁሉ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('fa232c5f-be3f-5145-acee-308006bb05db', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 7, 7, 'በእጅ በያዙህ ጊዜ ተሰበርህ፤ ጫንቃቸውንም ሁሉ አቈሰልህ፤ በተደገፉብህም ጊዜ ተሰበርህ፤ ወገባቸውንም ሁሉ አንቀጠቀጥህ።'),
  ('2859b9fc-acc1-593f-a526-a45c7cea70b7', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 8, 8, '“ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ ሰይፍን አመጣብሃለሁ፦ ሰውንና እንስሳንም ከአንተ ዘንድ አጠፋለሁ።'),
  ('6bce612b-c015-5fdb-a349-4e01e9d49664', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 9, 9, 'የግብፅም ምድር ባድማና ውድማ ትሆናለች፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ፤ አንተ፦ ወንዙ የእኔ ነው፤ የሠራሁትም እኔ ነኝ ብለሃልና።'),
  ('a8e5e006-09ea-509f-aa76-f8a6fc5e65c0', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 10, 10, 'ስለዚህ፥ እነሆ በአንተና በወንዞችህ ላይ ነኝ፤ የግብፅንም ምድር ከሚግዶል ጀምሮ እስከ ሰዌኔና እስከ ኢትዮጵያ ዳርቻ ድረስ በጦርና በቸነፈር ውድማና ባድማ አደርጋታለሁ።'),
  ('5229423c-20da-5821-af88-475d2ea01f5b', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 11, 11, 'የሰው እግር አያልፍባትም፤ የእንስሳም ኮቴ አይረግጣትም፥ እስከ አርባ ዓመትም ድረስ ማንም አይኖርባትም።'),
  ('bfed09bf-9662-53e4-a5bf-cffe43fd5a45', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 12, 12, 'ባድማም በሆኑ ምድሮች መካከል የግብፅን ምድር ባድማ አደርጋታለሁ፤ በፈረሱትም ከተሞች መካከል ከተሞችዋ አርባ ዓመት ፈርሰው ይቀመጣሉ፤ ግብፃውያንንም ወደ አሕዛብ እበትናቸዋለሁ፤ በሀገሮችም እዘራቸዋለሁ።”'),
  ('0d775efd-dce0-53be-a6ce-db586f1b3d10', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 13, 13, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “ከአርባ ዓመት በኋላ ግብፃውያንን ከተበተኑባቸው አሕዛብ ዘንድ እሰበስባለሁ፤'),
  ('8d316755-58e5-5d2d-aa50-02b97218b662', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 14, 14, 'የግብፅንም ምርኮ እመልሳለሁ፤ ወደ ተወለዱባትም ምድር ወደ ጳትሮስ እመልሳቸዋለሁ፤ በዚያም የተዋረደች መንግሥት ይሆናሉ።'),
  ('8112dad0-7dec-580c-a6af-3ed72585d8e9', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 15, 15, 'እንደ ገና በአሕዛብ ላይ ከፍ ከፍ እንዳይሉ ትንሽ መንግሥት ይሆናሉ፤ በአሕዛብም ላይ እንዳይበዙ አሳንሳቸዋለሁ።'),
  ('3e252f3c-b3eb-566e-a8a3-2ce682628b42', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', '29c288f9-f2ad-5f71-a95e-162c178d92e8', 16, 16, 'የእስራኤል ቤት እነርሱን በተከተሉ ጊዜ እርስዋ በደልን ታሳስባለች፤ ከእንግዲህም ወዲያ መታመኛ አትሆንላቸውም፤ እኔም ጌታ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('81266e30-b944-57ba-a6a6-b033edb9455d', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', 'c2e20d20-adc8-5536-a1a4-d387a6bbc127', 1, 17, 'እንዲህም ሆነ፤ በሃያ ሰባተኛው ዓመት በመጀመሪያው ወር ከወሩም በመጀመሪያው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('aee7de8a-1bcc-5860-a405-8c72b00620b3', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', 'c2e20d20-adc8-5536-a1a4-d387a6bbc127', 2, 18, '“የሰው ልጅ ሆይ! የባቢሎን ንጉሥ ናቡከደነፆር ሠራዊቱን በጢሮስ ላይ ጽኑ ሥራን አሠራቸው፤ ራስ ሁሉ የተላጨ፥ ጫንቃም ሁሉ የተላጠ ሆኖአል፤ ነገር ግን በላይዋ ስለ አሠራው ሥራ እርሱና ሠራዊቱ ከጢሮስ ደመወዝ አልተቀበሉም።'),
  ('4b642833-eb8b-5c98-a29d-8115717ea0cf', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', 'c2e20d20-adc8-5536-a1a4-d387a6bbc127', 3, 19, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ የግብፅን ምድር ለባቢሎን ንጉሥ ለናቡከደነፆር እሰጠዋለሁ፤ ብዛቷንም ይወስዳል፤ ምርኮዋንም ይማርካል፤ ብዝበዛዋንም ይበዘብዛል፤ ይህም ለሠራዊቱ ደመወዝ ይሆናል።'),
  ('a3c62719-51da-5591-a7f5-5ef8df28b89d', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', 'c2e20d20-adc8-5536-a1a4-d387a6bbc127', 4, 20, 'ስለ እኔ ሠርተዋልና በጢሮስ ላይ ስለ አገለገለው አገልግሎት የግብፅን ምድር ደመወዝ አድርጌ ሰጥቼዋለሁ፥ ይላል ጌታ እግዚአብሔር።'),
  ('ca944c4c-c1e0-5cc9-a991-36fc90d5cc9f', 'ee5429f8-7d3d-587d-ab34-af0ce95e191c', 'c2e20d20-adc8-5536-a1a4-d387a6bbc127', 5, 21, '“በዚያ ቀን ለእስራኤል ቤት ቀንድን አበቅላለሁ፤ በመካከላቸውም ለአንተ የተከፈተ አፍን እሰጥሀለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('9575e9e3-cdeb-5d5e-a22a-9835d2bf0931', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('23a11703-e262-5875-a768-96106738447a', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 2, 2, '“የሰው ልጅ ሆይ! ትንቢት ተናገር፤ እንዲህም በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ዋይ! በሉ፥ ለቀኑ ወዮ!'),
  ('c3bcef01-a224-5669-a3e4-5fafc390ed69', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 3, 3, 'ቀኑ ቅርብ ነው፤ የእግዚአብሔር ቀን ቅርብ ነው፤ የደመና ቀን፥ የአሕዛብ ማለቂያ ጊዜ ይሆናል።'),
  ('ce704d1f-caf6-5dae-ae3f-a1aacf1504ba', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 4, 4, 'ሰይፍ በግብፅ ላይ ይመጣል፤ ሁከትም በኢትዮጵያ ይሆናል፤ የተገደሉትም በግብፅ ውስጥ ይወድቃሉ፤ ብዛቷንም ይወስዳሉ፤ መሠረቷም ይፈርሳል።'),
  ('242503dd-b527-5132-aca7-30113bdcaa13', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 5, 5, 'ኢትዮጵያና ፉጥ፥ ሉድም፥ ዓረብም ሁሉ፥ ኩብም፤ ሊብያም፤ ቀርጤስም የተደባለቀ ሕዝብም ሁሉ፥ ቃል ኪዳንንም የገባችው ምድር ልጆች ከእነርሱ ጋር በሰይፍ ይወድቃሉ።'),
  ('ea4230ea-26eb-599e-a294-02f910505030', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 6, 6, '“እግዚአብሔርም እንዲህ ይላል፦ ግብፅን የሚደግፉ ይወድቃሉ፤ የኀይልዋም ትዕቢት ይወርዳል፤ ከሚግዶል ጀምሮ እስከ ሰዌኔ ድረስ በእርስዋ ውስጥ በሰይፍ ይወድቃሉ፥ ይላል ጌታ እግዚአብሔር።'),
  ('9545033c-0e9c-51f4-a2f4-547f055216b8', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 7, 7, 'ባድማም በሆኑ ሀገሮች መካከል ባድማ ይሆናሉ፤ ከተሞችዋም በፈረሱ ከተሞች መካከል ይሆናሉ።'),
  ('c9e1ac07-0cff-5750-a32d-958cf97df2ee', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 8, 8, 'እሳትንም በግብፅ ላይ በአነደድሁ ጊዜ፥ ረዳቶችዋም ሁሉ በተሰበሩ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('9fac5e10-7114-5f89-ad90-b80c9c4992b6', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 9, 9, 'በዚያ ቀን መልእክተኞች ተዘልለው የሚኖሩትን ኢትዮጵያውያንን ለማጥፋት ከፊቴ በመርከብ ይወጣሉ፤ በግብፅም ቀን ሁከት ይሆንባቸዋል፤ እነሆ፥ ይመጣልና።'),
  ('cc58a39b-cf3f-5c4f-a761-77bc74c67067', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 10, 10, '“ጌታ እግዚአብሔር እንዲህ ይላል፦ የግብፅን ብዛት በባቢሎን ንጉሥ በናቡከደነፆር እጅ አጠፋለሁ።'),
  ('da05f712-2500-5c86-af55-1ad256e02a7d', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 11, 11, 'እርሱና ሕዝቡ የአሕዛብም ኀያላን ምድሪቱን ለማጥፋት ይላካሉ፤ ግብፃውያንንም በሰይፍ ይወጉአቸዋል፤ ምድሪቱም በሙታን ትሞላለች።'),
  ('1ed745a7-6e7c-5756-ae7a-e0075a1bfbc8', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 12, 12, 'ወንዞችንም ምድረ በዳ አደርጋለሁ፤ ምድሪቱንም በክፉ ሰዎች እጅ እሰጣለሁ፥ ምድሪቱንና ሞላዋንም በባዕዳን እጅ ባድማ አደርጋለሁ፤ እኔ እግዚአብሔር ተናግሬአለሁ።'),
  ('87aa2303-2963-50d1-a8ea-c45f24066809', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 13, 13, '“ጌታ እግዚአብሔር እንዲህ ይላል፦ ጣዖቶቹን አጠፋለሁ፤ ምስሎቹንም ከሜምፎስ እሽራለሁ፤ ከእንግዲህ ወዲያም በግብፅ ምድር አለቃ አይሆንም፤ በግብፅ ምድር ላይም ፍርሀትን አደርጋለሁ።'),
  ('56f443d8-6a09-5934-a818-b36e7d3c257e', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 14, 14, 'ጳትሮስንም አፈርሳለሁ፤ በጣኔዎስም ላይ እሳትን አነድዳለሁ፤ በዲዮስጶሊን ላይም ፍርድን አደርጋለሁ።'),
  ('44d31960-7bfa-5f4d-a949-8a4a3be53d6b', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 15, 15, 'በግብፅም ኀይል በሲን ላይ መዓቴን አፈስሳለሁ፤ የሜምፎስንም ብዛት አጠፋለሁ።'),
  ('6d1c0bde-0850-5e95-ad4d-d2fd6b661d48', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 16, 16, 'በግብፅም ላይ እሳትን አነድዳለሁ፤ ሲንም ትታወካለች፤ ኖእም ትሰበራለች፤ ሜምፎስም ምድረ በዳ ትሆናለች።'),
  ('308a4325-4490-5c52-a48f-ee5b50de4cd5', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 17, 17, 'የሄልዮቱ ከተማና የቡባስቱም ጐልማሶች በሰይፍ ይወድቃሉ፤ ሴቶችም ይማረካሉ።'),
  ('07c332a3-4cd3-5948-a24b-6b440780e77e', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 18, 18, 'የግብፅን ቀንበር በዚያ በሰበርሁ ጊዜ በጣፍናስ ቀኑ ይጨልማል፤ የኀይልዋም ትዕቢት ይጠፋባታል፤ ደመናም ይጋርዳታል፤ ሴቶች ልጆችዋም ይማረካሉ።'),
  ('b6509907-8beb-537c-ac5f-66c3951501ba', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 19, 19, 'እንዲሁ በግብፅ ላይ ፍርድን አደርጋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('78f01fa6-665f-590e-adec-3249b6b23095', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 20, 20, 'እንዲህም ሆነ፤ በዐሥራ አንደኛው ዓመት በመጀመሪያው ወር ከወሩም በሰባተኛው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('91f5251d-3ca8-5484-a396-c8c4b9f5795f', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 21, 21, '“የሰው ልጅ ሆይ! የግብፅን ንጉሥ የፈርዖንን ክንድ ሰብሬአለሁ፥ እነሆም ይድን ዘንድ መድኃኒት ቀብተው አያደርቁትም፤ ሰይፉንም ለመያዝ ኀይልን ያገኝ ዘንድ አልታሰረም።'),
  ('07499c17-1d5c-5466-a0cb-e64b004956db', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 22, 22, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ እኔ በግብፅ ንጉሥ በፈርዖን ላይ ነኝ የጸናችውንና የተሰበረችውንም ክንዱን እሰብራለሁ፤ ሰይፉንም ከእጁ አስጥለዋለሁ።'),
  ('bc59bfdd-1a25-5c1a-af09-0353e3bc648e', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 23, 23, 'ግብፃውያንንም በአሕዛብ መካከል እበትናለሁ፤ በሀገሮችም መካከል እዘራቸዋለሁ።'),
  ('a19c4d3a-53ef-56a5-a9e9-3901a127a0bc', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 24, 24, 'የባቢሎንንም ንጉሥ ክንድ አበረታለሁ፤ ሰይፌንም በእጁ እሰጣለሁ፤ ግብፅንም ይወጋበታል፥ ምርኮዋንም ይማርካል፤ ሰለባዋንም ይሰልባል።'),
  ('1a951cd5-3c72-5ad3-a230-57b3ca6b3e28', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 25, 25, 'የባቢሎንንም ንጉሥ ክንድ አጸናለሁ፤ የፈርዖንም ክንድ ይወድቃል፤ ሰይፌንም በባቢሎን ንጉሥ እጅ በሰጠሁ ጊዜ፥ እርሱም በግብፅ ምድር ላይ በዘረጋው ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('f334aa9f-7c7f-53ae-acaf-b1df31bd9be3', 'aa3de900-d82c-509c-ae49-9e4c97ec71eb', '8c9bb021-6d52-5c09-a94d-c01086a8e259', 26, 26, 'ግብፃውያንንም በአሕዛብ መካከል እበትናለሁ፤ በሀገሮችም መካከል እዘራቸዋለሁ፤ ሁሉም እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('62736d36-9149-5809-a7b5-b376c5880683', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 1, 1, 'እንዲህም ሆነ፤ በዐሥራ አንደኛው ዓመት በሦስተኛው ወር ከወሩም በመጀመሪያው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('1a243b04-b721-558e-aba5-e7ea928c1315', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 2, 2, '“የሰው ልጅ ሆይ! የግብፅን ንጉሥ ፈርዖንንና ሕዝቡን እንዲህ በላቸው፦ በታላቅነትህ ማንን ትመስላለህ?'),
  ('ac064715-2586-5bc9-ab4e-3ea038d1e1fa', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 3, 3, 'እነሆ አሦር ጫፉ እንደ ተዋበ፥ ችፍግነቱ ጥላ እንደ ሰጠ፥ ቁመቱም እንደ ረዘመ፥ ራሱም ወደ ደመናዎች እንደ ደረሰ እንደ ሊባኖስ ዝግባ ነበረ።'),
  ('c20de998-3f67-5e0c-a69a-dcd1060598d2', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 4, 4, 'ውኃም አበቀለው፥ ቀላይም አሳደገው፥ ወንዞችም በተተከለበት ዙሪያ ይጎርፉ ነበር፤ ፈሳሾቹንም ወደ ምድረ በዳ ዛፍ ሁሉ ላከ።'),
  ('52bbbc74-d973-5286-a9f5-39c854b6f214', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 5, 5, 'ስለዚህ ቁመቱ ከምድረ በዳ ዛፍ ሁሉ በላይ ከፍ ከፍ አለ፤ ቅርንጫፎቹም በዙ፤ ጫፎቹም ከብዙ ውኆች የተነሣ ረዘሙ።'),
  ('5196f452-ec61-52e4-af00-1d5aaec15b8b', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 6, 6, 'የሰማይም ወፎች ሁሉ በቅርንጫፎቹ ላይ ተዋለዱ፤ የምድርም አራዊት ሁሉ ከጫፎቹ በታች ተዋለዱ፤ ከጥላውም በታች ታላላቆች አሕዛብ ሁሉ ይቀመጡ ነበር።'),
  ('4638bed7-f2e7-5ae6-ae98-cc3bd2812ab7', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 7, 7, 'ሥሩም በብዙ ውኃ አጠገብ ነበረና በታላቅነቱና በጫፎቹ ርዝመት የተዋበ ነበረ።'),
  ('2681dcb9-1ea3-5b69-af5a-7cbe1e02e4eb', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 8, 8, 'በእግዚአብሔር ገነት የነበሩ ዝግባዎች አይተካከሉትም፥ ጥዶችም ቅርንጫፎቹን፥ አስታ የሚባለውም ዛፍ ጫፎቹን አይመሳሰሉትም ነበር፤ የእግዚአብሔርም ገነት ዛፍ ሁሉ በውበቱ አይመስለውም ነበር።'),
  ('e18b72fb-d06d-5ec1-ad8e-d9a2d44d92dc', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 9, 9, 'በጫፎቹ ብዛት ውብ አደረግሁት፤ በእግዚአብሔርም ገነት በዔድን የነበሩ ዛፎች ሁሉ ቀኑበት።'),
  ('efaa3fac-0832-52e6-a4ba-8823b553780f', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 10, 10, '“ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ቁመትህ ከፍ ከፍ ብሎአልና፥ ራስህም በደመናት መካከል ደርሶአልና፤ ትዕቢቱንም አየሁ፤'),
  ('17cda5d3-9ff1-59a4-a5ac-d5243ef95032', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 11, 11, 'በአሕዛብም አለቆች እጅ አሳልፌ እሰጠዋለሁ፤ እርሱም እንደ ክፋቱ መጠን ያደርግበታል፤ እኔም አሳድደዋለሁ።'),
  ('1e4e469c-1803-5d0e-a373-902eca84903d', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 12, 12, 'የሌላ ሀገር ሰዎች፥ የአሕዛብ ጨካኞች የሆኑ፥ ቈርጠው ጣሉት፤ በተራሮችና በሸለቆዎች ሁሉ ውስጥ ጫፎቹ ወደቁ፤ ቅርንጫፎቹም በምድር ፈሳሾች ሁሉ ላይ ተሰባበሩ፤ የምድርም አሕዛብ ሁሉ ከጥላው ተመልሰው ተዉት።'),
  ('78575381-6e75-5b1d-aff4-c34ff2aad330', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 13, 13, 'በወደቀው ግንድ ላይ የሰማይ ወፎች ሁሉ ይቀመጣሉ፤ የምድርም አራዊት ሁሉ በቅርንጫፎቹ ላይ ይሆናሉ።'),
  ('bc5a22e8-d261-5e3a-ae5a-6d3490a288b6', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 14, 14, 'በውኃው አጠገብ ያሉ የዕንጨቶች ሁሉ ቁመት እንዳይረዝም ራሱም ወደ ደመና እንዳይደርስ ያንም ውኃ የሚጠጡት እንጨቶች ሁሉ በርዝመታቸው ከእርሱ ጋራ እንዳይተካከሉ ሁሉም ወደ መቃብር በሚወርዱ ሰዎች መካከል በጥልቅ ምድር ሞቱ።'),
  ('2122b290-b74d-5d17-a97f-44e7a2504cc3', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 15, 15, '“ጌታ እግዚአብሔር እንዲህ ይላል፦ ወደ ሲኦል በወረደበት ቀን ልቅሶን አስለቀስሁ፤ ቀላዩንም ስለ እርሱ ሸፈንሁት፤ ፈሳሾችንም ከለከልሁ፤ ታላላቆችም ውኆች ተከለከሉ፤ ሊባኖስንም ስለ እርሱ አሳዘንሁት። የዱርም ዛፎች ሁሉ ስለ እርሱ ዛሉ።'),
  ('8f063364-8f87-570d-a1bc-03a1eb64cbee', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 16, 16, 'ወደ ጕድጓድ ከሚወርዱ ጋር ወደ ሲኦል በጣልሁት ጊዜ ከመውደቁ ድምፅ የተነሣ አሕዛብን አንቀጠቀጥሁ፤ ውኃም የሚጠጡ ሁሉ፥ ምርጦችና መልካሞች የሊባኖስ ዛፎች፥ የዔድን ዛፎች ሁሉ በታችኛው ምድር ውስጥ ተጽናንተዋል።'),
  ('ae53dca0-5a1e-5098-ab17-c2e5700235ab', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 17, 17, 'እነርሱም በሰይፍ ወደ ተገደሉት ወደ ሲኦል ከእርሱ ጋር ወረዱ፤ በጥላው ሥር ይኖሩ የነበሩ ዘሮቹም በአሕዛብ መካከል ጠፉ።'),
  ('8e63197b-3371-544a-acaa-54415d9f1fc3', '1e9f38d9-2ed7-52c1-aea6-c33deb980cc5', 'ff9bbfbd-eba7-5e4b-a4b7-aa7904dada0c', 18, 18, '“በክብርና በታላቅነት በዔድን ዛፎች መካከል ማንን ትመስላለህ? ነገር ግን ከዔድን ዛፎች ጋር ወደ ታችኛው ምድር ያወርዱሃል፤ በሰይፍም በተገደሉት ባልተገረዙት መካከል ትተኛለህ። ይህም ፈርዖንና የሕዝቡ ብዛት ሁሉ ነው፥” ይላል ጌታ እግዚአብሔር።'),
  ('3a0d2794-0cbc-573c-ab67-4c9048218e0c', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 1, 1, 'እንዲህም ሆነ፤ በዐሥራ ሁለተኛው ዓመት በዐሥራ ሁለተኛው ወር ከወሩም በመጀመሪያው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('5b82d21d-a5dc-5c79-a03a-5873e1ceb804', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 2, 2, '“የሰው ልጅ ሆይ! ስለ ግብፅ ንጉሥ ስለ ፈርዖን ሙሾ አሙሽ፤ እንዲህም በለው፦ የአሕዛብን አንበሳ መስለህ ነበር፤ ነገር ግን እንደ ባሕር ዘንዶ ሆነሃል፤ ወንዞችህንም ወግተሃል፤ ውኃውንም በእግርህ አደፍርሰሃል፥ ወንዞችህንም በተረከዝህ ረግጠሃል።'),
  ('8d987485-de59-50c3-a458-8133c520192e', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 3, 3, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ በብዙ አሕዛብ ጉባኤ መረቤን እዘረጋብሃለሁ፤ በመረቤም አወጣሃለሁ።'),
  ('838a67bf-1c58-5cd0-abf2-c882ac8c83a9', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 4, 4, 'በሰፊ ምድረ በዳም እጥልሃለሁ፤ የሰማይንም ወፎች ሁሉ አሳርፍብሃለሁ፤ የምድርንም አራዊት ሁሉ ከአንተ አጠግባቸዋለሁ።'),
  ('6c57e83d-3728-510b-a1ba-2d83c7b99840', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 5, 5, 'ሥጋህን በተራሮች ላይ አደርጋለሁ፤ በደምህም አረካቸዋለሁ።'),
  ('34b975d2-fa09-527d-ac67-dce20a661a22', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 6, 6, 'የምቷኝባትንም ምድር እስከ ተረራሮች ድረስ በደምህ አጠጣለሁ፤ መስኖዎችም ከአንተ ይሞላሉ።'),
  ('33645dca-ec60-54f8-ae13-92000b9622e0', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 7, 7, 'በጠፋህም ጊዜ ሰማዮችን እሸፍናለሁ፤ ከዋክብትንም አጨልማለሁ፤ ፀሐዩንም በደመና እሸፍናለሁ፤ ጨረቃም ብርሃኑን አይሰጥም።'),
  ('928c6efc-5f1b-578e-a9fa-83cd308a1f34', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 8, 8, 'የሰማይን ብርሃኖች ሁሉ በላይህ አጨልማለሁ፤ በምድርህም ላይ ጨለማን አደርጋለሁ፥ ይላል ጌታ እግዚአብሔር።'),
  ('8c8872fb-4645-51c5-a1ff-308b2664d7ef', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 9, 9, 'በማታውቃቸውም ሀገሮች በአሉ በአሕዛብ ዘንድ ድል መሆንህን በአሰማሁ ጊዜ የብዙ ሕዝብን ልብ አስጨንቃለሁ።'),
  ('98240cd1-c867-55c2-a916-c78f66eeb11a', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 10, 10, 'ብዙ አሕዛብን አስደንቅብሃለሁ፤ ሰይፌም በፊታቸው በተወረወረች ጊዜ ንጉሦቻቸው እጅግ አድርገው ይፈራሉ፤ በወደቅህባትም ቀን እያንዳንዱ ስለ ነፍሱ በየጊዜው ይንቀጠቀጣል።”'),
  ('452347c1-0650-5d6f-a1e6-9f819c04854c', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 11, 11, 'ጌታ እግዚአብሔር እንዲህ ይላልና፥ “የባቢሎን ንጉሥ ሰይፍ ይመጣብሃል።'),
  ('fdcc136f-5141-5767-af29-5e2d1f1963e1', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 12, 12, 'በኀያላን ሰይፍ ኀይልህን እጥላለሁ፤ ሁሉ የአሕዛብ ጨካኞች ናቸው፤ የግብፅንም ትዕቢት ያጠፋሉ፤ ኀይልዋም ሁሉ ይደመሰሳል።'),
  ('a3cea74c-2fa6-5449-ac18-ba6ca11cbb9f', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 13, 13, 'በብዙም ውኃ አጠገብ ያሉትን እንስሶች ሁሉ አጠፋለሁ፤ ከእንግዲህም ወዲያ የሰው እግር አያደፈርሳትም፤ የእንስሳም ኮቴ አይረግጣትም።'),
  ('e9dd4880-7d12-514a-ad52-d8f63309f42f', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 14, 14, 'በዚያን ጊዜ ውኆቻቸውን አጠራለሁ፤ ወንዞቻቸውም እንደ ዘይት ይፈስሳሉ፤ ይላል ጌታ እግዚአብሔር።'),
  ('d51f36b3-349d-5693-ae1a-873797a2cd94', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 15, 15, 'የግብፅንም ምድር ባድማና ውድማ በአደረግሁ ጊዜ፥ ምድርም በመላዋ በጠፋች ጊዜ፥ የሚኖሩባትንም ሁሉ በቀሠፍሁ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('689ec653-96c0-5da2-a09d-3d16ddac3dc3', '86040fc6-355e-53cd-a6ab-ff69966495c5', '359d5b4b-4b3c-52ca-a9b5-4961fc5b5cbc', 16, 16, 'ይኸውም ሙሾ ነው፤ ሙሾን ያሞሹለታል፤ የአሕዛብ ሴቶች ልጆች ያሞሹለታል፤ ስለ ግብፅና ስለ ኀይልዋ ሁሉ ያሞሹለታል፥” ይላል ጌታ እግዚአብሔር።'),
  ('6ff7bed3-277e-5636-ae9c-99864dc69fd7', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 1, 17, 'እንዲህም ሆነ፤ በዐሥራ ሁለተኛው ዓመት በመጀመሪያው ወር ከወሩም በዐሥራ አምስተኛው ቀን የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('8ed287fd-3039-55ae-af59-844b6a1c4c4d', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 2, 18, '“የሰው ልጅ ሆይ! ስለ ግብፅ ኀይል ዋይ በል፤ እርስዋንና የብርቱዎቹን አሕዛብ ሴቶች ልጆች ወደ ጕድጓድ ከሚወርዱ ጋር ወደ ታችኛው ምድር ጣላቸው።'),
  ('2cea3884-7423-5c57-a006-f088e3e884af', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 3, 19, 'በውበት የምትበልጪው ማን ነው? ውረጂ ካልተገረዙትም ጋር ተኚ።'),
  ('73aebffb-bc5f-5b31-aac9-4e48634438da', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 4, 20, 'በሰይፍ በተገደሉት መካከል ከእርሱ ጋር በሰይፍ ይወድቃሉ፤ ኀይሉም ሁሉ ይጠፋል፤ እርስዋንና ብዛቷን ሁሉ ጐትቱ።'),
  ('78d2e1fb-f14c-5189-a990-780db7fd7870', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 5, 21, 'የኀያላን አለቆች በሲኦል ውስጥ ሆነው ከረዳቶቹ ጋር ይናገሩታል፤ በሰይፍም የተገደሉት ያልተገረዙ ወርደው ተኝተዋል።'),
  ('e849d31d-659b-5d8e-a637-9333f674eb09', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 6, 22, '“አሦርና ሠራዊቱ ሁሉ በዚያ ተገደሉ፤ ሁሉም ድል ተነሡ፤ ወደ ጥልቅ ዐዘቅትም ጣሉአቸው ሠራዊቱም በመቃብር ዙሪያ ናቸው፤ ሁሉም በሰይፍ ወድቀው ተገደሉ።'),
  ('bb9b82bf-e1af-5cd0-a30b-234567c82332', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 7, 23, 'መቃብራቸው በጕድጓዱ በውስጠኛው ክፍል ነው፤ ጉባኤዋም በመቃብርዋ ዙሪያ ነው፤ በሕያዋን ምድር ያስፈሩ ሁሉ በሰይፍ ወድቀው ተገድለዋል።'),
  ('919baeff-38e1-5d85-acdd-f013393b8b3e', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 8, 24, '“ኤላምም በዚያ አለች፤ ኀይልዋም ሁሉ በመቃብርዋ ዙሪያ ነው፤ በሕያዋን ምድር ያስፈሩ ሁሉ በሰይፍ ወድቀው ተገድለዋል፤ ሳይገረዙም ወደ ታችኛው ምድር ወርደዋል፤ ወደ ጕድጓድም ከሚወርዱ ጋር ቅጣታቸውን አግኝተዋል።'),
  ('fb207205-38f1-5e40-ad2e-38ec00f75764', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 9, 25, 'በተገደሉት መካከል ከብዛቷ ሁሉ ጋር መኝታን አድርገውላታል፤ መቃብርዋ በዙሪያዋ ነው፤ ሁሉም ያልተገረዙና በሰይፍ የተገደሉ ናቸው፤ በሕያዋንም ምድር ያስፈሩ ነበር፤ ወደ ጕድጓድም ከሚወርዱ ጋር እፍረታቸውን ተሸክመዋል፤ በተገደሉትም መካከል ተሰጥተዋል።'),
  ('54aa391e-9807-514f-a1fc-c14abf7861c7', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 10, 26, '“ሞሳሕና ቶቤል፥ ሠራዊታቸውም ሁሉ በዚያ አሉ፤ መቃብራቸውም በዙሪያቸው ነው፤ ሁሉም ሳይገረዙ በሰይፍ ተገድለዋል፤ በሕያዋን ምድር ያስፈሩ ነበርና።'),
  ('b175a1a9-00d5-53bc-a0ee-08df0516ed59', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 11, 27, 'በሕያዋንም ምድር ኀያላኑን ያስፈሩ ነበርና፤ መሣሪያቸውን ይዘው ወደ ሲኦል ከወረዱ፥ ሰይፋቸውንም ከራሳቸው በታች ከአደረጉ፥ ኀጢአታቸውም በአጥንታቸው ላይ ከሆነ ጋር ከወደቁ ካልተገረዙ ኀያላን ጋር ይተኛሉ።'),
  ('84d62b2f-8da3-535e-a22f-cbd9dc7c88c0', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 12, 28, 'አንተም ደግሞ ባልተገረዙት መካከል ትሰበራለህ፤ በሰይፍም ከተገደሉት ጋር ትተኛለህ።'),
  ('d5c28fb1-dee1-5cc9-ab31-39f272f64061', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 13, 29, '“ኤዶምያስና ነገሥታቷ፥ አለቆችዋም ሁሉ በዚያ አሉ፤ በሰይፍ ከተገደሉት ጋር'),
  ('23cd8f19-a95f-5a7b-ab1d-c3b931cd78ea', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 14, 30, 'ከአልተገረዙና ወደ ጕድጓድ ከሚወርዱ ጋር ተኝተዋል፤ የሰሜን አለቆች ሁሉ፥ ሲዶናውያንም ሁሉ ከተገደሉት ጋር ወርደው በዚያ አሉ፤ በኀይላቸውም ያስፈሩ በነበረው ፍርሀት አፍረዋል፤ በሰይፍም ከተገደሉት ጋር ያልተገረዙት ተኝተዋል፤ ወደ ጕድጓድም ከሚወርዱት ጋር ቅጣታቸውን ተሸክመዋል።'),
  ('c2f86633-502a-511d-a204-bb8889128686', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 15, 31, '“በሰይፍ የተገደሉ ፈርዖንና ሠራዊቱ ሁሉ ያዩአቸዋል፤ ፈርዖንም ስለ ኀይላቸው ሁሉ ይጽናናል፥ ይላል ጌታ እግዚአብሔር።'),
  ('669b1588-ed7b-50b8-ad98-a1df72ee05ba', '86040fc6-355e-53cd-a6ab-ff69966495c5', '5e418699-f785-5c87-ad1a-608fbe32fd81', 16, 32, 'መፈራቴን በሕያዋን ምድር አድርጌአለሁ፤ ፈርዖንና ሠራዊቱ ሁሉ በሰይፍ በተገደሉት፥ ባልተገረዙት መካከል ይተኛሉ፥” ይላል ጌታ እግዚአብሔር።'),
  ('c26519ef-cb39-5bd0-ac54-395dd0f02b85', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('ab73e2f5-a66d-551f-a0d0-d7d26f375097', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 2, 2, '“የሰው ልጅ ሆይ! ለሕዝብህ ልጆች ተናገር እንዲህም በላቸው፦ ጦርን በምድር ላይ በአመጣሁ ጊዜ፥ የምድር ሕዝብ ከመካከላቸው አንድ ሰውን ወስደው ለራሳቸው ጕበኛ ቢያደርጉ፥'),
  ('476ccc6c-5cec-54f4-a6fd-f34fe5ba6a64', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 3, 3, 'እርሱም በምድር ላይ የመጣውን ጦር በአየ ጊዜ መለከትን ቢነፋ፥ ሕዝቡንም ቢያስጠነቅቅ፤'),
  ('e63de123-5060-5c7d-aeb1-6268d5ac0de2', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 4, 4, 'የመለከቱን ድምፅ የሚሰማ ሰው ባይጠነቀቅ፥ ጦር መጥቶ ቢወስደው፥ ደሙ በራሱ ላይ ይሆናል።'),
  ('ec04d1b5-9977-5f5c-aec0-02324eebf19f', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 5, 5, 'የመለከቱን ድምፅ ሰምቶ ስላልተጠነቀቀ ደሙ በራሱ ላይ ይሆናል፤ ቢጠነቀቅስ ኖሮ ነፍሱን በአዳነ ነበር።'),
  ('605a012e-75cb-5b20-a3b1-24887daaae2f', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 6, 6, 'ጕበኛው ግን ጦር ሲመጣ ቢያይ፥ መለከቱንም ባይነፋ፥ ሕዝቡንም ባያስጠነቅቅ፥ ጦርም መጥቶ አንድ ሰው ከእነርሱ ቢወስድ፥ እርሱ በኀጢአቱ ተወስዶአል፤ ደሙን ግን ከጕበኛው እጅ እፈልጋለሁ።'),
  ('c9b9072f-79c0-5771-a405-b655caa1b165', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 7, 7, '“አንተም የሰው ልጅ ሆይ! ለእስራኤል ቤት ጕበኛ አድርጌሃለሁ፤ ከአፌ ቃሌን ስማ፤ ከእኔም ዘንድ አስጠንቅቃቸው።'),
  ('a034a818-b8a8-5784-abc7-be87dfdc963c', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 8, 8, 'ኀጢአተኛውን፦ ኀጢአተኛ ሆይ! በርግጥ ትሞታለህ ባልሁ ጊዜ፥ ኀጢአተኛውን ከክፉ መንገዱ ታስጠነቅቅ ዘንድ ባትናገር፥ ያ ኀጢአተኛ በኀጢአቱ ይሞታል፤ ደሙን ግን ከእጅህ እፈልጋለሁ።'),
  ('84c05dda-2c2b-570d-ac5b-ea2845ba9fa1', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 9, 9, 'ነገር ግን ከመንገዱ ይመለስ ዘንድ ኀጢአተኛውን ብታስጠነቅቀው፥ እርሱም ከመንገዱ ባይመለስ፥ በኀጢአቱ ይሞታል፤ አንተ ግን ነፍስህን ታድናለህ።'),
  ('e19b053d-b935-5eaa-a81a-e2c12d1ef6c1', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 10, 10, '“አንተም የሰው ልጅ ሆይ! የእስራኤልን ቤት፦ እናንተ፦ በደላችንና ኀጢአታችን በላያችን አሉ፤ እኛም ሰልስለንባቸዋል፤ እንዴትስ በሕይወት እንኖራለን? ብላችሁ ተናግራችኋል በላቸው።'),
  ('3ed46e44-ed00-5621-a89c-ffe524c9ef93', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 11, 11, 'እኔ ሕያው ነኝና ኀጢአተኛው ከመንገዱ ተመልሶ በሕይወት ይኖር ዘንድ እንጂ ኀጢአተኛው ይሞት ዘንድ አልፈቅድም፤ ይላል ጌታ እግዚአብሔር፤ የእስራኤል ቤት ሆይ! ተመለሱ፤ ከክፉ መንገዳችሁ ተመለሱ፤ ስለ ምንስ ትሞታላችሁ? በላቸው።'),
  ('40cd1b61-d2d6-5585-a265-17ad0df7ea26', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 12, 12, 'አንተም የሰው ልጅ ሆይ! የሕዝብህን ልጆች እንዲህ በላቸው፦ በበደለበት ቀን የጻድቅ ጽድቁ አያድነውም፤ ኀጢአተኛም ከኀጢአቱ በተመለሰበት ቀን በኀጢአቱ አይሰናከልም፤ ጻድቁም ኀጢአት በሠራበት ቀን በጽድቁ በሕይወት አይኖርም።'),
  ('a28a5c9b-c8fd-520b-aba2-b79de5f154a0', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 13, 13, 'እኔ ጻድቁን፦ በርግጥ በሕይወት ትኖራለህ ባልሁ ጊዜ፥ እርሱ በጽድቁ ታምኖ ኀጢአት ቢሠራ በሠራው ኀጢአት ይሞታል እንጂ ጽድቁ አይታሰብለትም።'),
  ('9b36539e-17c8-5e8c-a863-ea873997fcbf', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 14, 14, 'እኔም ኀጢአተኛውን፦ በርግጥ ትሞታለህ ባልሁ ጊዜ፥ እርሱ ከኀጢአቱ ተመልሶ ፍርድንና ቅን ነገርን ቢያደርግ፤'),
  ('2a535ca2-5340-5a1c-aaf0-ef4baf810eeb', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 15, 15, 'ኀጢአተኛውም መያዣን ቢመልስ፥ የነጠቀውንም ቢከፍል፥ በሕይወትም ትእዛዝ ቢሄድ፥ ኀጢአትም ባይሠራ፥ በሕይወት ይኖራል እንጂ አይሞትም።'),
  ('c0fd125b-f468-52aa-a17f-a8db844ac682', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 16, 16, 'የሠራውም ኀጢአት ሁሉ አይታሰብበትም፤ ፍርድንና ቅን ነገርን አድርጎአልና፤ በእርግጥ በሕይወት ይኖራል።'),
  ('df53daaa-80d9-5825-af7f-27f7b18785e5', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 17, 17, '“የሕዝብህ ልጆች፦ የእግዚአብሔር መንገድ የቀና አይደለም ይላሉ፤ ነገር ግን የእነርሱ መንገድ የቀና አይደለም።'),
  ('3562cd06-9692-5d45-a6c0-d3d542b28489', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 18, 18, 'ጻድቅ ከጽድቁ ተመልሶ ኀጢአትን ቢሠራ ይሞትበታል።'),
  ('e25043c3-19a3-5d3e-ab8f-41f9744e7f4e', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 19, 19, 'ኀጢአተኛውም ከኀጢአቱ ተመልሶ ፍርድንና ጽድቅን ቢያደርግ በሕይወት ይኖርበታል።'),
  ('b4ae33e7-b568-51f7-a1ac-06e6cdfdd5e7', '8c3d1308-f26a-50ce-a888-10642512d7fb', '6ceb349e-2840-528f-aca5-eba0a4ea4f4b', 20, 20, 'እናንተ ግን፦ የጌታ መንገድ የቀና አይደለም ትላላችሁ፤ የእስራኤል ቤት ሆይ! በእያንዳንዳችሁ ላይ እንደ መንገዳችሁ እፈርድባችኋለሁ።”'),
  ('7e179410-4994-5858-a155-dc4ca56c4750', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 1, 21, 'እንዲህም ሆነ፤ በተማረክን በዐሥራ ሁለተኛው ዓመት በዐሥረኛው ወር ከወሩም በአምስተኛው ቀን ከኢየሩሳሌም ያመለጠ አንድ ሰው ወደ እኔ መጥቶ፦ ከተማዪቱ ተያዘች አለኝ።'),
  ('65b9a8dd-a117-5467-a525-73a419605575', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 2, 22, 'ያመለጠውም ሳይመጣ በመሸ ጊዜ የእግዚአብሔር እጅ በእኔ ላይ ነበረች፤ በነጋውም ወደ እኔ እስኪመጣ ድረስ አፌን ከፈተ፤ አፌም ተከፈተች፤ ከዚያም በኋላ እኔ ዲዳ አልሆንሁም።'),
  ('40ab551f-a0f3-5009-a447-2506de753a05', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 3, 23, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፥'),
  ('cfb081a3-b864-527f-a568-c808f8bff50e', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 4, 24, '“የሰው ልጅ ሆይ! በእስራኤል ምድር በአሉ በባድማ ስፍራዎች የተቀመጡ፦ አብርሃም ብቻውን ሳለ ምድሪቱን ወረሰ፤ እኛም ብዙዎች ነን፤ ምድሪቱም ርስት ሆና ለእኛ ተሰጥታለች ይላሉ። ስለዚህ እንዲህ በላቸው፦'),
  ('acf9abfd-10c3-5ea0-ab69-94e6edc8eca6', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 5, 25, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ከደም ጋር ትበላላችሁ፤ ዐይናችሁንም ወደ ጣዖቶቻችሁ ታነሣላችሁ፤ ደምንም ታፈስሳላችሁ፤ በውኑ ምድሪቱን ትወርሳላችሁን?'),
  ('9ccc77cc-cdb7-5bcd-a7f8-8ef10f765149', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 6, 26, 'ሰይፋችሁን ይዛችሁ ቆማችኋል፤ ርኩስ ነገርን ታደርጋላችሁ፤ የባልንጀሮቻችሁንም ሚስቶች ታስነውራላችሁ፤ በውኑ ምድሪቱን ትወርሳላችሁን? ስለዚህም እንዲህ በላቸው፦'),
  ('952c80ca-4036-5c03-a24b-0ca90c0968d7', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 7, 27, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ እኔ ሕያው ነኝና በባድማ ስፍራዎች ያሉ በሰይፍ ይወድቃሉ፤ በምድረ በዳ ያለውን ለአራዊት መብል አድርጌ እሰጣለሁ፤ በአምባዎችና በዋሻዎች ያሉ በቸነፈር ይሞታሉ።'),
  ('5e61d24f-8d7c-5a9e-a88c-527a8be35d62', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 8, 28, 'ምድሪቱንም ባድማና ውድማ አደርጋታለሁ፤ የኀይልዋም ስድብ ይቀራል፤ የእስራኤልም ተራሮች ባድማ ይሆናሉ፤ ማንም አያልፍባቸውም።'),
  ('82500be2-2e44-5581-ab9c-727cb13cda6a', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 9, 29, 'ስላደረጉትም ርኵሰት ሁሉ ምድሪቱን ባድማና ውድማ ባደረግሁ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('1359a6de-ed36-544e-aad7-8fca90bde00e', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 10, 30, '“አንተም የሰው ልጅ ሆይ! የሕዝብህ ልጆች በቅጥር አጠገብና በቤት ደጆች ውስጥ ስለ አንተ ይናገራሉ፤ እርስ በርሳቸውም አንዱ ከአንዱ ጋር፦ እንሂድና እግዚአብሔር የሚለውን ቃል እንስማ ይላሉ።'),
  ('ab909562-34f6-5eb3-a5c0-4e5f9720aa82', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 11, 31, 'ሕዝብ እንደሚመጣ ወደ አንተ ይመጣሉ፤ እንደ ሕዝቤም በፊትህ ይቀመጣሉ፤ ቃልህንም ይሰማሉ፤ ነገር ግን አያደርጉትም፤ በአፋቸው ሐሰት ነገር አለና፥ ልባቸውም ጣዖታትን ይከተላልና።'),
  ('cf23e645-af13-54cf-a0bb-3701d8a60338', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 12, 32, 'እነሆ አንተ መልካም ድምፅ እንዳለው እንደሚወደድ መዝሙር ማለፊያም አድርጎ በገና እንደሚጫወት ሰው ሁነህላቸዋል፤ ቃልህንም ይሰማሉ ነገር ግን አያደርጉትም።'),
  ('6971b476-cb89-5b2e-a91d-e48f347e655e', '8c3d1308-f26a-50ce-a888-10642512d7fb', '7d2bf032-5bea-5927-a6ee-c6df02cca10c', 13, 33, 'እነርሱም እንዲህ ይላሉ፦ እነሆ ይህ ይመጣል፤ በመጣም ጊዜ እነርሱ ነቢይ በመካከላቸው እንደ ነበረ ያውቃሉ።”'),
  ('525cb7ce-8fb5-5e9c-a613-8201cce6f4d2', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('75af9288-3317-5b86-a1b3-dd849efbd9d0', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 2, 2, '“የሰው ልጅ ሆይ! ትንቢት ተናገር፤ በእስራኤል እረኞች ላይ ትንቢት ተናገር፤ እረኞችንም እንዲህ በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ራሳቸውን ለሚያሰማሩ ለእስራኤል እረኞች ወዮላቸው! እረኞች ራሳቸውን ያሰማራሉን? እረኞች በጎችን ያሰማሩ ዘንድ አይገባቸውምን?'),
  ('34df9afa-bb6a-510e-a8e9-9db9a926fad7', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 3, 3, 'ወተቱን ትጠጣላችሁ፤ ጠጕሩንም ትለብሳላችሁ፤ የወፈሩትን ታርዳላችሁ፤ በጎቹን ግን አታሰማሩም።'),
  ('067c9348-d12b-5b82-a2b6-5d37638d6688', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 4, 4, 'የደከመውን አላጸናችሁትም፤ የታመመውንም አልፈወሳችሁትም፤ የተሰበረውንም አልጠገናችሁትም፤ የባዘነውንም አልመለሳችሁትም፤ የጠፋውንም አልፈለጋችሁትም፤ በኀይልና በጭቈናም ገዛችኋቸው።'),
  ('3b958212-ff81-578f-a003-a62eaab921a7', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 5, 5, 'በጎችም እረኛን በማጣት ተበተኑ፤ ለዱርም አራዊት ሁሉ መብል ሆኑ።'),
  ('9a731a61-338d-50e2-a391-def55e67cbc5', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 6, 6, 'በጎች በተራሮች ሁሉና በረዘሙ ኮረብቶች ሁሉ ላይ ተበትነዋል፤ በጎችም በምድር ፊት ሁሉ ላይ ተበትነዋል፤ የሚፈልግም አልነበረም፤ የሚመልስም አልነበረም።'),
  ('c2ffcb5e-fd79-50f1-a3d4-66ea688ce068', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 7, 7, '“ስለዚህ እረኞች ሆይ! የእግዚአብሔርን ቃል ስሙ፤'),
  ('c1bf7916-6e7f-5c4d-a9b2-e383fdd812a7', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 8, 8, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ እኔ ሕያው ነኝና እረኞች ስለሌሉ፥ እረኞችም በጎችን ስላልፈለጉ፥ እረኞችም ራሳቸውን እንጂ በጎችን ስላላሰማሩ፥ በጎች ንጥቂያ ሆነዋልና፥ በጎችም ለዱር አራዊት ሁሉ መብል ሆነዋልና፤'),
  ('b38d8e3b-a51c-5005-a315-6b22d90472fd', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 9, 9, 'ስለዚህ እረኞች ሆይ! የእግዚአብሔርን ቃል ስሙ።'),
  ('bb406794-8565-5f1f-a211-3c2bc2486f52', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 10, 10, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ በእረኞች ላይ ነኝ፤ በጎችንም ከእጃቸው እፈልጋለሁ፤ በጎችንም ከማሰማራት አስተዋቸዋለሁ፤ ከዚያም ወዲያ እረኞች በጎችን አያሰማሩም፤ በጎችንም ከአፋቸው አድናለሁ፤ መብልም አይሆኑላቸውም።'),
  ('ae09eecb-06da-5cb9-a8f4-f96c8505c979', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 11, 11, '“ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ እኔ ራሴ በጎችን እሻለሁ፤ እጐበኛቸዋለሁም።'),
  ('df79b672-e8a1-5996-a95e-cecaa8ee2d66', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 12, 12, 'በደመናና በጭጋግ ቀን እረኛ ከበጎቹ መካከል የተለየውን እንደሚፈልግ፥ እንደዚሁ በጎችን እፈልጋለሁ፤ በደመናና በጭጋግ ቀን ከተበተኑባቸው ሀገሮች ሁሉ እሰበስባቸዋለሁ።'),
  ('c1bfde82-5345-5feb-a3f4-a5c2dd50eefc', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 13, 13, 'ከአሕዛብም ዘንድ አወጣቸዋለሁ፤ ከሀገሮችም ሁሉ እሰበስባቸዋለሁ፤ ወደ ገዛ ሀገራቸውም አመጣቸዋለሁ፤ በእስራኤልም ተራሮች ላይ፥ በፈሳሾችም አጠገብ፥ በምድርም ላይ ሰዎች በሚኖሩባት ስፍራ ሁሉ አሰማራቸዋለሁ።'),
  ('87d61585-1b0d-5c0d-afa2-7d58f66f6e75', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 14, 14, 'በመልካም ማሰማርያ አስማራቸዋለሁ፤ ጕረኖአቸውም በረዥሞቹ በእስራኤል ተራሮች ላይ ይሆናል፤ በዚያ በመልካም ጕረኖ ውስጥ ይመሰጋሉ፤ በእስራኤልም ተራሮች ላይ በለመለመ ማሰማርያ ይሰማራሉ።'),
  ('eac48cf5-7aec-584b-af86-632c523a55b9', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 15, 15, 'እኔ ራሴ በጎችን አሰማራለሁ፤ አስመስጋቸውማለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ፥ ይላል ጌታ እግዚአብሔር።'),
  ('e1b34eb5-8827-5104-aeb7-e3e49e1c559e', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 16, 16, 'የጠፋውንም እፈልጋለሁ፤ የባዘነውንም እመልሳለሁ፤ የተሰበረውንም እጠግናለሁ፤ የደከመውንም አጸናለሁ፤ የወፈረውንና የበረታውንም እጠብቃለሁ፤ በፍርድም እጠብቃቸዋለሁ።”'),
  ('e87bc424-fcf4-5fc2-ae58-dc8c4dad2fe8', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 17, 17, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “እናንተም መንጋዬ ሆይ! እነሆ በበግና በበግ መካከል፥ በአውራ በግና በአውራ ፍየልም መካከል እፈርዳለሁ።'),
  ('38730b0b-650d-58f6-aa53-92c8cc7a5775', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 18, 18, 'የቀረውን ማሰማርያችሁን በእግራችሁ የረገጣችሁት፥ የተሰማራችሁበት መልካሙ መሰማርያ ባይበቃችሁ ነውን? የቀረውንስ ውኃ በእግራችሁ ያደፈረሳችሁት፥ ጥሩውን ውኃ መጠጣታችሁ ባይበቃችሁ ነውን?'),
  ('ce79c7bd-8a1b-566f-ab71-0a69e6eeefc2', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 19, 19, 'በጎችም በእግራችሁ በረገጣችሁት ይሰማራሉ፤ በእግራችሁም ያደፈረሳችሁትን ይጠጣሉ።'),
  ('ae2859f5-ffbf-57cf-a65a-70f35176bd64', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 20, 20, '“ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላቸዋል፦ እነሆ እኔ በወፈሩት በጎችና በከሱት በጎች መካከል እፈርዳለሁ።'),
  ('e2b73cea-73e0-5d7b-a45c-ede2f1be5990', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 21, 21, 'እስክትበትኑአቸው ድረስ በእንቢያና በትከሻ ስለምትገፉአቸው፥ የደከሙትንም ሁሉ በቀንዳችሁ ስለምትወጉአቸው፥'),
  ('e3bf30b5-fad8-53c1-ad79-4aca34463743', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 22, 22, 'ስለዚህ መንጋዬን አድናለሁ፤ ከእንግዲህ ወዲህም ንጥቂያ አይሆኑም፤ በበግና በበግ መካከልም እፈርዳለሁ።'),
  ('32574274-9f21-574c-a59e-1f815960ec93', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 23, 23, 'በላያቸውም አንድ እረኛ አቆማለሁ፤ እርሱም ያሰማራቸዋል፤ እርሱም ባሪያዬ ዳዊት ነው፤ እረኛም ይሆናቸዋል።'),
  ('aedf0520-af20-574d-a6bd-0cb9873524e7', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 24, 24, 'እኔም እግዚአብሔር አምላክ እሆናቸዋለሁ፤ ባሪያዬ ዳዊትም በመካከላቸው አለቃ ይሆናል፤ እኔ እግዚአብሔር ተናግሬአለሁ።'),
  ('d8070866-abdd-5853-a56f-e8abca8bd329', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 25, 25, '“የሰላምንም ቃል ኪዳን ከዳዊት ቤት ጋር አደርጋለሁ፤ ክፉዎችንም አራዊት ከምድር አጠፋለሁ፤ ተዘልለውም በምድረ በዳ ይኖራሉ፤ በዱርም ውስጥ ይተኛሉ።'),
  ('2f49d054-ed1d-5028-afcc-e6fd1adda72a', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 26, 26, 'እነርሱንና በኮረብታዬ ዙሪያ ያሉትን ስፍራዎች እባርካቸዋለሁ፤ ዝናቡንም በጊዜው አወርዳለሁ፤ የበረከትም ዝናብ ይሆናል።'),
  ('e3aa9e52-045d-57f6-a158-c7e4ec44a421', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 27, 27, 'የምድረ በዳ ዛፍም ፍሬውን ይሰጣል፤ ምድርም ቡቃያዋን ትሰጣለች፤ በምድራቸውም በሰላም ታምነው ይኖራሉ፤ የቀንበራቸውንም ማነቆ በሰበርሁ ጊዜ፥ ከሚገዙአቸውም እጅ ባዳንኋቸው ጊዜ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('31625cdd-85ae-51f2-a6ba-a981b79f0f73', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 28, 28, 'እንግዲህ ለአሕዛብ ንጥቂያ አይሆኑም፤ የምድርም አራዊት አይበሉአቸዋም፤ ተዘልለውም ይቀመጣሉ፤ የሚያስፈራቸውም የለም።'),
  ('fb9f166f-614f-56c9-a772-3bcd0082aa92', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 29, 29, 'የሰላምን ተክል አቆምላቸዋለሁ፤ እንግዲህም ከራብ የተነሣ በምድር አያልቁም፤ የአሕዛብንም ስድብ ከእንግዲህ ወዲህ አይሸከሙም።'),
  ('996bff63-3382-55a6-a668-fc28d08112f6', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 30, 30, 'እኔ እግዚአብሔር አምላካቸው ከእነርሱ ጋር እንዳለሁ፥ እነርሱም የእስራኤል ቤት ሕዝቤ እንደ ሆኑ ያውቃሉ፥ ይላል ጌታ እግዚአብሔር።'),
  ('bb652e20-eaa0-5b71-a202-ec9eb8b14fbe', '8a5422e2-33d0-51af-a712-aa77791c2b72', '99b02b04-d147-546a-abd9-ea050c55cd29', 31, 31, 'እናንተም በጎች፥ የማሰማሪያዬ በጎች፥ ሰዎች ናችሁ፤ እኔም አምላካችሁ ነኝ፥ ይላል ጌታ እግዚአብሔር።”'),
  ('ed39b827-025d-589a-a785-2b4c68d96880', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('e574d4c5-d1b8-5fcb-a974-8ac515a8617d', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 2, 2, '“የሰው ልጅ ሆይ! ፊትህን ወደ ሴይር ተራራ መልስ፤ ትንቢትም ተናገርበት፤'),
  ('61338226-f6ad-5082-a75d-b965d423a992', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 3, 3, 'እንዲህም በለው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ የሴይር ተራራ ሆይ! እነሆ በአንተ ላይ ነኝ፤ እጄን እዘረጋብሃለሁ፤ ባድማና ውድማም አደርግሃለሁ።'),
  ('cfb1c031-ad3b-5fa2-ade5-d6720947277e', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 4, 4, 'ከተሞችህንም አፈራርሳቸዋለሁ፤ አንተም ባድማ ትሆናለህ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃለህ።'),
  ('858f701d-2b52-5510-ad1e-44ba062f261a', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 5, 5, 'የዘለዓለም ጠላት ሁነሃልና፥ በመከራቸውም ጊዜ በኀይለኛይቱ የኀጢአታቸው ቀጠሮ ጊዜ የእስራኤልን ልጆች በሰይፍ እጅ ጥለሃቸዋልና፤'),
  ('fef86e3b-31e4-5cc8-a39e-5e04e9d1a817', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 6, 6, 'ስለዚህ እኔ ሕያው ነኝ! በደም እንደ በደልህ ደም ያሳድድሃል፥ ይላል ጌታ እግዚአብሔር።'),
  ('ffd2c78c-3b70-5d97-aa19-92f3addd9521', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 7, 7, 'የሴይርንም ተራራ ውድማ አደርገዋለሁ፤ ሰውንና እንስሳውንም አጠፋለሁ።'),
  ('7688e815-4632-50b1-af6f-a59452faa6e4', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 8, 8, 'ተራሮችህንም በተገደሉት ሰዎች እሞላለሁ፤ በኮረብቶችህና በሸለቆዎችህ፥ በፈሳሾችህም ሁሉ ላይ በሰይፍ የተገደሉት ሁሉ ይወድቃሉ።'),
  ('c070c6cb-98ff-5403-a853-26c57b6445c8', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 9, 9, 'ለዘለዓለምም ባድማ አደርግሃለሁ፤ ከተሞችህም ሰው የማይኖርባቸው ይሆናሉ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃለህ።'),
  ('9394e3f3-267d-5b64-ad1d-89bd64b4149d', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 10, 10, '“እግዚአብሔርም በዚያ ሳለ፥ አንተ፥ እነዚህ ሁለቱ ሕዝቦች፥ እነዚህም ሁለቱ ሀገሮች ለእኔ ይሆናሉ፤ እኔም እወርሳቸዋለሁ ብለሃልና፤'),
  ('6483f32e-c824-5808-ad0e-7dd132828780', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 11, 11, 'ስለዚህ እኔ ሕያው ነኝ! እንደ ቍጣህ መጠን፥ እነርሱንም ጠልተህ እንዳደረግኸው እንደ ቅንአትህ መጠን እኔ እፈርድብሃለሁ፥ ይላል ጌታ እግዚአብሔር፤ በፈረድሁብህም ጊዜ በእነርሱ ዘንድ የታወቅሁ እሆናለሁ።'),
  ('3fa19cb0-bb84-5639-a26a-692981de74b0', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 12, 12, 'አንተም፦ ፈርሰዋል፤ መብልም ሆነው ለእኛ ተሰጥተዋል ብለህ በእስራኤል ተራሮች ላይ የተናገርኸውን ስድብ ሁሉ እኔ እግዚአብሔር እንደ ሰማሁት ታውቃለህ።'),
  ('7a4ea640-1546-5227-a90f-37fe9ca64b3b', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 13, 13, 'አንተ አፍህን በእኔ ላይ ከፍ ከፍ እንደ አደረግህ እኔ ሰምቼአለሁ።”'),
  ('9fbaaed9-2b87-53bc-af59-d8b92b24e40c', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 14, 14, 'ጌታ እግዚአብሔርም እንዲህ ይላል፥ “ምድር ሁሉ ደስ ሲላት አንተን ባድማ አደርግሃለሁ።'),
  ('6f8881c7-35a7-516a-aed6-f60f0ee89f10', 'a0126a95-ad2c-5193-a548-573fbf1fe76e', 'd2d9d51f-a1c4-550c-a455-c7c5247165a9', 15, 15, 'የእስራኤል ቤት ርስት ባድማ ስለ ሆነ በላዩ ደስ እንዳለህ፥ እንዲሁ አደርግብሃለሁ፤ የሴይር ተራራ ሆይ! አንተና መላው ኤዶምያስ ባድማ ትሆናላችሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃለህ።”'),
  ('3429c273-f8c6-5927-abbd-5d91d929b518', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 1, 1, '“አንተም የሰው ልጅ ሆይ! ለእስራኤል ተራሮች ትንቢት ተናገር፦ የእስራኤል ተራሮች ሆይ! የእግዚአብሔርን ቃል ስሙ በላቸው።'),
  ('23877f18-048f-5979-ae13-9b46d42a1afd', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 2, 2, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ጠላት በእናንተ ላይ፦ እሰይ! ለዘለዓለም ጥፋት፥ ለእኛ ርስት ሆነዋል ብሎአልና፤'),
  ('66f4b7b0-b46c-596f-ae21-44e41865e4e4', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 3, 3, 'ስለዚህ ትንቢት ተናገር፤ እንዲህም በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ለቀሩት አሕዛብ ርስት ትሆኑ ዘንድ በዙሪያችሁ ያሉ አሕዛብ አዋርደዋችኋልና፤ ውጠዋችሁማልና፥ እናንተም የተናጋሪዎች ከንፈር መተረቻና የአሕዛብ ማላገጫ ሆናችኋልና፤'),
  ('94198817-4168-5cc6-a52d-89c327bf5ef0', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 4, 4, 'ስለዚህ፥ እናንተ የእስራኤል ተራሮች ሆይ! የጌታ የእግዚአብሔርን ቃል ስሙ። ጌታ እግዚአብሔር ለተራሮችና ለኮረብቶች፥ ለፈሳሾችና ለሸለቆዎች፥ ለምድረ በዳዎች፥ ባዶ ለሆኑትና ለፈረሱት፥ በዙሪያ ላሉት ለቀሩት አሕዛብ ምርኮና መሣለቂያ ለሆኑት ከተሞች እንዲህ ይላል፦'),
  ('522b491c-f1b0-5b47-a09f-e6e9226e9fce', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 5, 5, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ ያሳድዱአትና ይበዘብዙአት ዘንድ በልባቸው ሁሉ ደስታና በነፍሳቸው ንቀት ምድሬን ርስት አድርገው ለራሳቸው በሰጡ በቀሩት አሕዛብና በኤዶምያስ ሁሉ ላይ በቅንአቴ እሳት ተናግሬአለሁ፤'),
  ('8979196f-3428-5dee-a2e0-5a93b160f576', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 6, 6, 'ስለዚህ ስለ እስራኤል ምድር ትንቢት ተናገር፤ ለተራሮችና ለኮረብቶችም፥ ለፈሳሾችና ለሸለቆዎችም እንዲህ በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ የአሕዛብን ስድብ ስለ ተሸከማችሁ በቅንአቴና በመዓቴ ተናግሬአለሁ።'),
  ('e586eed2-8cd7-592c-ab2d-417ff02f8600', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 7, 7, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ በዙሪያችሁ በአሉ አሕዛብ ላይ እኔ እጄን አነሣለሁ፤ እነርሱም ኀፍረታቸውን ይሸከማሉ።'),
  ('7329d00c-9321-57c3-a81d-c6ef02aa3c3e', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 8, 8, '“የእስራኤል ተራሮች ሆይ! ሕዝቤ ይመጡ ዘንድ ተስፋ ያደርጋሉና ወይናችሁንና ፍሬያችሁን ይበላሉ።'),
  ('043fe09a-8983-5420-aeb1-3763221fa9ba', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 9, 9, 'እነሆ እኔ ለእናንተ ነኝና፤ ወደ እናንተም እመለከታለሁ፤ እናንተም ትታረሳላችሁ፤ ትዘራላችሁም፤'),
  ('d98303f8-01c2-5486-ad81-a1fb584a2c90', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 10, 10, 'እኔም የእስራኤልን ቤት ሰዎች ሁሉ ሁሉንም አበዛባችኋለሁ፤ በከተሞችም ሰዎች ይኖሩባቸዋል፤ ባድማዎቹም ስፍራዎች ይሠራሉ።'),
  ('3f5fb8a0-c0f3-5cd1-a095-fb592c81985a', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 11, 11, 'ሰውንና እንስሳውንም አበዛላችኋለሁ፤ እነርሱም ይበዛሉ፤ ያፈሩማል፤ እንደ ጥንታችሁም ሰዎችን አኖርባችኋለሁ፤ ቀድሞም እንደ አደረግሁላችሁ መልካም አደርግላችኋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('2cd0e4dc-4118-5f65-a96e-820650db33d1', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 12, 12, 'ሰዎችንም፥ ሕዝቤን እስራኤልን በእናንተ ላይ አበዛለሁ፤ እነርሱም ይወርሱአችኋል፤ ርስትም ትሆኑአቸዋላችሁ፤ ከእንግዲህም ወዲያ ልጅ አልባ አታደርጓቸውም።'),
  ('29007f79-7677-5e91-a0b9-1599ead79070', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 13, 13, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ እነርሱ፦ ሰው በላተኛ ነሽ፤ በሕዝብሽም መካከል ልጆችሽን አጥፍተሻል ብለዋችኋልና፤'),
  ('64db3348-5cc8-5dce-a250-d195b6610175', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 14, 14, 'ስለዚህ ዳግመኛ ሰው በላተኛ አትሆኝም፤ ዳግመኛም ሕዝብሽን ልጅ አልባ አታደርጊም፥ ይላል ጌታ እግዚአብሔር።'),
  ('7f39c30e-5767-597b-a194-12e6cad955df', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '837476f3-c358-5323-abc5-96f1d395941e', 15, 15, 'ዳግመኛም የአሕዛብን ስድብ አላሰማብሽም፤ ዳግመኛም የአሕዛብን ውርደት አትሸከሚም፤ ዳግመኛም ሕዝብሽን አታሰናክዪም፥” ይላል ጌታ እግዚአብሔር።”'),
  ('34a10f5d-883b-5a4d-a13f-592118b488c7', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 1, 16, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('521439fc-a2ff-58d9-a586-70f786092922', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 2, 17, '“የሰው ልጅ ሆይ! የእስራኤል ቤት በምድራቸው በተቀመጡ ጊዜ በመንገዳቸውና በጣዖታቸው አረከሱአት፤ መንገዳቸውም በፊቴ እንደ አደፍ ርኵሰት ነበረ።'),
  ('ca1ea75c-bb69-5cca-a2ac-2f497f8cb7a7', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 3, 18, 'በምድር ላይ ስለ አፈሰሱት ደም፥ በጣዖቶቻቸውም ስለ አረከሱአት መዓቴን አፈሰስሁባቸው፤'),
  ('60faedfa-a7c3-5631-adb9-ad8eed32c300', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 4, 19, 'ወደ አሕዛብም በተንኋቸው፤ ወደ ሀገሮችም ዘራኋቸው፤ እንደ መንገዳቸውና እንደ በደላቸውም መጠን ፈረድሁባቸው።'),
  ('0ff3995f-38c9-5b59-a15a-2e0075b469bd', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 5, 20, 'ወደ ገቡባቸውም ወደ አሕዛብ በመጡ ጊዜ፥ ሰዎች እነርሱን፦ ከምድራቸው የወጡ የእግዚአብሔር ሕዝብ እነዚህ ናቸው ሲሉአቸው ቅዱስ ስሜን አረከሱ።'),
  ('3074fb28-59ff-54fa-ad3d-fd87f819fc0c', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 6, 21, 'እኔ ግን የእስራኤል ቤት በመጡባቸው በአሕዛብ መካከል ስለ አረከሱት ስለ ቅዱስ ስሜ ስል ራራሁላቸው።'),
  ('7223f07b-69aa-5100-ab8a-b8de3aec9cee', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 7, 22, '“ስለዚህ ለእስራኤል ቤት እንዲህ በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ የእስራኤል ቤት ሆይ! በገባችሁባቸው በአሕዛብ መካከል ስላረከሳችሁት ስለ ቅዱስ ስሜ ነው እንጂ ስለ እናንተ የምሠራ አይደለሁም።'),
  ('7b11ff81-5d22-56a5-ad4d-1b8d65fd08bc', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 8, 23, 'በአሕዛብም ዘንድ የረከሰውን፥ በመካከላቸው ያረከሳችሁትን ገናና ስሜን እቀድሰዋለሁ፤ በዐይናቸውም ዘንድ በተቀደስሁባችሁ ጊዜ እኔ እግዚአብሔር እንደ ሆንሁ አሕዛብ ያውቃሉ፥ ይላል ጌታ እግዚአብሔር።'),
  ('96ab1da8-4ffe-5a42-a821-8fca09bfd388', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 9, 24, 'ከአሕዛብም መካከል አወጣችኋለሁ፤ ከየሀገሩም ሁሉ እሰበስባችኋለሁ፤ ወደ ገዛ ምድራችሁም እመልሳችኋለሁ።'),
  ('9e14aefb-5bc9-561e-a938-4d0db8f705e2', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 10, 25, 'ጥሩ ውኃንም እረጭባችኋለሁ፤ እናንተም ከርኵሰታችሁ ሁሉ ትነጻላችሁ፤ ከጣዖቶቻችሁም ሁሉ አነጻችኋለሁ።'),
  ('4c2bc5a9-b2ef-5940-a3db-0bb617c308c2', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 11, 26, 'አዲስ ልብንም እሰጣችኋለሁ፤ አዲስ መንፈስንም በውስጣችሁ አኖራለሁ፤ የድንጋዩንም ልብ ከሥጋችሁ አወጣለሁ፤ የሥጋንም ልብ እሰጣችኋለሁ።'),
  ('432268d0-514c-5697-af1b-39da784ad6c9', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 12, 27, 'መንፈሴንም በውስጣችሁ አኖራለሁ፤ በትእዛዜም እንድትሄዱ አደርጋችኋለሁ፤ ፍርዴንም ትጠብቃላችሁ ታደርጉትማላችሁ።'),
  ('32856d53-b77d-57d0-a781-77cf1cffda83', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 13, 28, 'ለአባቶቻችሁም በሰጠኋት ምድር ትኖራላችሁ፤ ሕዝብም ትሆኑኛላችሁ፤ እኔም አምላክ እሆናችኋለሁ።'),
  ('05dcae4d-95a1-52f1-a855-9690e2371121', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 14, 29, 'ከርኵሰታችሁም ሁሉ አድናችኋለሁ፤ እህልንም እጠራዋለሁ፤ አበዛውማለሁ፤ ራብንም አላመጣባችሁም።'),
  ('9b182a2a-e133-55d1-a06e-ef2ad66241cb', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 15, 30, 'ደግሞም የራብን ስድብ ከአሕዛብ ዘንድ እንዳትሸከሙ የዛፍን ፍሬና የእርሻውን መከር አበዛለሁ።'),
  ('3e1be456-726c-54cd-a5eb-0cd4c890ed7e', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 16, 31, 'ክፉውን መንገዳችሁንና መልካም ያይደለውን ሥራችሁንም ታስባላችሁ፤ ስለ በደላችሁና ስለ ርኵሰታችሁም ራሳችሁን ትጸየፋላችሁ።'),
  ('02825ba1-3fc5-5e74-ad9f-515393421ba4', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 17, 32, 'ይህን የሠራሁ ስለ እናንተ እንዳይደለ በእናንተ ዘንድ የታወቀ ይሁን፥ ይላል ጌታ እግዚአብሔር፤ የእስራኤል ቤት ሆይ! ስለ መንገዳችሁ እፈሩና ተዋረዱ።'),
  ('6a9904d1-b0b6-56c7-a54a-3d2c70d14909', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 18, 33, '“ጌታ እግዚአብሔር እንዲህ ይላል፦ ከኀጢአታችሁ ሁሉ በአነጻኋችሁ ጊዜ በከተሞች ሰዎችን አኖራለሁ፤ ባድማዎቹም ስፍራዎች ይሠራሉ።'),
  ('2f98629b-2e8e-5790-ad94-907914712e0b', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 19, 34, 'ባድማ የነበረች፥ በመንገደኛም ሁሉ ዐይን ዘንድ ባድማ የነበረች ምድር ትታረሳለች።'),
  ('a8a8f35e-4151-5d56-a4e5-bf3d9fef2845', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 20, 35, 'ሰዎችም ባድማ የነበረች ይህች ምድር እንደ ዔድን ገነት ሆናለች፤ የፈረሱት፥ ባድማ የሆኑት፥ የጠፉትም ከተሞች ተመሽገዋል፤ ሰውም የሚኖርባቸው ሆነዋል ይላሉ።'),
  ('29b527c4-d49a-55a7-aded-b5620fcc7eaa', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 21, 36, 'በዙሪያችሁም የቀሩት አሕዛብ፥ እኔ እግዚአብሔር የፈረሱትን ስፍራዎች እንደ ሠራሁ፥ ውድማ የሆነውንም እንደ ተከልሁ ያውቃሉ፤ እኔ እግዚአብሔር ተናግሬአለሁ፥ እኔም አደርገዋለሁ።'),
  ('98896847-6dca-5aa1-a43f-416c97f6b239', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 22, 37, '“ጌታ እግዚአብሔር እንዲህ ይላል፦ ስለዚህ ደግሞ አደርግላቸው ዘንድ የእስራኤል ቤት ይሹኛል፤ ሰውንም እንደ መንጋ አበዛላቸዋለሁ።'),
  ('78820df8-a6cf-5a9e-a307-435ab6016915', 'd531aeb0-c2b7-5676-ab7b-aa455d6eccd8', '1d1587ff-efe7-5b59-a4e8-b10891ce9761', 23, 38, 'እንደ ተቀደሱ በጎች፥ በበዓላቶችዋ ቀን እንደሚሆኑ እንደ ኢየሩሳሌም በጎች እንዲሁ የፈረሱት ከተሞች በሰዎች መንጋ ይሞላሉ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('32f66b54-7ca8-5f99-aaf3-151dde8a16a0', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 1, 1, 'የእግዚአብሔርም እጅ በላዬ ነበረ፤ እግዚአብሔርም በመንፈሱ አወጣኝ፤ አጥንቶችም በሞሉበት ሸለቆ መካከል አኖረኝ።'),
  ('ea2a46e2-3d50-5a0e-a870-d73e2ed08525', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 2, 2, 'በእነርሱም አንጻር በዙሪያቸው አዞረኝ፤ እነሆም በሜዳው እጅግ ነበሩ፤ እነሆም እጅግ ደርቀው ነበር።'),
  ('e89be0f4-daf7-5234-a4de-639a09711858', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 3, 3, 'እርሱም፥ “የሰው ልጅ ሆይ! እነዚህ አጥንቶች በሕይወት ይኖራሉን?” አለኝ። እኔም፥ “ጌታ እግዚአብሔር ሆይ! አንተ ታውቃለህ” አልሁ።'),
  ('0a59e6c6-92b0-5dff-a082-3caaf95f27b2', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 4, 4, 'እርሱም እንዲህ አለኝ፥ “በእነዚህ አጥንቶች ላይ ትንቢት ተናገር፤ እንዲህም በላቸው፦ እናንተ የደረቃችሁ አጥንቶች ሆይ! የእግዚአብሔርን ቃል ስሙ።'),
  ('5d260da5-a7f1-51b8-af6a-88a25629f511', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 5, 5, 'ጌታ እግዚአብሔር ለእነዚህ አጥንቶች እንዲህ ይላል፦ እነሆ በእናንተ ላይ የሕይወትን መንፈስ አመጣለሁ።'),
  ('eacad1a5-2a5d-54d0-a129-ce29300166df', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 6, 6, 'ጅማትንም እሰጣችኋለሁ፤ ሥጋንም አወጣባችኋለሁ፤ በእናንተም ላይ ቍርበትን እዘረጋለሁ፤ ትንፋሽንም አገባባችኋለሁ፤ በሕይወትም ትኖራላችሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።”'),
  ('99813ad9-4e17-5e58-a6a6-c886389f4285', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 7, 7, 'እንዳዘዘኝም ትንቢት ተናገርሁ፤ ስናገርም ድምፅ ሆነ፤ እነሆም መናወጥ ሆነ፤ አጥንቶችንም እየራሱ በሆነ በሰውነቱ ከአጥንቶች ጋር አንድ አደረጋቸው።'),
  ('119bbe59-0d80-5051-acab-ed940167d493', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 8, 8, 'እኔም አየሁ፤ እነሆም ጅማት ነበረባቸው፤ ሥጋም ወጣ፤ ቍርበትም በላያቸው ተዘረጋ፤ ትንፋሽ ግን አልነበረባቸውም።'),
  ('6a3acfcb-4cbf-58cc-af31-8441852d89a6', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 9, 9, 'እርሱም፥ “የሰው ልጅ ሆይ! ትንቢት ተናገር፤ ለነፋስ ትንቢት ተናገር፤ ለነፋስም፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ነፋስ ሆይ! ከአራቱ ነፋሳት ዘንድ ና፤ እነዚህ ሙታን በሕይወት ይኖሩ ዘንድ እፍ በልባቸው በል” አለኝ።'),
  ('bfe7d095-1066-5544-a31b-c40d4f8b5f3c', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 10, 10, 'እንዳዘዘኝም ትንቢት ተናገርሁ፤ ትንፋሽም ገባባቸው፤ ሕያዋንም ሆኑ፤ እጅግም ታላቅ ሠራዊት ሆነው በእግራቸው ቆሙ።'),
  ('2e1756e0-a6a9-5115-a05b-1bee50b7568f', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 11, 11, 'እግዚአብሔርም ተናገረኝ፤ እንዲህም አለኝ፥ “የሰው ልጅ ሆይ! እነዚህ አጥንቶች የእስራኤል ቤት ሁሉ ናቸው፤ እነሆ! አጥንቶቻችን ደርቀዋል፤ ተስፋችንም ጠፍቶአል፤ ፈጽመንም ተቈርጠናል ብለዋል።'),
  ('4deb6d99-c6a3-538f-a984-86323aa964e6', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 12, 12, 'ስለዚህ ትንቢት ተናገር፤ እንዲህም በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ሕዝቤ ሆይ! እነሆ መቃብራችሁን እከፍታለሁ፤ ከመቃብራችሁም አወጣችኋለሁ፤ ወደ እስራኤልም ምድር አገባችኋለሁ።'),
  ('df7cb15a-080b-5602-a3e4-8379e6736173', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 13, 13, 'ሕዝቤ ሆይ! መቃብራችሁን በከፈትሁ ጊዜ፥ ከመቃብራችሁም በአወጣኋችሁ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('e76f39bb-fb1b-5bd4-a9cb-d573f4f405d8', '93fffd58-2b17-514c-a61a-e04967e7d115', '8c1bb479-386e-5280-a37b-2a0f07cd3a85', 14, 14, 'መንፈሴንም በውስጣችሁ አሳድራለሁ፤ እናንተም በሕይወት ትኖራላችሁ፤ በገዛ ምድራችሁም አኖራችኋለሁ፤ እኔም እግዚአብሔር እንደ ተናገርሁ፥ እንዳደረግሁም ታውቃላችሁ፥ ይላል ጌታ እግዚአብሔር።”'),
  ('d14b4858-6b4a-5d83-abfc-8ae1c2c716f6', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 1, 15, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('9ad2ca63-2303-5732-a64f-eaa38bdeaf32', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 2, 16, '“አንተ የሰው ልጅ ሆይ! አንድ በትር ውሰድና፦ ይሁዳንና ባልንጀሮቹን፥ የእስራኤልንም ልጆች በላዩ ጻፍ፤ ሌላም በትር ውሰድና፦ የኤፍሬም በትር ለዮሴፍና ለባልንጀሮቹ ለእስራኤል ቤት ሁሉ ብለህ በላዩ ጻፍ።'),
  ('073c7e47-51c6-5a07-a7af-1fe898539619', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 3, 17, 'አንድ በትርም እንዲሆኑ አንዱን ከሁለተኛው ጋር ለአንተ አጋጥም፤ በእጅህም ውስጥ አንድ ይሁኑ።'),
  ('ab64f164-9903-5f80-aa91-56f1d6d10583', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 4, 18, 'የሕዝብህም ልጆች፦ ይህ የምታደርገው ነገር ምን ማለት እንደ ሆነ አትነግረንምን? ብለው በተናገሩህ ጊዜ፥ አንተ፦ ጌታ እግዚአብሔር እንዲህ ይላል፦'),
  ('907edb28-503e-50d1-afa6-77609e202ad6', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 5, 19, 'እነሆ በኤፍሬም እጅ ያለውን የዮሴፍን በትር ባልንጀሮቹንም የእስራኤልን ነገዶች እወስዳለሁ፤ ከእርሱም ከይሁዳ በትር ጋር አጋጥማቸዋለሁ፤ አንድ በትርም አደርጋቸዋለሁ፤ በእጄም ውስጥ አንድ ይሆናሉ በላቸው።'),
  ('96edc031-cedb-5abf-a781-0487be223e40', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 6, 20, 'የምትጽፍባቸውም በትሮች በፊታቸው በእጅህ ውስጥ ይሆናሉ።'),
  ('f74f077b-0a97-552b-a513-e5b3d644f243', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 7, 21, 'አንተም እንዲህ ትላቸዋለህ፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ የእስራኤልን ልጆች ከገቡባቸው ከአሕዛብ መካከል እወስዳለሁ፤ ከስፍራም ሁሉ እሰበስባቸዋለሁ፤ ወደ እስራኤልም ምድር አመጣቸዋለሁ፤'),
  ('733162db-ea3f-55d0-af57-b8976e713124', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 8, 22, 'በምድርም ላይ በእስራኤል ተራሮች ላይ አንድ ሕዝብ አደርጋቸዋለሁ፥ አንድ ንጉሥም በሁላቸው ላይ ይነግሣል፤ ከዚያ ወዲያ ሁለት ሕዝብ አይሆኑም፤ ከዚያ ወዲያም ሁለት መንግሥት ሆነው አይለያዩም።'),
  ('265787d8-3be0-5cc5-aadd-9a159720f7f2', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 9, 23, 'ከዚያ ወዲያም በጣዖቶቻቸውና በርኵሰታቸው፥ በመተላለፋቸውም ሁሉ አይረክሱም፤ ኀጢአትም ከሠሩባት ዐመፅ ሁሉ አድናቸዋለሁ፤ አነጻቸውማለሁ፤ ሕዝብም ይሆኑኛል፤ እኔም አምላክ እሆናቸዋለሁ።'),
  ('fac391a0-dc8e-5733-a37c-98e7038e0ec7', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 10, 24, '“ባሪያዬም ዳዊት በላያቸው ንጉሥ ይሆናል፤ ለሁሉም አንድ እረኛ ይሆንላቸዋል፤ በፍርዴም ይሄዳሉ ትእዛዜንም ይጠብቃሉ፤ ያደርጓትማል።'),
  ('6602e258-63e5-5a09-af02-209689e5b64c', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 11, 25, 'አባቶቻችሁም በኖሩባት፤ ለባሪያዬ ለያዕቆብ በሰጠኋት ምድር ይኖራሉ፤ እነርሱና ልጆቻቸው፥ የልጅ ልጆቻቸውም ለዘለዓለም ይኖሩባታል፤ ባሪያዬም ዳዊት ለዘለዓለም አለቃ ይሆናቸዋል።'),
  ('6e9a9015-88a3-5fa0-a029-d82823e67885', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 12, 26, 'የሰላምም ቃል ኪዳን ከእነርሱ ጋር አደርጋለሁ፤ የዘለዓለምም ቃል ኪዳን ይሆንላቸዋል፤ እኔም እባርካቸዋለሁ፤ አበዛቸውማለሁ፤ መቅደሴንም ለዘለዓለም በመካከላቸው አኖራለሁ።'),
  ('ddb447e3-539f-548a-a5c5-b2c268f3f9f9', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 13, 27, 'ማደሪያዬም በላያቸው ላይ ይሆናል፤ እኔም አምላክ እሆናቸዋለሁ፤ እነርሱም ሕዝብ ይሆኑኛል።'),
  ('e11e49ec-fc5a-58f1-a526-388bce5ea4e3', '93fffd58-2b17-514c-a61a-e04967e7d115', '1139e91b-43f1-5222-ad88-d3c5c0611807', 14, 28, 'መቅደሴም ለዘለዓለም በመካከላቸው በሆነ ጊዜ፥ እኔ እስራኤልን የምቀድሰው እግዚአብሔር እንደ ሆንሁ አሕዛብ ያውቃሉ።”'),
  ('c39c9be9-27c3-5dc3-a323-e046ffe4c9bc', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('47dbe821-ec5d-51d5-a01e-fdc68c908d0e', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 2, 2, '“የሰው ልጅ ሆይ! ፊትህን በጎግ ላይና በማጎግ ምድር ላይ፥ በሮስ በሞሳሕና በቶቤል አለቃ ላይ አቅናበት፤ ትንቢትም ተናገርበት፤'),
  ('d3cda619-9904-5cfb-a7be-64555a8a0a9b', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 3, 3, 'እንዲህም በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ የሮስ፥ የሞሣሕና የቶቤል አለቃ ጎግ ሆይ! እነሆ! እኔ በአንተ ላይ ነኝ።'),
  ('632fce8b-109c-58cd-a66f-72f422ab10f1', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 4, 4, 'እመልስህማለሁ፤ በመንጋጋህም ልጓም አገባብሃለሁ፤ አንተንና ሠራዊትህን ሁሉ፥ ፈረሶችንና ፈረሰኞችን፥ የጦር ልብስ የለበሱትን ሁሉ፥ ጋሻና ራስ ቍርን፥ ሰይፍንም የያዙትን ሁሉ አወጣለሁ።'),
  ('6f202d0f-5bf3-57ef-aa3a-f666475b7ad6', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 5, 5, 'ፋርስንና ኢትዮጵያን፥ ሊብያንም፥ ከእነርሱ ጋር ጋሻና የራስ ቍርን የለበሱትን ሁሉ፥'),
  ('354bcff6-62f3-5089-a714-9a50271b2d3f', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 6, 6, 'ጎሜርንና ከእርሱ ጋር ያሉትን ሁሉ፥ በሰሜን ዳርቻም ያለውን የቴርጋማን ቤትና ጭፍሮቹን ሁሉ፥ ብዙዎችንም ሕዝቦች ከአንተ ጋር አወጣለሁ።'),
  ('79d93fd1-abb5-500a-a534-459a2c316c95', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 7, 7, '“አንተና ወደ አንተ የተሰበሰቡ ወገኖችህ ሁሉ ተዘጋጁ፤ አንተም ራስህን አዘጋጅተህ ጠባቂ ሁናቸው።'),
  ('88c1aeb4-adcb-5ea5-a492-b2886161a77a', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 8, 8, 'ከብዙ ዘመንም በኋላ ትፈለጋለህ፤ በኋለኛውም ዘመን፥ የዘለዓለም ባድማ በነበሩ በእስራኤል ተራሮች ላይ ከብዙ ሕዝብ ውስጥ ወደ ተሰበሰበች፥ ከሰይፍ ወደ ተመለሰች ምድር ትገባለህ፤ እርስዋም ከሕዝብ ውስጥ ወጥታለች፤ ሁሉም በሰላም ይቀመጡበታል።'),
  ('762c7c4e-82fa-5da9-ae75-49a8d8724ee5', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 9, 9, 'እንደ ዝናም ትወጣለህ፤ እንደ ደመናም ምድርን ትሸፍን ዘንድ ትደርሳለህ፤ አንተም ከብዙ ሕዝብና ሠራዊት ጋር ትወድቃለህ።”'),
  ('64bd1971-980d-5d46-a28f-1776d06d6be1', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 10, 10, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “በዚያ ቀን ነገር ወደ ልብህ ይገባል፥ ክፉ አሳብንም ታስባለህ፤ እንዲህም ትላለህ፦'),
  ('3bb75fa0-5bd6-5d48-aee0-edd88ae9e95b', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 11, 11, 'ወደ ጠፋች ሀገር እወጣለሁ፤ ተዘልለው በሰላም ወደሚኖሩ፥ ሁላቸው ሳይፈሩ ያለ ቅጥርና ያለ መወርወሪያ፥ ያለ መዝጊያም ወደሚቀመጡባት ምድር እገባለሁ፤'),
  ('b7ae820f-3beb-5dc0-aade-30f9411baa92', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 12, 12, 'ምርኮን ትማርክ ዘንድ፥ ብዝበዛንም ትበዘብዝ ዘንድ፥ ባድማም በነበሩ፥ አሁንም ሰዎች በሚኖሩባቸው ስፍራዎች ላይ፥ ከአሕዛብም በተሰበሰበ፥ ከብትና ዕቃንም በአገኘ፥ በምድርም መካከል በተቀመጠ ሕዝብ ላይ እጅህን ትመልሳለህ።'),
  ('1971616f-c71e-510d-ac7c-81f7a774aa37', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 13, 13, 'ሳባና ድዳን፥ የተርሴስም ነጋዴዎች፥ መንደሮችዋም ሁሉ፦ ምርኮን ትማርክ ዘንድ መጥተሃልን? ብዝበዛንስ ትበዘብዝ ዘንድ፥ ብርንና ወርቅንስ ትወስድ ዘንድ፥ ከብትንና ዕቃንስ ትወስድ ዘንድ፥ እጅግስ ብዙ ምርኮ ትማርክ ዘንድ ወገንህን ሰብስበሃልን? ይሉሃል።”'),
  ('0a208810-d8a2-57e8-a7fe-5788bbce3234', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 14, 14, 'አንተ የሰው ልጅ ሆይ! ስለዚህ ትንቢት ተናገር፤ ጎግንም እንዲህ በለው፥ “ጌታ እግዚአብሔር እንዲህ ይላል፦ በዚያ ቀን ሕዝቤ እስራኤል በሰላም በተቀመጠ ጊዜ አንተ የምትነሣ አይደለምን?'),
  ('01adb62d-1b2c-5315-a371-c93e4a441245', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 15, 15, 'አንተም፥ ከአንተም ጋር ብዙ ሕዝብ ሁላቸው በፈረሶች ላይ የተቀመጡ፥ ታላቅ ወገንና ብርቱ ሠራዊት፥ ከሰሜን ዳርቻ ከስፍራችሁ ትመጣላችሁ።'),
  ('1bb59c8d-74bf-56fc-a660-13dffd8dddf1', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 16, 16, 'ምድርንም ትሸፍን ዘንድ እንደ ደመና በሕዝቤ በእስራኤል ላይ ትወጣለህ። በኋለኛው ዘመን ይሆናል፤ ጎግ ሆይ! በፊታቸው በተቀደስሁብህ ጊዜ፥ አሕዛብ ያውቁኝ ዘንድ በምድሬ ላይ አወጣሃለሁ።'),
  ('6f5c35c2-4e56-596d-a3d2-ebbef92ad8a5', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 17, 17, '“ጌታ እግዚአብሔር ለጎግ እንዲህ ይላል፦ በእነርሱ ላይ እንደማመጣህ፥ በዚያች ዘመን ብዙ ዓመት ትንቢት በተናገሩ በባሪያዎች በእስራኤል ነቢያት እጅ በቀደመው ዘመን ስለ እርሱ የተናገርሁ አንተ ነህን?'),
  ('93b6ecbc-c0e9-5b59-a795-6fd62f991c09', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 18, 18, 'በዚያም ቀን ጎግ በእስራኤል ምድር ላይ በመጣ ጊዜ መቅሠፍቴ በመዓቴ ይመጣል ይላል ጌታ እግዚአብሔር።'),
  ('3a78a0fd-6b35-50b8-a32b-dc27ec424594', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 19, 19, 'በቅንአቴና በመዓቴ እሳት ተናግሬአለሁ፦ በእርግጥ በዚያ ቀን በእስራኤል ምድር ጽኑ መናወጥ ይሆናል፤'),
  ('e9f2e223-1853-5ac7-a390-3052c4eb6e8f', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 20, 20, 'ከእግዚአብሔርም ፊት የተነሣ የባሕር ዓሣዎችና የሰማይ ወፎች፥ የምድረ በዳም አራዊት፥ በምድርም ላይ የሚንቀሳቀሱ ተንቀሳቃሾች ሁሉ፥ በምድርም ላይ የሚኖሩ ሰዎች ሁሉ ይንቀጠቀጣሉ፤ ተራሮችም ይገለባበጣሉ፤ ገዳላገደሎችም ይወድቃሉ፤ ቅጥርም ሁሉ ወደ ምድር ይወድቃል።'),
  ('7c8be624-14c1-5de9-a844-2491da717f95', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 21, 21, 'በተራሮችም ሁሉ በእርሱ ላይ ፍርሀትን እጠራለሁ፤ የሰውም ሁሉ ሰይፍ በወንድሙ ላይ ይሆናል፥ ይላል ጌታ እግዚአብሔር።'),
  ('f205b440-40ff-5e36-a613-a29ad5a3a8c6', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 22, 22, 'በቸነፈርና በደም እፈርድበታለሁ፤ ዶፍም፥ የበረዶም ድንጋይ፥ እሳትና ድኝም በእርሱና በጭፍሮቹ፥ ከእርሱም ጋር በአሉ በብዙ ሕዝብ ላይ አዘንባለሁ።'),
  ('84031d93-5148-5942-ae67-ddb4c11cc952', '4c64b2af-cef6-573f-afba-0bf9c81cbca5', '86c31d57-2378-5957-ac1c-1c1b9f97c4e1', 23, 23, 'ታላቅ እሆናለሁ፤ እቀደስማለሁ፤ እመሰገናለሁም፤ በብዙ አሕዛብም ዐይን የታወቅሁ እሆናለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('dd006fdb-3005-5a5e-acb0-2bdfb8facaa2', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 1, 1, '“አንተም የሰው ልጅ ሆይ! በጎግ ላይ ትንቢትን ተናገር እንዲህም በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ የሮስ የሞሣሕና የቶቤል አለቃ ጎግ ሆይ! እነሆ እኔ በአንተ ላይ ነኝ፤'),
  ('47e88dd3-d56b-5158-a23f-1bfa03a5a97b', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 2, 2, 'እሰበስብሃለሁ፤ እመራሃለሁ፤ ከሰሜንም ዳርቻ አወጣሃለሁ፥ ወደ እስራኤልም ተራሮች እወስድሃለሁ።'),
  ('dc179478-c9dc-560f-ab35-1bcdb2aa6280', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 3, 3, 'ከግራ እጅህም ቀስትህን አስጥልሃለሁ፤ ከቀኝ እጅህም ፍላጾችህን አስረግፍሃለሁ፤ በእስራኤልም ተራሮች ላይ እጥልሃለሁ።'),
  ('01ef681e-6be6-5140-a333-521886a27d37', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 4, 4, 'አንተና ጭፍሮችህ ሁሉ፥ ከአንተም ጋር ያሉ ሕዝብ በምድረ በዳ ፊት ትወድቃላችሁ፤ ለሚናጠቁ ወፎች ሁሉና ለምድር አራዊትም መብል አድርጌ እሰጥሃለሁ።'),
  ('7b6a131c-acb7-51ff-ae34-d16efd5d8617', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 5, 5, 'አንተ በሜዳ ፊት ላይ ትወድቃለህ፤ እኔ ተናግሬአለሁና፥ ይላል ጌታ እግዚአብሔር።'),
  ('ab6baca7-1ab6-566c-aaff-05267d876364', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 6, 6, 'በማጎግም ላይ፥ በሰላምም በደሴቶች በሚቀመጡ ላይ እሳትን እሰድዳለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('ec77bacb-4e10-548a-ab7c-2bb45cf6fc5e', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 7, 7, 'ቅዱሱም ስሜ በሕዝቤ በእስራኤል መካከል ይታወቃል፤ ቅዱሱንም ስሜን ከእንግዲህ ወዲህ አላረክስም፤ አሕዛብም የእስራኤል ቅዱስ እግዚአብሔር፥ እኔ እንደ ሆንሁ ያውቃሉ።'),
  ('c48f8d06-508a-5fd9-a40c-426343d7753f', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 8, 8, 'እነሆ ይመጣል፤ እንደሚሆንም ታውቃላችሁ፥ ይላል ጌታ እግዚአብሔር፤ ያልሁት ቀን ይህ ነው።'),
  ('27138f3f-3519-578d-a854-4c1277c517a9', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 9, 9, 'በእስራኤልም ከተሞች የሚኖሩ ይወጣሉ፤ የጦር መሣሪያዎችንም በእሳት ያቃጥላሉ፤ አላባሽ አግሬ ጋሻንና ጋሻን፥ ቀስትንና ፍላጻዎችን፥ የእጅ በትሮችንና ጦርንም ያቃጥላሉ፤ ሰባት ዓመት በእሳት ያቃጥሉአቸዋል።'),
  ('e5969448-ed02-55cb-ab49-08ce43939148', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '35bfe270-ac10-5f14-aac4-980e3109d798', 10, 10, 'እንጨትን ከሜዳ አይወስዱም፤ ከዱርም አይቈርጡም፤ ነገር ግን የጦር መሣሪያን በእሳት ያነድዳሉ፤ የገፈፉአቸውንም ይገፍፋሉ፤ የበዘበዙአቸውንም ይበዘብዛሉ፤ ይላል ጌታ እግዚአብሔር።'),
  ('6376603d-cf47-5640-a2d1-fbef9001dbd8', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 1, 11, '“በዚያም ቀን በእስራኤል ዘንድ በባሕር ምሥራቅ የሚያልፉበትን ሸለቆ፥ የመቃብርን ስፍራ ለጎግ እሰጣለሁ፤ የሚያልፉትንም ይከለክላል፤ በዚያም ጎግንና ሠራዊቱን ሁሉ ይቀብራሉ፤ የሸለቆውንም ስም የጎግ መቃብር ብለው ይጠሩታል።'),
  ('adeaea72-646c-5c06-aa4b-7b20961653ba', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 2, 12, 'ምድርንም ያነደዱ የእስራኤል ወገኖች ሰባት ወር መቃብር እየቈፈሩ ይቀብሯቸዋል፤'),
  ('d4a2699e-fb86-5ac6-aaf5-f43b3f2ae349', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 3, 13, 'የምድሩም ሕዝብ ሁሉ ይቀብሯቸዋል፤ እኔም በምመሰገንበት ቀን ለክብር ይሆንላቸዋል ይላል ጌታ እግዚአብሔር።'),
  ('376f782b-1242-59ad-a979-cafce4f6e283', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 4, 14, 'ምድርንም ለማጽዳት በምድሩ ላይ ወድቀው የቀሩትን የሚቀብሩ፥ ዘወትር በምድሩ ላይ የሚዞሩትን ሰዎች ይቀጥራሉ፤ ከሰባት ወርም በኋላ ይመረምራሉ።'),
  ('ed585a4c-d063-5101-a069-149d374df17f', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 5, 15, 'በምድርም የሚዞሩት ያልፋሉ፤ የሰውንም አጥንት ቢያዩ፥ ቀባሪዎች በጎግ መቃብር ሸለቆ እስኪቀብሩት ድረስ ምልክት ያኖሩበታል።'),
  ('e3eb6843-95a9-57f4-af4a-3911781ca4b0', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 6, 16, 'ደግሞም የከተማዪቱ ስም የመቃብር ቦታ ይባላል። እንዲሁ ምድሪቱን ያጸዳሉ።'),
  ('6b34a4b9-91c2-5fbc-abde-f9ef8c25edab', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 7, 17, '“አንተም የሰው ልጅ ሆይ! ጌታ እግዚአብሔር እንዲህ ይላል፦ ለሚበርሩ ወፎች ሁሉና ለምድር አራዊት ሁሉ እንዲህ በላቸው፦ ኑ፤ ተከማቹ፤ ሥጋንም ትበሉ ዘንድ፥ ደምንም ትጠጡ ዘንድ በእስራኤል ተራሮች ላይ ወደማርድላችሁ መሥዋዕት፥ እርሱም ታላቅ መሥዋዕት፥ ከየሰፍራው ሁሉ ተሰብሰቡ።'),
  ('2bbf7c0f-c283-52b1-a504-f8fb895b2100', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 8, 18, 'የኀያላኑን ሥጋ ትበላላችሁ፤ የምድርንም አለቆች፥ የአውራ ፍየሎችንና የአውራ በጎችን፥ የወይፈኖችንና፥ የባሳንን ፍሪዳዎች ሁሉ፥ ደም ትጠጣላችሁ።'),
  ('1b10576a-a40f-5ab4-a293-72b32dfe93da', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 9, 19, 'እኔም ከማርድላችሁ መሥዋዕት እስክትጠግቡ ድረስ ጮማን ትበላላችሁ፤ እስክትሰክሩም ድረስ ደምን ትጠጣላችሁ።'),
  ('e43d48a0-a564-582d-ac0f-f80f208b61aa', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', '69c62aa4-5183-5018-a386-4eec4fa82572', 10, 20, 'ከማዕዴም ከፈረሶችና ከፈረሰኞች፥ ከኀያላንና ከሰልፈኞች ሁሉ ሥጋን ትጠግባላችሁ፥ ይላል ጌታ እግዚአብሔር።'),
  ('42db2669-e083-59d0-a6f4-691985a0c2e4', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 1, 21, '“ክብሬንም እሰጣችኋለሁ፤ አሕዛብም ሁሉ ያደረግሁትን ፍርዴን፥ በላያቸውም ያኖርኋትን እጄን ያያሉ።'),
  ('dae85433-7c79-5440-ae5f-b53319b8fc3f', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 2, 22, 'ከዚች ቀን ጀምሮ ለዘለዓለም የእስራኤል ቤት እኔ እግዚአብሔር አምላካቸው እንደ ሆንሁ ያውቃሉ።'),
  ('aa207f2c-0478-528d-affc-4e61ec8c0e8d', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 3, 23, 'አሕዛብም የእስራኤል ቤት በኀጢአታቸው ምክንያት እንደ ተማረኩ ያውቃሉ፤ ስለ ከዱኝ እኔም ፊቴን ከእነርሱ ስለ መለስሁ፥ በጠላቶቻቸው እጅ አሳልፌ ሰጠኋቸው፥ እነርሱም ሁሉ በሰይፍ ወደቁ።'),
  ('8f91b22f-2140-5040-a915-c3d9c5e08a49', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 4, 24, 'እንደ ርኵሰታቸውም እንደ መተላለፋቸውም መጠን አደረግሁባቸው፤ ፊቴንም ከእነርሱ መለስሁ።'),
  ('fd351e25-8671-580e-ad7f-15c9d5a591c4', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 5, 25, '“ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ አሁን የያዕቆብን ምርኮ እመልሳለሁ፤ ለእስራኤልም ቤት ሁሉ እራራለሁ፤ ስለ ቅዱስ ስሜም እቀናለሁ።'),
  ('bd483ff6-cf96-510c-ae59-e56213fddd6f', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 6, 26, 'በምድራቸው ተዘልለው በተቀመጡ ጊዜ እፍረታቸውንና የበደሉኝን በደላቸውን ሁሉ ይሸከማሉ፤ የሚያስፈራቸውም የለም።'),
  ('f5d8c5b6-8ed0-58e2-ab10-e490c51bfcc0', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 7, 27, 'ከአሕዛብም ዘንድ በመለስኋቸው ጊዜ፥ ከአሕዛብም ሀገሮች በሰበሰብኋቸው ጊዜ፥ በብዙ አሕዛብም ፊት በተቀደስሁባቸው ጊዜ፥'),
  ('0ca4e65c-779f-512b-a995-b3a1e8ccd998', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 8, 28, 'እኔም ወደ አሕዛብ አስማርኬአቸዋለሁና፥ ወደ ገዛ ምድራቸውም ሰብስቤአቸዋለሁና እኔ እግዚአብሔር አምላካቸው እንደ ሆንሁ ያውቃሉ፤ በዚያም ከእነርሱ አንድ ሰው ከእንግዲህ ወዲያ አላስቀርም፤'),
  ('16e2704e-210d-5e78-a181-b429a604dac3', '9ffccfde-0f8a-5eb8-ace5-6eb620dd92ee', 'ebe0679c-b88a-5d20-a1d7-cebed6134458', 9, 29, 'ፊቴንም ከእነርሱ ከእንግዲህ ወዲህ አልመልስም፤ መዓቴን በእስራኤል ቤት ላይ አፍስሻለሁና፥” ይላል ጌታ እግዚአብሔር።'),
  ('b2bbca78-055d-579f-a82a-80a6ef9c9902', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 1, 1, 'በተማረክን በሃያ አምስተኛው ዓመት በዓመቱ መጀመሪያ ከወሩ በዐሥረኛው ቀን፥ ከተማዪቱ ከተመታች በኋላ በዐሥራ አራተኛው ዓመት፥ በዚያው ቀን የእግዚአብሔር እጅ በእኔ ላይ ነበረ፤ እርሱም ወደዚያ ወሰደኝ።'),
  ('eba8033d-fa45-5234-a8ec-55087f8f34e1', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 2, 2, 'በእግዚአብሔር ራእይ ወደ እስራኤል ምድር አመጣኝ፤ እጅግም በረዘመ ተራራ ላይ አኖረኝ፤ በዚያም ላይ እንደ ከተማ ሆኖ የተሠራ ነገር በፊቴ ነበረ።'),
  ('f3667b76-0592-5efd-a3c9-96ed23920b96', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 3, 3, 'ወደዚያም አመጣኝ፤ እነሆም መልኩ እንደሚያንፀባርቅ ናስ መልክ የመሰለ አንድ ሰው በዚያ ነበረ፤ በእጁም የተልባ እግር ገመድና የመለኪያ ዘንግ ነበረ፤ እርሱም በበሩ አጠገብ ቆሞ ነበር።'),
  ('64b16449-4139-5670-aa5b-0800bd56286b', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 4, 4, 'ያም ሰው፥ “የሰው ልጅ ሆይ! ይህን አሳይህ ዘንድ አንተ ወደዚህ መጥተሃልና በዐይንህ እይ፤ በጆሮህም ስማ፤ የማሳይህንም ሁሉ በልብህ ጠብቅ፤ የምታየውንም ሁሉ ለእስራኤል ቤት ንገር” አለኝ።'),
  ('621a8890-540b-5b23-a4f1-91f0ee7cb9df', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 5, 5, 'እነሆም በቤቱ ውጭ በዙሪያው ቅጥር ነበረ፤ በሰውየውም እጅ የክንዱ ልክ አንድ ክንድ ከጋት የሆነ ስድስት ክንድ ያለበት የመለኪያ ዘንግ ነበረ፤ የቅጥሩንም ስፋት አንድ ዘንግ ቁመቱንም አንድ ዘንግ አድርጎ ለካ።'),
  ('7d5ef9aa-c766-51b1-a801-4a67fc12bb02', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 6, 6, 'ወደ ምሥራቅ ወደሚመለከተውም በር መጣ፤ በሰባቱም ደረጃዎች ላይ ወጣ፤ በበሩ በኩል ያለውንም የመድረኩን ወለል ወርዱን አንድ ዘንግ አድርጎ ለካ፤ የሁለተኛውም ወለል ወርድ አንድ ዘንግ ነበረ።'),
  ('1611068c-fdd8-5355-a161-82189d0cc258', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 7, 7, 'የዕቃ ቤቱ ሁሉ ርዝመት አንድ ዘንግ፤ ወርዱም አንድ ዘንግ ነበረ፤ በዕቃ ቤቶቹም መካከል አምስት ክንድ ነበረ፤ በበሩም ደጀ ሰላም፤ በስተውስጥ በኩል የሚገኝ የበሩ የመድረክ ወለል አንድ ዘንግ ነበረ።'),
  ('6f06ec3a-1f9e-5d5e-a0c0-e637d09fb8a8', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 8, 8, 'በስተውስጥም ያለውን የበሩን ደጀሰላም አንድ ዘንግ አድርጎ ለካ።'),
  ('a057596d-6698-5995-a01e-53d84857ab67', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 9, 9, 'የበሩንም ደጀ ሰላም ስምንት ክንድ፤ የግንቡንም አዕማድ ወርድ ሁለት ክንድ አድርጎ ለካ፤ የበሩም ደጀ ሰላም በስተውስጥ ነበረ።'),
  ('e100babb-3c29-5001-a1d8-5948e9f10174', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 10, 10, 'የምሥራቁም ዕቃ ቤቶች በዚህ በኩል ሦስት፥ በዚያም በኩል ሦስት፥ ነበሩ፤ ለሦስቱም አንድ ልክ ነበረ፤ የግንቡም አዕማድ ወርድ በዚህ በኩልና በዚያ በኩል አንድ ልክ ነበረ።'),
  ('49f9988b-eb6d-5b50-a24a-461d96d5e8c6', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 11, 11, 'የበሩንም መግቢያ ወርድ ዐሥር ክንድ፥ የበሩንም ርዝመት ዐሥራ ሦስት ክንድ አድርጎ ለካ።'),
  ('efd0d5f0-4ace-5e67-aaa8-ba8d175f13ef', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 12, 12, 'በዕቃ ቤቱም ፊት በዚህ በኩል አንድ ክንድ፥ በዚያም በኩል አንድ ክንድ የሆነ ዳርቻ ነበረ፤ የዕቃ ቤቱም በዚህ በኩል ስድስት ክንድ በዚያም በኩል ስድስት ክንድ ነበሩ።'),
  ('31aa05b6-908c-53fe-a852-62be62da41dd', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 13, 13, 'ከአንዱም የዕቃ ቤት ደርብ ጀምሮ እስከ ሌላው ደርብ ድረስ የበሩን ወርድ ሃያ አምስት ክንድ አድርጎ ለካ፤ በሩና በሩም ትይዩ ነበረ።'),
  ('21e7f9f4-eb38-5b2a-ab2f-1682695474fa', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 14, 14, 'ደጀ ሰላሙንም ሃያ ክንድ አድርጎ ለካ፤ በበሩም ደጀ ሰላም ዙሪያ አደባባይ ነበረ።'),
  ('79c1942a-0814-5e6f-a559-839a99f962bd', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 15, 15, 'ከበሩም መግቢያ ፊት ጀምሮ እስከ ውስጠኛው የበሩ ደጀ ሰላም መጨረሻ ድረስ አምሳ ክንድ ነበረ።'),
  ('fad56d3b-26ad-52b0-a31d-da769b637e58', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 16, 16, 'በዕቃ ቤቶቹም በበሩ ውስጥ በዙሪያው በነበሩትም በግንቡ አዕማድ የዐይነ ርግብ መስኮቶች ነበሩባቸው፤ ደግሞም በደጀ ሰላሙ ውስጥ በዙሪያው መስኮቶች ነበሩ፤ በግንቡም አዕማድ ሁሉ ላይ የዘንባባ ዛፍ ተቀርጾባቸው ነበር።'),
  ('b87553e2-966e-5f69-ab59-fe4fe93cbcb4', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 17, 17, 'ወደ ውስጠኛው አደባባይም አገባኝ፤ እነሆም በአደባባዩ ዙሪያ የተሠሩ ዕቃ ቤቶችና ወለል ነበሩ፤ በወለሉም ላይ ሠላሳ ዕቃ ቤቶች ነበሩ።'),
  ('bff75b84-6839-5f8b-a1e2-b1a22b68638a', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 18, 18, 'ወለሉም በበሮች አጠገብ ነበረ፤ ይህም ታችኛው ወለል እንደ በሮቹ ርዝመት መጠን ነበረ።'),
  ('43131e7f-82df-518c-a915-55fb371efa54', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 19, 19, 'ከታችኛውም በር ፊት ጀምሮ እስከ ውስጠኛው አደባባይ ፊት ድረስ ወርዱን አንድ መቶ ክንድ አድርጎ ወደ ምሥራቅና ወደ ሰሜን ለካ።'),
  ('7353676a-fd9d-55e2-a006-62b288116deb', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 20, 20, 'ወደ ሰሜንም መራኝ፤ እነሆም በውጭው አደባባይ ያለ ወደ ሰሜን የሚመለከት በር ነበረ፤ ርዝመቱንና ወርዱንም ለካ።'),
  ('585c7915-d169-5bad-a020-05fe206c2e51', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 21, 21, 'የዕቃ ቤቶቹም በዚህ በኩል ሦስት፥ በዚያም በኩል ሦስት ነበሩ፤ የግንቡ አዕማድና መዛነቢያዎቹም፥ ወደ ምሥራቅ የሚያሳዩ ዘንባባዎቹም አምሳ ክንድ ነበሩ፤ ወርዱም ሃያ አምስት ክንድ ነበረ።'),
  ('51617dff-a9b8-5ed3-a097-5fa9b3f13379', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 22, 22, 'መስኮቶቹም፥ መዛነቢያዎቹም፥ የዘንባባ ዛፎቹም ወደ ምሥራቅ እንደሚመለከተው በር ልክ ነበሩ፤ ወደ እርሱም የሚያደርሱ ሰባት ደረጃዎች ነበሩ፤ መዛነቢያዎቹም በፊቱ ነበሩ።'),
  ('8475e5fb-4a74-5089-ac97-5fa4727ee638', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 23, 23, 'በውስጠኛውም አደባባይ በሰሜኑና በምሥራቁ በኩል በሌላው በር አንጻር በር ነበረ፤ ከበርም እስከ በር አንድ መቶ ክንድ አድርጎ ለካ።'),
  ('0d7eb9a2-c3d4-5d68-a3b0-5c869ba41ac7', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 24, 24, 'ወደ ደቡብም መራኝ፤ እነሆም ወደ ደቡብ የሚመለከት በር ነበረ፤ የግንቡን አዕማድና መዛነቢያዎቹንም እንደዚያው መጠን አድርጎ ለካ።'),
  ('88e6378c-2bc6-5fb0-a18e-37722aef5192', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 25, 25, 'በእርሱና በመዛነቢያዎቹም ዙሪያ እንደ እነዚያ መስኮቶች የሚመስሉ መስኮቶች ነበሩ፤ ርዝመቱ አምሳ ክንድ፥ ወርዱም ሃያ አምስት ክንድ ነበረ።'),
  ('bead9def-0ded-59fa-aaa2-55e1f5a5990c', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 26, 26, 'ወደ እርሱም የሚያደርሱ ሰባት ደረጃዎች ነበሩ፤ መዛነቢያዎቹም በፊቱ ነበሩ፤ በግንቡም አዕማድ ላይ አንዱ በዚህ አንዱም በዚያ ወገን ሆኖ የዘንባባ ዛፍ ተቀርጾባቸው ነበር።'),
  ('f200fd40-cea8-5249-ad07-0182c2ba1469', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 27, 27, 'በውስጠኛውም አደባባይ በደቡብ በኩል በር ነበረ፤ ከበር እስከ በር ድረስ በደቡብ በኩል መቶ ክንድ አድርጎ ለካ።'),
  ('eac842dc-967d-57eb-ac4e-3443990cc668', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 28, 28, 'በደቡብም በር በኩል ወደ ውስጠኛው አደባባይ አገባኝ፤ እንደዚያውም መጠን አድርጎ የደቡብን በር ለካ፤'),
  ('14a06d6a-a345-52e6-abae-a63971bb4c8c', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 29, 29, 'እንደዚያውም መጠን አድርጎ የዕቃ ቤቶቹንና የግንቡን አዕማድ፥ መዛነቢያዎቻቸውንም ለካ፤ በእርሱና በመዛነቢያዎቹም ዙሪያ መስኮቶች ነበሩ፤ ርዝመቱ አምሳ ክንድ፥ ወርዱም ሃያ አምስት ክንድ ነበረ።'),
  ('29b6c75b-5d35-5711-a0e7-e4225bf1da48', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 30, 30, 'በዙሪያውም ደጀ ሰላሞች ነበሩ፤ ርዝመታቸውም ሃያ አምስት ክንድ፥ ወርዳቸውም አምስት ክንድ ነበረ።'),
  ('c6db3e68-ba2f-5ee3-a8a1-c0e0080c30a5', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 31, 31, 'መዛነቢያዎቹም ወደ ውጭው አደባባይ ይመለከቱ ነበር፤ በግንቡም አዕማድ ላይ የዘንባባ ዛፍ ተቀርጾ ነበር፤ ወደ እርሱም የሚያደርሱ ስምንት ደረጃዎች ነበሩ።'),
  ('15127324-ba96-519a-a46e-b81b0913b8eb', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 32, 32, 'በውስጠኛውም አደባባይ በምሥራቅ በኩል አገባኝ፤ በሩንም ለካ፤ መጠኑም እንደ እነዚያ ነበረ።'),
  ('0ff93332-7148-5ff0-a4f0-c37bb9c1f2e2', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 33, 33, 'እንደዚያም መጠን የዕቃ ቤቶቹንና የግንቡን አዕማድ፥ መዛነቢያዎቹንም ለካ፤ በእርሱና በመዛነቢያዎቹም ዙሪያ መስኮቶች ነበሩ፤ ርዝመቱም አምሳ ክንድ፥ ወርዱም ሃያ አምስት ክንድ ነበረ።'),
  ('de084d33-7e60-5267-a067-9bd4fb485cc7', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 34, 34, 'መዛነቢያዎቹም በስተ ውጭ ወደ አለው አደባባይ ይመለከቱ ነበር፤ በግንቡም አዕማድ ላይ በዚህና በዚያ ወገን የዘንባባ ዛፍ ተቀርጾ ነበር፤ ወደ እርሱም የሚያደርሱ ስምንት ደረጃዎች ነበሩት።'),
  ('2f83434c-662d-575c-a849-864f8b1c2532', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 35, 35, 'በሰሜንም ወደ አለው በር አመጣኝ፤ እንደዚያውም መጠን ለካው፤'),
  ('ce97bdbf-6905-524e-a244-d50014b09794', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 36, 36, 'የዕቃ ቤቶቹንና የግንቡን አዕማድ፥ መዛነቢያዎቹንም ለካ፤ በዙሪያውም መስኮቶች ነበሩበት፤ ርዝመቱም አምሳ ክንድ፥ ወርዱም ሃያ አምስት ክንድ ነበረ።'),
  ('95d154c1-941f-5960-a42f-00d33ba0b542', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 37, 37, 'የግንቡም አዕማድ ወደ ውጭው አደባባይ ይመለከቱ ነበር፤ በግንቡም አዕማድ ላይ በዚህና በዚያ ወገን የዘንባባ ዛፍ ተቀርጾ ነበር፤ ወደ እርሱም የሚያወጡ ስምንት ደረጃዎች ነበሩት።'),
  ('34395c2c-6a64-5b1f-aa6d-20b45024cb0d', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 38, 38, 'በበሮቹም በግንቡ አዕማድ አጠገብ ዕቃ ቤቱና መዝጊያው ነበሩ፤ በዚያም የሚቃጠለውን መሥዋዕት ያጥቡ ነበር።'),
  ('fc34090f-609d-5b48-a8da-602470df13a1', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 39, 39, 'የሚቃጠለውንም መሥዋዕት፥ የኀጢአቱንና የበደሉንም መሥዋዕት ያርዱባቸው ዘንድ፥ በበሩ ደጀ ሰላም በዚህ ወገን ሁለት ገበታዎች፥ በዚያም ወገን ሁለት ገበታዎች ነበሩ።'),
  ('2afa5e77-4b1b-5edf-a5e4-1820891f1b6b', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 40, 40, 'በሰሜን በኩል በአለው በር በስተውጭው፥ በመወጣጫው ደረጃዎች አጠገብ፥ በአንዱ ወገን ሁለት ገበታዎች ነበሩ፤ በሌላውም ወገን በበሩ ደጀ ሰላም በኩል ሁለት ገበታዎች ነበሩ።'),
  ('2e09c040-2075-5578-a193-ef9d8f003e7e', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 41, 41, 'በበሩ አጠገብ በዚህ ወገን አራት ገበታዎች፥ በዚያም ወገን አራት ገበታዎች ነበሩ፤ መሥዋዕት የሚያርዱባቸው ገበታዎች ስምንት ነበሩ።'),
  ('d8be1690-3138-5b5c-ad82-cce79ad8cc52', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 42, 42, 'ስለሚቃጠለውም መሥዋዕት ርዝመታቸው አንድ ክንድ ተኩል ወርዳቸውም አንድ ክንድ ተኩል ቁመታቸውም አንድ ክንድ የሆኑ፥ የሚቃጠለውን መሥዋዕትና ሌላውን መሥዋዕት የሚያርዱበትን ዕቃ ያኖሩባቸው ዘንድ፥ ከተጠረበ ድንጋይ የተሠሩ አራት ገበታዎች ነበሩ።'),
  ('1bff3e80-aa8e-5263-a0f4-e18b40b5ccd7', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 43, 43, 'በዙሪያውም በስተውስጥ የነበረው የለዘበ ከንፈራቸው አንድ ጋት ነበረ፤ በገበታውም ላይ መክደኛ ነበረ፤ ከፀሐይና ከዝናምም የተሰወረ ነበረ።'),
  ('f79a91fa-c72b-53cd-a1bb-95a7c925b8b2', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 44, 44, 'ወደ ውስጠኛውም አደባባይ አገባኝ፤ እነሆም ሁለት ቤቶች ነበሩ፤ አንዱ ወደ ሰሜን በሚመለከተው በር አጠገብ ነበረ፤ መግቢያውም ወደ ደቡብ ይመለከት ነበረ፤ ሌላውም ወደ ደቡብ በሚመለከተው በር አጠገብ ነበረ፤ መግቢያውም ወደ ሰሜን ይመለከት ነበር።'),
  ('5d909318-c332-51cc-a43b-9de363364cdb', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 45, 45, 'ሰውዬውም፥ “ይህ ወደ ደቡብ የሚመለከት ቤት ለማገልገል ለሚተጉ ካህናት ነው።'),
  ('28b9fb89-ff72-5810-a17b-17e13855b365', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 46, 46, 'ወደ ሰሜንም የሚመለከተው ቤት መሠዊያዉን ለማገልገል ለሚተጉ ካህናት ነው፤ እነዚህ ከሌዊ ልጆች መካከል ያገለግሉት ዘንድ ወደ እግዚአብሔር የሚቀርቡ የሳዶቅ ልጆች ናቸው” አለኝ።'),
  ('4784d97a-7ed5-5718-acf2-20e357a10afd', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 47, 47, 'አደባባዩንም በአራት ማዕዘኑ ርዝመቱን መቶ ክንድ፥ ወርዱንም መቶ ክንድ አድርጎ ለካ፤ መሠዊያውም በቤቱ ፊት ነበረ።'),
  ('0737f4eb-da6b-5e90-af89-32cb44187fe8', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 48, 48, 'ወደ ቤቱም ደጀ ሰላም አመጣኝ፤ የደጀ ሰላሙንም የግንብ አዕማድ ወርድ በዚህ ወገን አምስት ክንድ፤ በዚያም ወገን አምስት ክንድ አድርጎ ለካ፤ የበሩም ወርድ ዐሥራ አራት ክንድ ነበረ፤ በበሩም በዚህ ወገንና በዚያ ወገን የነበሩት ግንቦች ሦስት ሦስት ክንድ ነበሩ።'),
  ('8107f195-19bd-5855-a756-eac36fa04016', '245f9e82-4cf5-5855-a7d4-1c7f9039b958', 'bf1ff004-9746-51df-a941-812a67ef0328', 49, 49, 'የደጀ ሰላሙም ርዝመት ሃያ ክንድ፥ ወርዱም ዐሥራ ሁለት ክንድ ነበረ፥ ወደ እርሱም የሚያደርሱ ዐሥር ደረጃዎች ነበሩ፤ አንድ በዚህ ወገን፥ አንድም በዚያ ወገን ሆነው በመቃኖቹ አጠገብ የግንብ አዕማድ ነበሩ።'),
  ('180a5c0f-a558-5fff-a312-f48d466ce31b', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 1, 1, 'ወደ መቅደሱም አገባኝ፤ የግንቡንም አዕማድ ወርድ በዚህ ወገን ስድስት ክንድ፥ በዚያም ወገን ስድስት ክንድ አድርጎ ለካ።'),
  ('9c87bd73-f9b5-55b3-a98a-ab9bdbff1433', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 2, 2, 'የመግቢያውም ወርድ ዐሥር ክንድ ነበረ፤ የመግቢያውም መቃኖች በዚህ ወገን አምስት ክንድ፥ በዚያም ወገን አምስት ክንድ ነበሩ፤ ርዝመቱንም አርባ ክንድ፥ ወርዱንም ሃያ ክንድ አድርጎ ለካ።'),
  ('48da8383-eafb-51c2-acfc-8165b7950568', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 3, 3, 'ወደ ውስጥም ገባ፤ የመግቢያውንም የግንብ አዕማድ ወርድ ሁለት ክንድ አድርጎ ለካ፤ የመግቢያውም ወርድ ስድስት ክንድ ነበረ፤ የመግቢያውም ግንብ ወርድ በዚህ ወገን ሰባት ክንድ፥ በዚያም ወገን ሰባት ክንድ ነበረ።'),
  ('2916131f-112f-52d7-a490-e5110728f001', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 4, 4, 'በመቅደሱም ፊት ርዝመቱን አርባ ክንድ፥ ወርዱንም ሃያ ክንድ አድርጎ ለካና፥ “ይህ ቅድስተ ቅዱሳን ነው” አለኝ።'),
  ('f705283a-de77-5963-a25a-a6177e839b25', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 5, 5, 'የመቅደሱንም ግንብ ስድስት ክንድ፥ በመቅደሱም ዙሪያ ሁሉ ያሉትን የጓዳዎቹን ሁሉ ወርድ አራት ክንድ አድርጎ ለካ።'),
  ('5f57409b-29d9-528f-a262-89283d499a22', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 6, 6, 'ጓዳዎቹም አንዱ ከአንዱ በላይ በሦስት ደርብ ነበሩ፤ በእያንዳንዱም ደርብ ሠላሳ ጓዳዎች ነበሩ። በመቅደሱም ግንብ ዙሪያ ደገፋዎች ይሆኑ ዘንድ አረፍቶች ነበሩ፤ ከመቅደሱ ግንብ ጋር ግንአልተያያዙም ነበር።'),
  ('36a01d9b-f145-59e7-a959-58c2e514a747', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 7, 7, 'በቤቱም ዙሪያ ባለ ግንብ ውስጥ በነበሩት አረፍቶች ምክንያት ላይኞቹ ጓዳዎች ከታችኞቹ ጓዳዎች ይበልጡ ነበር፤ ከታችኛውም ደርብ ወደ መካከለኛው፥ ከመካከለኛውም ደርብ ወደ ሦስተኛው የሚወጣበት ደረጃ ነበረ።'),
  ('0765ac2e-2cf7-51e8-a180-39b1716fbe7e', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 8, 8, 'ለመቅደሱም ከፍ ያለ ወለል በዙሪያው እንዳለው አየሁ፤ የጓዳዎቹም መሠረት ቁመቱ ሙሉ ዘንግ የሚያህል ስድስት ክንድ ነበረ።'),
  ('90468a98-9841-5352-afc0-6e29fe591839', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 9, 9, 'የጓዳዎቹም የውጭው ግንብ ወርድ አምስት ክንድ ነበረ፤ በመቅደሱም ጓዳዎች አጠገብ የቀረ አንድ ባዶ ስፍራ ነበረ።'),
  ('b938491d-c274-58d3-a1b1-d770852fe2f7', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 10, 10, 'በዕቃ ቤቶቹም መካከል ወርዱ በቤቱ ዙሪያ ሁሉ ሃያ ክንድ ነበረ።'),
  ('de797007-6912-5a7d-a221-0c830ae4da85', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 11, 11, 'የጓዳዎቹም መግቢያ ብቻውን ወደሚኖረው ስፍራ ነበረ፤ አንዱ ደጅ ወደ ሰሜን መንገድ፤ አንዱም ደጅ ወደ ደቡብ መንገድ፥ ብቻውን የሚኖረው ስፍራ ወርዱ አምስት ክንድ በዙሪያው ነበር።'),
  ('590c2091-56cf-5241-ad02-3d2d6967b51e', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 12, 12, 'በምዕራብም በኩል በልዩ ስፍራ አንጻር የነበረ ግቢ ስፋቱ ሰባ ክንድ ነበረ። በግቢውም ዙሪያ የነበረ ግንብ ወርዱ አምስት ክንድ፥ ርዝመቱም ዘጠና ክንድ ነበረ።'),
  ('9678b31d-84b7-5f7f-ab22-7967fddfe5e2', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 13, 13, 'የቤተ መቅደሱንም ርዝመት መቶ ክንድ፥ የልዩውን ስፍራና ግቢውን ከግንቡ ጋር አንድ መቶ ክንድ አድርጎ ለካ።'),
  ('7ad64589-f3b0-560f-aef8-0c89adc6b4db', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 14, 14, 'ደግሞም በምሥራቅ በኩል የነበረውን የቤተ መቅደሱንና የልዩውን ስፍራ ወርድና ቁመት አንድ መቶ ክንድ አድርጎ ለካ።'),
  ('8528e1d0-60f6-56f7-a366-510b82e2c30a', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 15, 15, 'ወደኋላውም በአለው በልዩ ስፍራ አንጻር የነበረውን የግቢውን ርዝመት፥ በዚህና በዚያ ከነበሩት ከግንቦቹ ጋር አንድ መቶ ክንድ አድርጎ ለካ፤ የውስጡንም መቅደስ፥ የአዳራሹንም መዛነቢያዎች ለካ።'),
  ('e34f163c-cb1e-51df-a79b-38fb8d4d5ee6', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 16, 16, 'መድረኮቹ፥ መስኮቶቹና አዕማዱ፥ በስተውስጥ ያለው ክፍል ደጀ ሰላሙም በእንጨት ተለብጠው ነበር፤ በሦስቱም ዙሪያ የዐይነ ርግብ መስኮቶች ነበሩ። መቅደሱም በመድረኩ አንጻር ከመሬት ጀምሮ እስከ መስኮቶቹ ድረስ በእንጨት ተለብጦ ነበር፤ መስኮቶቹም የዐይነ ርግብ ነበሩ፤'),
  ('86fbc68e-718f-519b-a351-59134be0acbf', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 17, 17, 'በደጁም ላይ እስከ ውስጠኛው ክፍል ድረስ፥ በውጭም ግንቡ ሁሉ ውስጡም፥ ውጭውም ዙሪያውን ተለብጦ ነበር።'),
  ('f1cd4965-ed90-5f0b-a7e4-2c4e793d43c9', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 18, 18, 'ኪሩቤልና የዘንባባው ዛፎች ተቀርጸውበት ነበር፤ የዘንባባውም ዛፍ ከኪሩብና ከኪሩብ መካከል ነበረ፤ ለእያንዳዱም ኪሩብ ሁለት ፊት ነበረው።'),
  ('976460db-9fce-57f4-a1a6-fc0a4a08e1a7', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 19, 19, 'በአንድ ወገን ወደ አለው የዘንባባ ዛፍ የሰው ፊት ይመለከት ነበር፤ በሌላውም ወገን ወደ አለው ዘንባባ የአንበሳ ፊት ይመለከት ነበር፤ በቤቱ ሁሉ ዙሪያ እንደዚህ ተቀርጾ ነበር።'),
  ('f690c622-edeb-528b-a34d-35cca36aa4f0', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 20, 20, 'ከመሬት አንሥቶ እስከ ደጁ ራስ ድረስ ኪሩቤልና የዘንባባ ዛፎች ተቀርጸው ነበር፤ የመቅደሱ ግንብ እንደዚህ ነበረ።'),
  ('f9e81fa3-eb12-5e68-a6da-fc74925bee50', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 21, 21, 'የመቅደሱ መቃኖችም አራት ማዕዘን ነበሩ፤ የመቅደሱ ፊትም መልኩ እንደሌላው መልክ ነበረ።'),
  ('442422db-d707-587f-ad5c-f3c33740d491', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 22, 22, 'መሠዊያውም ቁመቱ ሦስት ክንድ፥ ርዝመቱ ሁለት ክንድ፥ ወርዱም ሁለት ክንድ ሆኖ ከእንጨት ተሠርቶ ነበር፤ ማዕዘኖቹም፥ እግሩም፥ አገዳዎቹም ከእንጨት ተሠርተው ነበር፤ እርሱም፥ “በእግዚአብሔር ፊት ያለችው ገበታ ይህች ናት” አለኝ።'),
  ('9973a31b-5188-5680-a2f4-26799d124e0f', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 23, 23, 'ለመቅደሱና ለተቀደሰው ስፍራ ሁለት መዝጊያዎች ነበሩአቸው።'),
  ('836e8482-5b87-5854-aa74-a9a71af5c84d', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 24, 24, 'ለእያንዳንዱ መዝጊያም ሁለት ተዘዋዋሪ ሳንቃዎች ነበሩት፤ ለአንዱ መዝጊያ ሁለት፥ ለሌላውም መዝጊያ ሁለት ሳንቃዎች ነበሩት።'),
  ('2d70d2f2-1fa5-5e15-a09d-76fc5a19b985', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 25, 25, 'በግንቡም ላይ በተቀረጹት ዓይነት በእነዚህ በመቅደሱ መዝጊያዎች ላይ ኪሩቤልና የዘንባባ ዛፎች ተቀርጸው ነበር፤ በስተውጭም በአለው በደጀ ሰላሙ ፊት የእንጨት መድረክ ነበረ።'),
  ('525c6aa7-143a-51de-a4e1-a0f2a3082505', '705209ec-3889-513f-ac18-56c539006a83', 'b9477078-e1d4-55ca-ae15-7a790e893f3b', 26, 26, 'በደጀ ሰላሙም በሁለቱ ወገን በዚህና በዚያ የዐይነ ርግብ መስኮቶችና የተቀረጹ የዘንባባ ዛፎች ነበሩበት፤ የመቅደሱም ጓዳዎችና የእንጨቱ መድረክ እንዲሁ ነበሩ።'),
  ('6115442c-ae9e-520c-af5f-9b127f92c83a', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 1, 1, 'በውጭም አደባባይ በሰሜኑ መንገድ በምሥራቅ በኩል አወጣኝ፤ በልዩውም ስፍራ አንጻርና በሰሜን በኩል በአለው ግቢ ፊት ለፊት ወዳሉት አምስት ዕቃ ቤቶች አገባኝ።'),
  ('69b302f8-0e3e-536d-a4ae-b63c1ca0ca3e', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 2, 2, 'መቶ ክንድ በሆነው ርዝመት ፊት በሰሜን በኩል መዝጊያ ነበረ፤ ወርዱም አምሳ ክንድ ነበረ።'),
  ('a9d654e9-6d1b-5db7-aa0d-442135ff26cc', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 3, 3, 'በውስጠኛውም አደባባይ በሃያው ክንድ አንጻር፥ በውጭውም አደባባይ በወለሉ አንጻር በሦስት ደርብ በትይዩ የተሠራ መተላለፊያ ነበረ።'),
  ('2dafd499-7fe3-5945-aaed-f83e0160d46d', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 4, 4, 'በዕቃ ቤቶቹም ፊት በስተውስጥ ወርዱ ዐሥር ክንድ፥ ርዝመቱ መቶ ክንድ የሆነ መንገድ ነበረ፤ መግቢያዎቻቸውም ወደ ሰሜን ይመለከቱ ነበር።'),
  ('aadb13e2-1435-58de-aa45-83148d88054f', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 5, 5, 'መተላለፊያውም አሳጥሮአቸዋልና ላይኞቹ ዕቃ ቤቶች ከመካከለኞቹና ከታችኞቹ ይልቅ አጫጭር ነበሩ።'),
  ('ee6acb3e-2739-5d11-a4b5-d1915c1b23d7', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 6, 6, 'በሦስትም ደርብ ተሠርተው ነበርና፥ በአደባባዩም እንዳሉት አዕማድ፥ አዕማድ አልነበሩላቸውምና ስለዚህ ከመካከለኞቹና ከታችኞቹ ይልቅ ጠባብ ነበሩ።'),
  ('d2be8cb5-7b24-59b5-ad1f-504e5867b2b7', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 7, 7, 'በውጭ በዕቃ ቤቶቹ አጠገብ ያለው፥ ወደ ውጭው አደባባይ የሚያመለክተው ቅጥር፥ በዕቃ ቤቶች ትይዩ የሆነ ርዝመቱ አምሳ ክንድ ነበረ።'),
  ('e9a59f45-c87a-53e7-a35d-02fa5dc7f5e6', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 8, 8, 'በመቅደሱ ፊት የነበሩት ዕቃ ቤቶች ርዝመታቸው መቶ ክንድ ሲሆን፥ በውጭው አደባባይ በኩል የነበሩት ዕቃ ቤቶች ርዝመታቸው አምሳ ክንድ ነበረና።'),
  ('e29d9c68-b07d-5a6d-a92c-1052f5ad685a', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 9, 9, 'ከእነዚህም ዕቃ ቤቶች በታች በስተምሥራቅ በኩል፥ ሰው ከውጭው አደባባይ የሚገባበት መግቢያ ነበረ፤ ይህም በቅጥሩ ራስ አጠገብ ነበረ።'),
  ('9161553c-84f0-5bc7-a926-4d1fc3c4e31a', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 10, 10, 'በደቡብም በኩል በልዩው ስፍራና በግቢው አንጻር ዕቃ ቤቶች ነበሩ።'),
  ('79be72fe-8acb-50b6-a998-aad16e37f568', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 11, 11, 'በስተፊታቸውም የነበረ መንገድ በሰሜን በኩል እንደ ነበረው እንደ ዕቃ ቤቶቹ መንገድ አምሳል ነበር። ርዝመታቸውም፥ ወርዳቸውም፥ መውጫቸውም፥ ሥርዐታቸውም፥ መዝጊያዎቻቸውም በዚያው ልክ ነበሩ።'),
  ('715198ce-ed97-5a43-a191-3c53536a5dc2', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 12, 12, 'በደቡብም በኩል ከአሉት ዕቃ ቤቶች በታች በምሥራቅ በኩል በቅጥሩ ራስ አጠገብ መግቢያ በር ነበር።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('1aeb1542-4213-51bb-ad81-acc4a9ae6a80', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 13, 13, 'እንዲህም አለኝ፥ “በልዩ ስፍራ አንጻር በሰሜንና በደቡብ በኩል ያሉ ዕቃ ቤቶች፥ እነርሱ ወደ እግዚአብሔር የሚቀርቡ የሳዶቅ ልጆች ካህናቱ ከሁሉ ይልቅ የተቀደሰውን ምግብ የሚበሉባቸው ቤቶች ናቸው። ስፍራው ቅዱስ ነውና በዚያ የተቀደሰውን ነገር፥ የእህሉን ቍርባን፥ የኀጢአቱንና የበደሉን መሥዋዕት ያኖራሉ።'),
  ('213e7947-950c-5dff-abd5-6b279db02568', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 14, 14, 'ካህናቱም በገቡ ጊዜ ከመቅደሱ በውጭው አደባባይ አይወጡም፤ የሚያገለግሉበትን ልብሳቸውን ግን ቅዱስ ነውና በዚያ ያኖሩታል፤ ሌላም ልብስ ለብሰው ወደ ሕዝብ ይወጣሉ።”'),
  ('92084297-d839-588c-a401-9ffef39c0af7', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 15, 15, 'ውስጠኛውንም ቤት ለክቶ በፈጸመ ጊዜ ወደ ምሥራቅ በሚመለከተው በር መንገድ አወጣኝ፤ እርሱንም ዙሪያውን ለካው።'),
  ('7dcd05b2-eb5a-576e-a27c-3c361eefd34a', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 16, 16, 'ወደ ምሥራቅ በሚመለከተውም በር ኋላ ቆመ፤ የምሥራቁን ወገን በመለኪያ ዘንግ አምስት መቶ ክንድ አድርጎ ለካ።'),
  ('d7d55c6c-2335-5522-a1f2-f094d53c6b6c', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 17, 17, 'ወደ ሰሜንም ዞረ፤ የሰሜኑንም ወገን በመለኪያ ዘንግ አምስት መቶ ክንድ አድርጎ ለካ።'),
  ('ab6d3454-7930-52e3-ac01-70156a7eb19b', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 18, 18, 'ወደ ደቡብም ዞረ፤ የደቡቡንም ወገን በመለኪያ ዘንግ አምስት መቶ ክንድ አድርጎ ለካ።'),
  ('92715f8f-b6cf-52fe-acf1-ef04d318d88c', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 19, 19, 'ወደ ምዕራብም ዞረ፤ የምዕራቡንም ወገን በመለኪያ ዘንግ አምስት መቶ ክንድ አድርጎ ለካ።'),
  ('a4ed19e5-04cb-5047-ae0c-313a94461b42', '14d46fff-a18c-54d1-a6ac-63ee35811723', '104374e9-ca51-5161-a831-0649a357c079', 20, 20, 'በአራቱም ወገን ለካ፤ የተቀደሰውንና ያልተቀደሰውን ይለይ ዘንድ ርዝመቱ አምስት መቶ ክንድ፥ ወርዱም አምስት መቶ ክንድ የሆነ ቅጥር በዙሪያው ነበረ።'),
  ('ec040658-fed3-5958-a82e-64f9ac555244', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 1, 1, 'ወደ ምሥራቅም ወደሚመለከተው በር አመጣኝ።'),
  ('48d3da4c-34e1-520e-a63a-afd5203d372e', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 2, 2, 'እነሆም የእስራኤል አምላክ ክብር ከምሥራቅ መንገድ መጣ፤ ድምፁም እንደ ብዙ ውኆች ይተምም ነበር፤ ከክብሩም የተነሣ ምድር ታበራ ነበር።'),
  ('5912ec6e-2118-5f24-a686-e5274796cee9', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 3, 3, 'ያየሁትም ራእይ ከተማዪቱን ለማጥፋት በመጣሁ ጊዜ እንደ አየሁት ራእይ ነበረ፤ ራእዩም በኮቦር ወንዝ እንደአየሁት ራእይ ነበረ፤ እኔም በግምባሬ ተደፋሁ።'),
  ('01dc96c1-8f03-5a9c-ad47-c022f9de285b', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 4, 4, 'የእግዚአብሔርም ክብር ወደ ምሥራቅ በሚመለከት በር ወደ መቅደሱ ገባ።'),
  ('92ca3999-a3ed-5f07-adad-a087382b6243', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 5, 5, 'መንፈስም አነሣኝ፤ ወደ ውስጠኛውም አደባባይ አገባኝ፤ እነሆም የእግዚአብሔር ክብር መቅደሱን መልቶት ነበር።'),
  ('c6093206-21b9-52fa-aa7d-e88605a99844', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 6, 6, 'በመቅደሱም ሆኖ የሚናገረኝን ሰማሁ፤ በአጠገቤም ሰው ቆሞ ነበር።'),
  ('7e332d9b-99e4-5d4a-a6e1-087d7cfe561b', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 7, 7, 'እንዲህም አለኝ፥ “የሰው ልጅ ሆይ! በእስራኤል ልጆች መካከል ለዘለዓለም የምቀመጥበት የዙፋኔ ስፍራና የእግሬ ጫማ መረገጫ ይህ ነው። ዳግመኛም የእስራኤል ቤትና ነገሥታቶቻቸው በዝሙታቸውና በከፍታዎቻቸው በአለው በነገሥታቶቻቸው ሬሳ ቅዱስ ስሜን አያረክሱም።'),
  ('4ba6d755-3974-5a8c-ab32-3e2db46eb363', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 8, 8, 'መድረካቸውን በመድረኬ አጠገብ፥ መቃናቸውንም በመቃኔ አጠገብ አድርገዋልና። በእኔና በእነርሱ መካከል ግንብ ብቻ ነበረ፤ በሠሩትም ርኵሰት ቅዱስ ስሜን አረከሱ፤ ስለዚህ በቍጣዬ አጠፋኋቸው።'),
  ('eede83ae-9b85-50a7-a438-4a49c7feec4f', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 9, 9, 'አሁንም ዝሙታቸውንና የነገሥታቶቻቸውን ሬሳ ከእኔ ዘንድ ያርቁ፤ እኔም ለዘለዓለም በመካከላቸው አድራለሁ።'),
  ('fe6fcc48-41b3-5ac2-a732-90ff9070fbdc', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 10, 10, '“አንተም የሰው ልጅ ሆይ፥ ሥራቸውንና ኀጢአታቸውን ይተዉ ዘንድ ለእስራኤል ቤት ይህን ቤት አሳያቸው፤ አምሳያውንም ይለኩ።'),
  ('4f95874e-63fc-5586-a6c7-b77243593064', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 11, 11, 'እነርሱም ስለ ሠሩት ሥራ ሁሉ መቅሠፍታቸውን ያገኛሉ፤ አንተም የቤቱን መልክና ምሳሌውን፥ መውጫውንም፥ መግቢያውንም፥ ሥርዐቱንም፥ ሕጉንም ሁሉ አስታውቃቸው፤ ሥርዐቱንና ሕጉን ሁሉ ይጠብቁ ዘንድ፥ ያደርጉትም ዘንድ በፊታቸው ጻፈው።'),
  ('62492ab5-32b6-5743-a8e8-bca500a87878', '2215787d-1d52-5ca7-a777-36246575ae3e', 'b8887702-ef0a-5bf9-a3aa-634f022c07d9', 12, 12, 'በተራራው ራስ ላይ ያለውን ቤቱንና የቤቱን ሥርዐት ሣል፤ የዙሪያውም ዳርቻ ሁሉ ቅዱሰ ቅዱሳን ነው። እነሆ የቤቱ ሕግ ይህ ነው።”'),
  ('3dfeb3f4-6768-5869-a812-cc6a815d3001', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 1, 13, 'የመሠዊያው ልክ በክንድ ይህ ነው፤ ክንዱም ክንድ ተጋት ነው። የመሠረቱም ቁመቱ አንድ ክንድ፥ ወርዱም አንድ ክንድ ነው፤ አንድ ስንዝርም ክፈፍ ዳር ዳሩን በዙሪያው አለ፤ የመሠዊያው ቁመት እንዲሁ ነው።'),
  ('23fffdc7-79f3-5161-a2f0-2c4cd011ca5c', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 2, 14, 'በመሬቱም ላይ ከአለው መሠረት ጀምሮ እስከ ታችኛው እርከን ድረስ ሁለት ክንድ፥ ወርዱም አንድ ክንድ ነው፤ ከትንሹም እርከን ጀምሮ እስከ ትልቁ እርከን ድረስ አራት ክንድ፥ ወርዱም አንድ ክንድ ነው።'),
  ('617b72bb-a701-5236-a7af-2d3040423e7b', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 3, 15, 'ምድጃውም አራት ክንድ ነው፤ በምድጃውም ላይ አንድ ክንድ ወደ ላይ ከፍ የሚሉ አራት ቀንዶች አሉበት።'),
  ('49f6fe7b-ebbc-5d69-ac71-3638bd4c9780', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 4, 16, 'የምድጃውም ርዝመት ዐሥራ ሁለት ክንድ፥ ወርዱም ዐሥራ ሁለት ክንድ ነው፥ አራቱም ማዕዘን ትክክል ነው።'),
  ('a3d62096-ca87-53b4-a264-2d6f7b46886a', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 5, 17, 'የእርከኑም ርዝመት ዐሥራ አራት ክንድ፥ ወርዱም ዐሥራ አራት ክንድ ነው፤ አራቱም መዐዝን ትክክል ነው፤ በዙሪያውም ያለው ክፈፍ የክንድ እኩሌታ ነው፤ መሠረቱም በዙሪያው አንድ ክንድ ነው፤ ደረጃዎቹም ወደ ምሥራቅ ይመለከታሉ።”'),
  ('66c71e29-65d6-5327-a596-8ad11e2ea7b4', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 6, 18, 'እንዲህም አለኝ፥ “የሰው ልጅ ሆይ! ጌታ እግዚአብሔር እንዲህ ይላል፦ የሚቃጠለውን መሥዋዕት ያቀርቡበት ዘንድ፥ ደሙንም ይረጩበት ዘንድ በሚሠሩበት ቀን የመሠዊያው ሕግ ይህ ነው።'),
  ('2a5be096-ac22-54c9-a149-2dc1683ff534', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 7, 19, 'ያገለግሉኝ ዘንድ ወደ እኔ ለሚቀርቡ ከሳዶቅ ዘር ለሚሆኑ ለሌዋውያኑ ካህናት ለኀጢአት መሥዋዕት የሚሆነውን ከመንጋው አንድ ወይፈን ትሰጣቸዋለህ፥ ይላል ጌታ እግዚአብሔር።'),
  ('41b18861-195c-53ed-a5ce-d817b8ff8b73', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 8, 20, 'ከደሙም ትወስዳለህ፤ በአራቱ የመሠዊያ ቀንዶቹም፥ በእርከኑም በአራቱ ማዕዘን ላይ፥ በዙሪያውም በአለው ክፈፍ ላይ ትረጨዋለህ፤ እንዲሁ ታነጻዋለህ፤ ታስተሰርይለትማለህ።'),
  ('9ff25b0b-9b73-5403-a3ee-a07ae1e3234f', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 9, 21, 'ለኀጢአትም መሥዋዕት የሚሆነውን ወይፈን ትወስዳለህ፤ በመቅደሱም ውጭ በቤቱ በተለየው ስፍራ ይቃጠላል።'),
  ('c63906b0-6b65-5756-a5d4-e5698c60f4fc', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 10, 22, 'በሁለተኛውም ቀን ለኀጢአት መሥዋዕት የሚሆነውን ነውር የሌለበትን አውራ ፍየል ታቀርባለህ፤ በወይፈኑም እንዳነጹት እንዲሁ መሠዊያውን ያነጹበታል።'),
  ('065c683b-1c73-57e8-abbf-54d18dd32b83', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 11, 23, 'ማንጻቱንም ከፈጸምህ በኋላ ነውር የሌለበትን ወይፈን፥ ከበጎችም ነውር የሌለበትን ጠቦት በግ ታቀርባለህ፤'),
  ('5aa59f70-2ac2-5cf9-a588-a228e7d5e10c', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 12, 24, 'በእግዚአብሔርም ፊት ታቀርባቸዋለህ፤ ካህናቱም ጨው ይጨምሩባቸዋል፤ የሚቃጠለውንም መሥዋዕት አድርገው ለእግዚአብሔር ያቀርቡአቸዋል።'),
  ('36d8d1b4-2b92-5e98-ac70-e68618638789', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 13, 25, 'ሰባት ቀንም በየዕለቱ ለኀጢአት መሥዋዕት የሚሆነውን አውራ ፍየል ታቀርባለህ፤ ነውርም የሌለባቸውን አንድ ወይፈንና ከበጎችም አንድ ጠቦት በግ ያቀርባሉ።'),
  ('0084c080-c5cd-5b4d-a1fe-b2e5e54af587', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 14, 26, 'ሰባት ቀን ለመሠዊያው ያስተሠርያሉ፤ ያነጹታል፤ ይቀድሱትማል።'),
  ('5a6960fc-7d72-5485-a896-172cdb8f23a8', '2215787d-1d52-5ca7-a777-36246575ae3e', 'cc206724-6bf5-5fcf-af45-88a1115b6fa5', 15, 27, 'ቀኖቹንም በፈጸሙ ጊዜ በስምንተኛው ቀን ከዚያም በኋላ ካህናቱ የሚቃጠለውን መሥዋዕታችሁን፥ የደኅንነት መሥዋዕታችሁንም በመሠዊያው ላይ ያደርጋሉ፤ እኔም እቀበላችኋለሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('342ef030-f72e-5d30-a9b5-c820b2390766', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 1, 1, 'ወደ ምሥራቅም ወደሚመለከተው በስተ ውጭ ወደ አለው ወደ መቅደሱ በር መለሰኝ፤ ተዘግቶም ነበር።'),
  ('8763717d-d9d9-5594-ac98-58a9455e3aaa', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 2, 2, 'እግዚአብሔርም እንዲህ አለኝ፥ “ይህች በር ተዘግታ ትኖራለች እንጂ አትከፈትም፤ ሰውም አይገባባትም፤ የእስራኤል አምላክ እግዚአብሔር ገብቶባታልና ተዘግታ ትኖራለች።'),
  ('398b8207-4646-5f45-af8c-72984595312b', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 3, 3, 'አለቃው ግን እርሱ በእግዚአብሔር ፊት እንጀራ ይበላ ዘንድ ይቀመጥባታል፤ በበሩ ይገባል፤ በዚያም መንገድ ይወጣል።”'),
  ('1968e43e-00fd-5973-acac-59e645298e58', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 4, 4, 'በሰሜኑም በር መንገድ በቤቱ ፊት አገባኝ፤ እኔም አየሁ እነሆም የእግዚአብሔር ክብር የእግዚአብሔርን ቤት መልቶት ነበር፤ እኔም በግምባሬ ተደፋሁ።'),
  ('16b24cf1-4c32-54d2-ad10-593a02c896d7', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 5, 5, 'እግዚአብሔርም እንዲህ አለኝ፥ “የሰው ልጅ ሆይ! ልብ አድርግ፤ ስለ እግዚአብሔርም ቤት ሥርዐትና ሕግ ሁሉ የምነግርህን ሁሉ በዐይንህ ተመልከት፤ በጆሮህም ስማ፤ የቤቱንም መግቢያ፥ የመቅደሱንም መውጫ ሁሉ ልብ አድርግ።'),
  ('d3e9432c-c982-5eaa-a263-bd19f57ad5ed', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 6, 6, 'ለዐመፀኛው ለእስራኤል ቤት እንዲህ በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ እናንተ የእስራኤል ቤት ሆይ! ርኵሰታችሁ ሁሉ ይብቃችሁ።'),
  ('ed9887c0-b298-5ddd-ae9d-b489bef335f8', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 7, 7, 'እንጀራዬን፥ ስብንና ደምን በምታቀርቡበት ጊዜ በመቅደሴ ውስጥ ይሆኑ ዘንድ ቤቴንም ያረክሱ ዘንድ፥ በልባቸውና በሥጋቸው ያልተገረዙትን እንግዶችን ሰዎች አግብታችኋልና፥ በርኵሰታችሁም ሁሉ ቃል ኪዳኔን አፍርሳችኋልና።'),
  ('0df9ce14-aa56-5ac1-ad82-921f4d54e3e6', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 8, 8, 'የመቅደሴን ሥርዐት አልጠበቃችሁም፤ ነገር ግን የመቅደሴን ሥርዐት የሚጠብቁ ሌሎችን ለራሳችሁ ሾማችሁ።”'),
  ('57c9940f-9d48-5e23-ab78-7b9fbd5ac100', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 9, 9, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “በእስራኤል ልጆች መካከል ከአሉት ሁሉ በልቡና በሥጋው ያልተገረዘ የባዕድ ልጅ እንግዳ ሁሉ ወደ መቅደሴ አይግባ።'),
  ('bc49ef4e-78b9-5942-a65a-6a3ac570b71f', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 10, 10, 'ከእኔ ዘንድ የራቁ፥ እስራኤልም በሳቱ ጊዜ ጣዖታቸውን ተከትለው ከእኔ ዘንድ የሳቱ ሌዋውያን ሳይቀር ኀጢአታቸውን ይሸከማሉ።'),
  ('156be14e-0043-5765-a4d5-8a43a19d4a32', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 11, 11, 'ነገር ግን በመቅደሴ ውስጥ አገልጋዮች ይሆናሉ፤ በቤቱም በሮች በረኞች ይሆናሉ፤ በቤቱም ውስጥ ያገለግላሉ፤ ለሕዝቡም የሚቃጠለውን መሥዋዕትና ሌላ መሥዋዕትን ይሠዋሉ፤ ያገለግሉአቸውም ዘንድ በፊታቸው ይቆማሉ።'),
  ('8236c33e-c160-5fac-a2c2-e01f2a0cb53d', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 12, 12, 'በጣዖቶቻቸውም ፊት አገልግለዋቸው ነበሩና፥ ለእስራኤልም ቤት የኀጢአት እንቅፋት ሆነዋልና ስለዚህ እጄን በላያቸው አንሥቻለሁ፤ ኀጢአታቸውንም ይሸከማሉ፥ ይላል ጌታ እግዚአብሔር።'),
  ('eb82851e-939c-55e1-ac2b-ba7fb714dcf3', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 13, 13, 'እኔንም በክህነት ለማገልገል ወደ እኔ አይቀርቡም፤ ወደ ተቀደሰውም ነገሬና ወደ ቅድስተ ቅዱሳን ነገር አይቀርቡም፤ እፍረታቸውንና የሠሩትንም ርኵሰታቸውን ይሸከማሉ።'),
  ('32a212d6-421c-585a-a941-bcf06d8f0892', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 14, 14, 'ነገር ግን ለአገልግሎቱ ሁሉና በእርሱ ውስጥ ለሚደረገው ሁሉ የቤቱን ሥርዐት ጠባቂዎች አደርጋቸዋለሁ።'),
  ('75b06150-d30a-5996-a089-07cd9bdcea33', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 15, 15, '“ነገር ግን የእስራኤል ልጆች ከእኔ ዘንድ በሳቱ ጊዜ የመቅደሴን ሥርዐት የጠበቁ የሳዶቅ ልጆች ሌዋውያን ካህናት ያገለግሉኝ ዘንድ ወደ እኔ ይቀርባሉ፤ ስቡንና ደሙንም ወደ እኔ ያቀርቡ ዘንድ በፊቴ ይቆማሉ፥ ይላል ጌታ እግዚአብሔር።'),
  ('9a671661-e434-5bb2-a66f-b02c04d0fb94', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 16, 16, 'ወደ መቅደሴም ይገባሉ፤ ያገለግሉኝም ዘንድ ወደ ገበታዬ ይቀርባሉ፤ ሥርዐቴንም ይጠብቃሉ።'),
  ('7bf0710f-1383-5cf9-a48a-810564d1bb04', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 17, 17, 'ወደ ውስጠኛውም አደባባይ በር በገቡ ጊዜ የተልባ እግር ልብስ ይልበሱ፤ በውስጠኛውም አደባባይ በርና በቤቱ ውስጥ በአገለገሉ ጊዜ ከበግ ጠጕር አንዳች ነገር በላያቸው አይሁን።'),
  ('2c0b46a7-7465-57b7-ae9a-e1b1b3f8af66', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 18, 18, 'በራሳቸው ላይ የተልባ እግር መጠምጠሚያ ይሁን፤ በወገባቸውም ላይ የተልባ እግር ሱሪ ይሁን፤ የሚያልብ ነገር አይታጠቁ።'),
  ('45dfa591-71cc-5454-aba9-4b84c23974fb', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 19, 19, 'ወደ ውጭውም አደባባይ ወደ ሕዝብ በወጡ ጊዜ ያገለገሉበትን ልብሳቸውን ያውልቁ፤ በተቀደሰውም ዕቃ ቤት ውስጥ ያኑሩት፤ ሕዝቡንም በልብሳቸው እንዳይቀድሱ ሌላውን ልብስ ይልበሱ።'),
  ('0a603c04-b7bd-59f4-aa23-f25392e112c9', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 20, 20, 'ራሳቸውንም አይላጩ፥ የራሳቸውንም ጠጕር ይከርከሙ እንጂ ጠጕራቸውን አያሳድጉ።'),
  ('20b03652-a0fd-502e-adc0-f66cae80654c', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 21, 21, 'ካህናቱም ሁሉ በውስጠኛው አደባባይ ሲገቡ የወይን ጠጅ አይጠጡ።'),
  ('fab062da-e63d-5c22-a3bb-0539794d83b5', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 22, 22, 'መበለቲቱንና የተፈታችይቱን አያግቡ፤ ከእስራኤል ቤት ዘር ግን ድንግሊቱን ወይም የካህን ሚስት የነበረችይቱን መበለት ያግቡ።'),
  ('a889fb85-fd52-5c07-a042-4ac758697d94', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 23, 23, 'በተቀደሰውና ባልተቀደሰው መካከል ይለዩ ዘንድ ሕዝቤን ያስተምሩ፤ ንጹሕና ንጹሕ ባልሆነው መካከል ይለዩ ዘንድ ያሳዩአቸው።'),
  ('b79c3d02-3c9f-5c93-ac61-adaf1eb3778e', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 24, 24, 'ክርክርም በሆነ ጊዜ ለመፍረድ ይቁሙ፤ እንደ ፍርዴ ይፍረዱ፤ በበዓላቴ ሁሉ ሕጌንና ሥርዐቴን ይጠብቁ፤ ሰንበታቴንም ይቀድሱ።'),
  ('92dbc629-031c-5f72-a2ea-bcf514a5c1f1', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 25, 25, 'እንዳይረክሱም ወደ ሞተ ሰው አይግቡ፤ ነገር ግን ለአባት፥ ወይም ለእናት፥ ወይም ለወንድ ልጅ፥ ወይም ለሴት ልጅ፥ ወይም ለወንድም፥ ወይም ላልተዳረች እኅት ይርከሱ።'),
  ('ce3d00ae-e2f6-56f7-a9e3-dd6f48dd0c00', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 26, 26, 'ከነጻም በኋላ ሰባት ቀን ይቍጠሩለት።'),
  ('a1969829-f950-52b2-a7b3-0eb7ed9cda31', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 27, 27, 'በመቅደስም ውስጥ ያገለግል ዘንድ ወደ ውስጠኛው አደባባይ ወደ መቅደሱ በሚገባበት ቀን የኀጢአትን መሥዋዕት ያቅርብ፥” ይላል ጌታ እግዚአብሔር።'),
  ('4b86dcc4-1221-56f8-a134-1779574d81de', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 28, 28, '“ርስት አይሆንላቸውም፤ እኔ ርስታቸው ነኝ፤ በእስራኤልም ልጆች ዘንድ ርስት አትስጡአቸው፤ እኔ ርስታቸው ነኝ፤'),
  ('490a510c-a662-5960-a930-59023c78d74c', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 29, 29, 'የእህሉን ቍርባንና የኀጢአትን መሥዋዕት የንስሓንም መሥዋዕት ይበላሉ፤ በእስራኤልም ዘንድ እርም የሆነው ነገር ሁሉ ለእነርሱ ይሆናል።'),
  ('51b0c529-85f9-5b33-a271-17145352a288', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 30, 30, 'የበኵራቱ ሁሉ መጀመሪያ ከየዓይነቱ፥ ከቍርባናችሁም ሁሉ የማንሣት ቍርባን ሁሉ ለካህናት ይሆናል፤ በቤታችሁም ውስጥ በረከት ያድር ዘንድ የአዝመራችሁን ቀዳምያት ለካህናቱ ትሰጣላችሁ።'),
  ('32473f9d-6837-5e4c-a629-1d906e513bb9', '344a7189-42c0-556c-a3c4-844db54b6be2', '01184084-2516-56dd-af29-30595b61100e', 31, 31, 'ከዎፍም ሆነ ከእንስሳ የበከተውንና አውሬ የሰበረውን ካህናት አይብሉት።'),
  ('daca514b-2e30-564a-a9ac-9bccc26e4185', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 1, 1, '“ርስትም አድርጋችሁ ምድርን በዕጣ በምታካፍሉበት ጊዜ ከምድር የተቀደሰውን የዕጣ ክፍል መባ አድርጋችሁ ወደ እግዚአብሔር ታቀርባላችሁ። ርዝመቱ ሃያ አምስት ሺህ ክንድ፥ ወርዱም ሃያ ሺህ ክንድ ይሆናል፤ በዳርቻው ሁሉ ዙሪያው የተቀደሰ ይሆናል።'),
  ('6389fd9b-b761-50d5-a826-52cd63e675a9', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 2, 2, 'ከእርሱም ርዝመቱ አምስት መቶ፥ ወርዱም አምስት መቶ ክንድ አራት ማዕዘን የሆነ ቦታ ለመቅደሱ ይሆናል፤ በዙሪያውም ባዶ ስፍራ የሚሆን አምሳ ክንድ ይሆናል።'),
  ('3a7c80e4-5bb4-5a4e-afae-7d9a0b95fe55', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 3, 3, 'ከዚያው ልክ ደግሞ ርዝመቱ ሃያ አምስት ሺህ ክንድ፥ ወርዱም ዐሥር ሺህ ክንድ የሆነ ስፍራ ትለካለህ፤ በእርሱም ውስጥ ቅድስተ ቅዱሳን የሆነ መቅደስ ይሆናል።'),
  ('77cdb66a-18fa-5214-a39d-17df9b4e7557', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 4, 4, 'ከምድርም የተቀደሰ የዕጣ ክፍል ይሆናል፤ እግዚአብሔርን ያገለግሉ ዘንድ ለሚቀርቡ ለመቅደሱ አገልጋዮች ለካህናቱ ይሆናል፤ ለቤቶቻቸውም የሚሆን ስፍራ፥ ለመቅደስም የሚሆን የተቀደሰ ስፍራ ይሆናል።'),
  ('9d1f0d4b-bd29-55bc-a87a-561f5c191d65', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 5, 5, 'ርዝመቱም ሃያ አምስት ሺህ፥ ወርዱም ዐሥር ሺህ የሆነ ስፍራ ለቤቱ አገልጋዮች ለሌዋውያን መኖሪያ ርስት ከሃያ ዕቃ ቤቶች ጋር ይሆናል።'),
  ('ca5f247e-068d-58a2-afbb-b7d36c907547', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 6, 6, '“ለከተማዪቱም ይዞታ በተቀደሰው የዕጣ ክፍል መባ አጠገብ ወርዱ አምስት ሺህ፥ ርዝመቱም ሃያ አምስት ሺህ የሆነውን ስፍራ ታደርጋላችሁ። እርሱም ለእስራኤል ቤት ሁሉ ይሆናል።'),
  ('d4c62322-03c2-5a91-a7e0-a6b5aef46c09', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 7, 7, 'ለአለቃውም የሆነ የዕጣ ክፍል በተቀደሰው መባና በከተማዪቱ ይዞታ አጠገብ በዚህና በዚያ ይሆናል፤ በተቀደሰው መባና በከተማዪቱ ይዞታ ፊት በምዕራብ በኩል ወደ ምዕራብ፥ በምሥራቅም በኩል ወደ ምሥራቅ ይሆናል፤ ርዝመቱም እንደ አንድ ነገድ ዕጣ ክፍል ሆኖ ከምድሩ ከምዕራቡ ዳርቻ ጀምሮ እስከ ምሥራቁ ዳርቻ ድረስ ይሆናል።'),
  ('55e1b218-046b-5dea-a5db-fb72bb5f3f18', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 8, 8, 'ይህም በእስራኤል ዘንድ ይዞታ ይሆንለታል፤ የሕዝቤ አለቆችም ለእስራኤል ቤት ምድሪቱን እንደ ነገዳቸው መጠን ይሰጡአቸዋል እንጂ ሕዝቤን ከእንግዲህ ወዲህ አያስጨንቋቸውም።”'),
  ('c71444ad-21ed-5211-acf0-1f05d4fa1442', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 9, 9, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “የእስራኤል አለቆች ሆይ! ይብቃችሁ፤ ግፍንና ዐመፅን አስወግዱ፤ ፍርድንና ጽድቅንም አድርጉ፤ ቅሚያችሁን ከሕዝቤ ላይ አርቁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('5eb42c02-77d2-54d8-ac72-1359e15e6c5c', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 10, 10, 'እውነተኛ ሚዛን፥ እውነተኛም የኢፍ መስፈሪያ፥ እውነተኛም የባዶስ መስፈሪያ ይሁንላችሁ።'),
  ('7c5d8f55-968a-5e73-a2b0-bf182823e233', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 11, 11, 'እንዲሁም የኢፍና የባዶስ መስፈሪያ አንድ ይሁን፤ የባዶስ መስፈሪያ፥ የቆሮስ መስፈሪያ ዐሥረኛ ክፍል፥ የኢፍ መስፈሪያውም የቆሮስ መስፈሪያ ዐሥረኛ ክፍል ይሁን። መስፈሪያው እንደ ቆሮስ መስፈሪያ ይሁን።'),
  ('a03384e7-cfb4-593a-adfe-d5f0e255154e', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 12, 12, 'ሰቅሉም ሃያ አቦሊ ይሁን፤ ሃያ ሰቅል፥ ሃያ አምስት ሰቅል፥ ዐሥራ አምስት ሰቅል፥ ምናን ይሁንላችሁ።'),
  ('ef62a7dc-6694-5bd1-a741-b1dc3f70ab71', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 13, 13, '“የምታቀርቡት መባ ይህ ነው፤ ከአንድ ቆሮስ መስፈሪያ ስንዴ አንድ ስድስተኛ የኢፍ መስፈሪያ፥ ከአንድም ቆሮስ መስፈሪያ ገብስ አንድ ስድስተኛ የኢፍ መስፈሪያ ትሰጣላችሁ።'),
  ('5eb875c1-fa7e-554f-a2fa-cfbf371d1c4b', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 14, 14, 'የዘይቱም ደንብ፥ ከእያንዳንዱ የቆሮስ መስፈሪያ የባዶስን ዐሥረኛ ክፍል ትሰጣላችሁ፤ ዐሥር የባዶስ መስፈሪያ አንድ የቆሮስ መስፈሪያ ነውና።'),
  ('a0959e03-fde5-57f6-ad02-9598a23b1500', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 15, 15, 'ከእስራኤል ማሰማርያ ከመንጋው ከሁለት መቶው አንዱን የበግ ጠቦት ትሰጣላችሁ፤ ይህ ኀጢአታችሁን ያስተሰርይላችሁ ዘንድ ለእህል ቍርባንና ለሚቃጠል መሥዋዕት፥ ለደኅንነትም መሥዋዕት ይሆናል” ይላል ጌታ እግዚአብሔር።'),
  ('9ed3bcae-8d34-5453-a0e1-70c85e20d9a7', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 16, 16, 'የሀገሩም ሕዝብ ሁሉ ይህን መባ ለእስራኤል አለቃ ይሰጣሉ።'),
  ('181946db-8d55-555d-a042-c0117d9c8253', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 17, 17, 'በየበዓላቱም፥ በየመባቻውም፥ በየሰንበታቱም በእስራኤልም ቤት ዓመት በዓል ሁሉ የሚቃጠለውን መሥዋዕትና የእህሉን ቍርባን፥ የመጠጡንም ቍርባን መስጠት በአለቃው ላይ ይሆናል፤ እርሱ ለእስራኤል ቤት ያስተሰርይ ዘንድ የኀጢአቱን መሥዋዕትና የእህሉን ቍርባን፥ የሚቃጠለውን መሥዋዕትና የደኅንነቱን መሥዋዕት ያቀርባል።”'),
  ('62ddcca3-5b36-5472-abf1-9fc2ac25d502', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 18, 18, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “በመጀመሪያው ወር ከወሩም በመጀመሪያው ቀን ከመንጋው ነውር የሌለበትን ወይፈን ውሰድ፤ መቅደሱንም አንጻ።'),
  ('2f176486-9fd2-5387-a271-dd6f734d4169', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 19, 19, 'ካህኑም ከኀጢአቱ መሥዋዕት ደም ወስዶ በመቅደሱ መቃኖችና በመሠዊያው እርከን በአራቱ ማዕዘን፥ በውስጠኛውም አደባባይ በበሩ መቃኖች ላይ ይርጨው።'),
  ('53f07b1b-f7d1-5d3b-ab74-95bdd5aa458f', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 20, 20, 'ከወሩም በሰባተኛው ቀን እንዲሁ አድርግ፤ ይኸውም ስለ ሳተውና ስለ በደለው ሁሉ ነው። እንዲሁ ስለ ቤቱ አስተስርዩ።'),
  ('cc64c140-d24b-5e6d-a5fa-1bf1f484878d', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 21, 21, '“በመጀመሪያው ወር ከወሩም በዐሥራ አራተኛው ቀን የፋሲካን በዓል ታደርጋላችሁ። እስከ ሰባት ቀንም ድረስ ቂጣ ትበላላችሁ።'),
  ('dae9f98b-b41c-5956-a1fe-50add8bca9fd', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 22, 22, 'በዚያም ቀን አለቃው ለራሱና ለሀገሩ ሕዝብ ሁሉ የኀጢአት መሥዋዕት የሚሆነውን ወይፈን ያቅርብ።'),
  ('023468ab-5396-5635-a6ae-c5ff510820ff', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 23, 23, 'በበዓሉም በሰባቱ ቀኖች የሚቃጠለውን መሥዋዕት ለእግዚአብሔር ያቅርብ፤ ሰባቱን ቀኖች በየዕለቱ ነውር የሌለባቸውን ሰባት ወይፈንና ሰባት አውራ በጎች ያቅርብ፤ ለኀጢአትም መሥዋዕት በየዕለቱ ከፍየሎች አንድ አውራ ፍየል ያቅርብ።'),
  ('22dd6e52-7b41-5f78-a4f7-39ff08b76264', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 24, 24, 'ለአንድም ወይፈን አንድ የኢፍ መስፈሪያ፥ ለአንድም አውራ በግ አንድ የኢፍ መስፈሪያ፥ ለአንድም የኢፍ መስፈሪያ አንድ የኢን መስፈሪያ ዘይት ለእህል ቍርባን ያቅርብ።'),
  ('c49db583-6b48-5c38-a28b-446232bed68e', '2b12a3e9-4aab-5d5f-aa96-178320407293', 'ce47c562-a1ab-52ae-a153-7a3e8e35e7f5', 25, 25, 'በሰባተኛውም ወር ከወሩም በዐሥራ አምስተኛው ቀን በበዓሉ ሰባት ቀኖች፥ የኃጢአቱን መሥዋዕት፥ የሚቃጠለውንም መሥዋዕት፥ የእህሉንም ቍርባን ከዘይቱ ጋር እንዲሁ ያቅርብ።”'),
  ('d584d642-5a3b-5969-abb5-1d813e01e059', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 1, 1, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “በውስጠኛው አደባባይ ወደ ምሥራቅ የሚመለከተው በር ሥራ በሚሠራበት በስድስቱ ቀን ተዘግቶ ይቈይ፤ ነገር ግን በሰንበት ቀን ይከፈት፤ በመባቻ ቀንም ይከፈት።'),
  ('7f975f30-ed86-5405-a7d0-9efa12812f7d', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 2, 2, 'አለቃው በስተ ውጭ ባለው በር በደጀ ሰላሙ መንገድ ገብቶ በበሩ መቃን አጠገብ ይቁም፤ ካህናቱም የእርሱን የሚቃጠለውን መሥዋዕትና የደኅንነቱን መሥዋዕት ያቅርቡ፥ እርሱም በበሩ መድረክ ላይ ይስገድ፤ ከዚያም በኋላ ይውጣ፤ በሩ ግን እስከ ማታ ድረስ አይዘጋ።'),
  ('95f5e694-20b7-53de-a659-1b06f0582328', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 3, 3, 'የሀገርም ሕዝብ በዚያ በር መግቢያ በእግዚአብሔር ፊት በሰንበታትና በመባቻ ይስገዱ።'),
  ('5c4d903f-1de9-5b63-ae16-2c605c1d6d34', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 4, 4, 'አለቃውም በሰንበት ቀን ለእግዚአብሔር የሚያቀርበው የሚቃጠል መሥዋዕት ነውር የሌለባቸው ስድስት የበግ ጠቦቶች፥ ነውርም የሌለበት አንድ አውራ በግ ይሁን፤'),
  ('2438de2d-49b9-5403-a497-1f566541ce32', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 5, 5, 'የእህሉም ቍርባን ለአውራ በጉ አንድ የኢፍ መስፈሪያ ይሁን፤ ለጠቦቶቹም የእህል ቍርባን እጁ እንደ ቻለ ያህል ይሁን፥ ለአንዱም የኢፍ መስፈሪያ አንድ የኢን መስፈሪያ ዘይት ያቅርብ።'),
  ('799e449e-d233-5ca5-a30d-6c4175abb895', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 6, 6, 'በመባቻም ቀን ነውር የሌለበትን አንድ ወይፈን፥ ነውር የሌለባቸውንም ስድስት ጠቦቶችና አንድ አውራ በግ ያቅርብ፤'),
  ('5389efef-2975-53c3-af41-317bd40b07f7', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 7, 7, 'ለወይፈኑም አንድ የኢፍ መስፈሪያ፥ ለአውራውም በግ አንድ የኢፍ መስፈሪያ፥ ለጠቦቶቹም እጁ እንደ ቻለው ያህል፥ ለአንዱም የኢፍ መስፈሪያ አንድ የኢን መስፈሪያ ዘይት ለእህሉ ቍርባን ያቅርብ።'),
  ('9db6ae02-b806-5810-a379-8a57e389cb54', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 8, 8, 'አለቃውም በሚገባበት ጊዜ በበሩ ደጀ ሰላም መንገድ ይግባ፤ በዚያውም ይውጣ።'),
  ('7b3c1a6a-1399-53c7-a9f1-f846ebf2fb10', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 9, 9, '“የሀገሩ ሕዝብ ግን በየክብረ በዓሉ ቀን ወደ እግዚአብሔር ፊት በመጡ ጊዜ በሰሜን በር በኩል ሊሰግድ የሚገባው በደቡብ በር በኩል ይውጣ፤ በደቡብም በር የሚገባው በሰሜን በር በኩል ይውጣ፤ በፊት ለፊት ይውጣ እንጂ በገባበት በር አይመለስ።'),
  ('38ff8516-2e48-56db-a6bf-9bc1af4bf296', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 10, 10, 'ሕዝቡ በሚገቡበት ጊዜ አለቃው በመካከላቸው ይግባ፤ በሚወጡበትም ጊዜ ይውጣ።'),
  ('f7153db1-0e59-54a2-a81b-dc2266265b62', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 11, 11, 'በበዓላትና በክብረ በዓል ቀኖች የእህሉ ቍርባን ለወይፈኑ አንድ የኢፍ መስፈሪያ፥ ለአውራ በጉ አንድ የኢፍ መስፈሪያ፥ ለጠቦቶቹም እጁ እንደሚችለው ያህል፥ ለአንድ የኢፍ መስፈሪያ ዱቄት አንድ የኢን መስፈሪያ ዘይት ይሆናል።'),
  ('49298379-2744-5e66-ac24-812f518d849b', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 12, 12, 'አለቃውም በፈቃዱ የሚያቀርበውን መሥዋዕት፥ የሚቃጠለውን መሥዋዕት፥ ወይም በፈቃዱ ለእግዚአብሔር የሚያቀርበውን የደኅንነቱን መሥዋዕት በአቀረበ ጊዜ፥ ወደ ምሥራቅ የሚመለከተው በር ይከፈትለት፤ በሰንበትም ቀን እንደሚያደርግ የሚቃጠለውን መሥዋዕትና የደኅንነቱን መሥዋዕት ያቅርብ፤ ከዚያም በኋላ ይውጣ፤ ከወጣም በኋላ በሩ ይዘጋ።'),
  ('b0ea7a3b-7944-5ae5-a2d5-82cbf75bf0d2', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 13, 13, '“በየዕለቱም ለሚቃጠል መሥዋዕት ነውር የሌለበትን የአንድ ዓመት የበግ ጠቦት ለእግዚአብሔር ታቀርባለህ፤ በየማለዳው ታቀርበዋለህ።'),
  ('ead98cc9-9b30-5197-acb4-6dc641b2a6b1', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 14, 14, 'ከእርሱም ጋር የእህልን ቍርባን፥ በኢን መስፈሪያ ሢሶ ዘይት የተለወሰ የኢፍ መስፈሪያ ስድስተኛ እጅ የስንዴ ዱቄትን፤ በየማለዳው ታቀርባለህ፤ ይህ የሚደረግ ዘለዓለማዊ ሥርዐት ነው።'),
  ('15f4d3eb-fe6f-5f25-a5dc-4270424048b8', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 15, 15, 'እንዲሁ ዘወትር ለሚቃጠለው መሥዋዕት ጠቦቱንና የእህሉን ቍርባን ዘይቱንም በየማለዳው ያቀርባሉ።”'),
  ('42c4c53e-f636-58a9-a4c7-4cc2f96886fa', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 16, 16, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “አለቃው ከልጆቹ ለአንዱ ከርስቱ ስጦታ ቢሰጥ ለልጆቹ ይሁን፤ የርስት ይዞታ ይሆንላቸዋል።'),
  ('a9862e13-7b07-5ead-a374-aab1d102377b', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 17, 17, 'ነገር ግን ከአገልጋዮቹ ለአንዱ ከርስቱ ስጦታ ቢሰጥ እስከ ነፃነት ዓመት ድረስ ለእርሱ ይሁን፥ ከዚያም በኋላ ለአለቃው ይመለስ፤ ርስቱ ግን ለልጆቹ ይሁን።'),
  ('ce492c9f-9df9-56b6-a021-006d3dd79411', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 18, 18, 'አለቃውም ሕዝቡን ከይዞታቸው ያወጣቸው ዘንድ ከርስታቸው በግድ አይወሰድ፤ ሕዝቤ ሁሉ ከየይዞታቸው እንዳይነቀሉ ከገዛ ይዞታው ለልጆቹ ርስትን ይስጥ።”'),
  ('4052f416-018f-550e-a522-6ac85121e212', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 19, 19, 'በበሩም አጠገብ በአለው መግቢያ ወደ ሰሜን ወደሚመለከተው ለካህናት ወደሚሆን ወደ ተቀደሰው ዕቃ ቤት አገባኝ፤ እነሆም በኋላው በባሕር በኩል አንድ ስፍራ ነበረ።'),
  ('344c4f32-8169-54af-a019-745a523a1f9c', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 20, 20, 'እርሱም እንዲህ አለኝ፥ “ካህናቱ ሕዝቡን ለመቀደስ ወደ ውጭው አደባባይ እንዳይወጡ የበደሉን መሥዋዕትና የኀጢአቱን መሥዋዕት የሚያበስሉበት፥ የእህሉንም ቍርባን የሚጋግሩበት ስፍራ ይህ ነው።”'),
  ('85afe432-bc42-5f61-ab7f-35c2628f8ad6', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 21, 21, 'በውጭው አደባባይ አወጣኝ፤ በአደባባይም ወዳለው ወደ አራቱ ማዕዘን አዞረኝ፤ እነሆም፥ በአደባባዩ ማዕዘን ሁሉ አደባባይ ነበረ።'),
  ('d432895a-41b3-5b69-af67-422f4ad959ea', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 22, 22, 'በአደባባዩ በአራቱ ማዕዘን ርዝመቱ አርባ ክንድ፥ ወርዱም ሠላሳ ክንድ የሆነ የታጠረ አደባባይ ነበረ፤ በማዕዘኑ ላሉ ለእነዚህ ለአራቱ ስፍራዎች አንድ ልክ ነበራቸው።'),
  ('eb039409-d4e2-5ed6-a9da-a64b0c07ef6c', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 23, 23, 'በአራቱም ዙሪያ ሁሉ ግንብ ነበረ፥ በግንቡም ሥር በዙሪያው የመቀቀያ ቦታ ነበረ።'),
  ('a47331d5-4fd0-5164-aa84-2861b5a3f653', '748c58ad-b7bd-5fc6-aa56-0d14331cf57f', 'dab02c4e-e3db-500d-aec1-a88fa1ee56ab', 24, 24, 'እርሱም፥ “እነዚህ የቤቱ አገልጋዮች የሕዝቡን መሥዋዕት የሚያበስሉባቸው ስፍራዎች ናቸው” አለኝ።'),
  ('f604887b-57c3-503c-a4be-3c875280da15', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 1, 1, 'ወደ መቅደሱም መዝጊያ መለሰኝ፤ እነሆም ውኃ ከቤቱ መድረክ በታች ወደ ምሥራቅ ይወጣ ነበር፤ የቤቱ ፊት ወደ ምሥራቅ ይመለከት ነበርና፤ ውኃውም ከቤቱ ከቀኝ ወገን በታች በመሠዊያው በደቡብ በኩል ይወርድ ነበር።'),
  ('36951841-c96c-574f-a87d-2b701e59fb67', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 2, 2, 'በሰሜኑም በር በኩል አወጣኝ፤ በስተ ውጭ በአለው መንገድ፥ ወደ ምሥራቅ ወደሚመለከት በስተ ውጭ ወዳለው በር አዞረኝ፤ እነሆም ውኃው በቀኝ በኩል ይፈስስ ነበር።'),
  ('25288d6f-c857-5ccf-ad23-b5292fcf416e', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 3, 3, 'ሰውዮውም የመለኪያ ገመድ በእጁ ይዞ ወደ ምሥራቅ ወጣ፤ አንድ ሺህም ክንድ ለካ፤ በውኃውም ውስጥ አሻገረኝ፤ ውኃውም እስከ ቍርጭምጭሚት ደረሰ።'),
  ('3021efff-66ca-50a0-a0ce-89c110682bf4', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 4, 4, 'ደግሞ አንድ ሺህ ለካ፤ በውኃውም ውስጥ አሻገረኝ፤ ውኃውም እስከ ጉልበት ደረሰ፤ ደግሞም አንድ ሺህ ለካ፤ በውኃውም ውስጥ አሻገረኝ፤ ውኃውም እስከ ወገብ ደረሰ።'),
  ('478d6dc3-7b8f-5806-a84b-42115a77c69c', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 5, 5, 'ደግሞ አንድ ሺህ ለካ ልሻገረውም የማልችለው ወንዝ ሆነ፤ ውኃውም ጥልቅ ነበረ፤ የሚዋኝበትም ውኃ ነበረ፤ ሰው ሊሻገረው የማይችለው ወንዝ ነበረ።'),
  ('1e29a60c-8b38-5abd-a46c-72e67c14deef', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 6, 6, 'እርሱም፥ “የሰው ልጅ ሆይ! አይተሃልን?” አለኝ። አመጣኝም፤ ወደ ወንዙም ዳር መለሰኝ።'),
  ('917402a7-bf03-5d5a-a90c-1c4540a6a671', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 7, 7, 'በተመለስሁም ጊዜ፥ እነሆ በወንዙ ዳር በዚህና በዚያ እጅግ ብዙ ዛፎች ነበሩ።'),
  ('61e7a2e8-a847-52ac-a014-b83cc081831b', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 8, 8, 'እርሱም እንዲህ አለኝ፥ “ይህ ውኃ ወደ ምሥራቅ ወደ ገሊላ ይወጣል፤ ወደ ዓረባም ይወርዳል፤ ወደ ባሕሩም ይገባል፤ ወደ ባሕሩም ወደ ረከሰው ውኃ በገባ ጊዜ ውኃውን ይፈውሰዋል።'),
  ('9dc142d6-09dc-5e81-a502-644bbff17253', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 9, 9, 'ሕያው ነፍስ ያለው ተንቀሳቃሽ ሁሉ ወንዙ በሚገባበት ስፍራ ሁሉ በሕይወት ይኖራል፤ ይህም ውኃ በዚያ ስለ ደረሰ ዓሣዎች እጅግ ይበዛሉ፤ የባሕሩም ውኃ ይፈወሳል፤ ወንዙም በሚመጣበት ያለው ሁሉ በሕይወት ይኖራል።'),
  ('591b1690-f1ce-56a4-aa04-28bd9f4c2d4a', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 10, 10, 'ዓሣ አጥማጆችም ከዓይንጋዲ ጀምሮ እስከ ዓይንኤግላይም ድረስ በዚያ ይቆማሉ። ያም መረብ መዘርጊያ ይሆናል፤ ዓሣዎችም እንደ ታላቁ ባሕር ዓሣዎች በየወገናቸው እጅግ ይበዛሉ።'),
  ('c70c80e0-114f-5b1c-adad-61fd10941b72', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 11, 11, 'ረግረጉና ዕቋሪው ውኃ ግን ጨው እንደ ሆነ ይኖራል እንጂ አይፈወስም።'),
  ('dd88cdc8-840f-5b77-a7fc-68de24701e35', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', 'd0f644d2-506f-5c47-a537-9844a3f2aa35', 12, 12, 'በወንዙም አጠገብ በዳሩ ላይ በዚህና በዚያ ፍሬው የሚበላ ዛፍ ሁሉ ይበቅላል፤ ቅጠሉም አይረግፍም፤ ፍሬውም አይጐድልም፤ ውኃውም ከመቅደስ ይወጣልና በየወሩ ሁሉ የፍሬ በኵር ያገኛል፤ ፍሬውም ለመብል፥ ቅጠሉም ለመድኀኒት ይሆናል።”'),
  ('830fef80-d3c6-5d74-a15f-2106ef4ea71e', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 1, 13, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “ርስት አድርጋችሁ ለዐሥራ ሁለቱ የእስራኤል ነገዶች ምድሪቱን የምትከፍሉበት ድንበር ይህ ነው። ለዮሴፍ ሁለት ዕጣ ይሆናል።'),
  ('d385309a-e703-5fae-a989-3a8cc7487a26', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 2, 14, 'ለአባቶቻችሁ እሰጣቸው ዘንድ እጄን አንሥቼ ነበርና እናንተ እኩል አድርጋችሁ ተካፈሉት፤ ይህችም ምድር ርስት ትሆናችኋለች።'),
  ('36b77875-f8fc-58e9-ae27-f2cdac6e2f3f', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 3, 15, '“የምድሪቱም ድንበር ይህ ነው። በሰሜኑ ወገን ከታላቁ ባሕር ጀምሮ በሔትሎን መንገድ ወደ ጽዳድ መግቢያ፤'),
  ('4aa66354-92ec-56e0-ace9-4aa900218d13', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 4, 16, 'ሐማት፥ ቤሮታ፥ በደማስቆ ድንበርና በሐማት ድንበር መካከል ያለው ሲብራይም፥ በሐውራን ድንበር አጠገብ ያለው ሐጸርሃቲኮን።'),
  ('75b6ab5b-d38c-5207-aa70-f4710562d1ac', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 5, 17, 'ድንበሩ ከባሕሩ በደማስቆ ድንበር ላይ ያለው ሐጽርዔናን ይሆናል፥ በሰሜን በኩል የሐማት ድንበር አለ። የሰሜኑ ድንበር ይህ ነው።'),
  ('2af7b570-7436-596a-a7e5-8497b3225356', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 6, 18, 'የምሥራቁም ድንበር በሐውራን በደማስቆና በገለዓድ በእስራኤልም ምድር መካከል ዮርዳኖስ ይሆናል። ከሰሜኑ ድንበር ጀምሮ እስከ ምሥራቁ ባሕር እስከ ታማር ድረስ የምሥራቁ ድንበር ይህ ነው።'),
  ('05e19329-487c-5ead-a012-5d1b6d6e2bd6', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 7, 19, 'የደቡቡም ድንበር ከታማር ጀምሮ እስከ ሜሪባ ቃዴስ ውኃ እስከ ግብፅ ወንዝ እስከ ታላቁ ባሕር ይሆናል። የደቡቡም ድንበር ይህ ነው።'),
  ('8d610cb5-4bc5-5781-a5a7-cb2d4d0e13f3', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 8, 20, 'የምዕራቡም ድንበር ከደቡቡ ድንበር ጀምሮ እስከ ሐማት መግቢያ አንጻር ድረስ ታላቁ ባሕር ይሆናል። የምዕራቡ ድንበር ይህ ነው።'),
  ('89fc28ba-6b60-589b-a6de-c302214a5f1e', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 9, 21, '“ይህችን ምድር እናንተ ዐሥራ ሁለቱ ነገደ እስራኤል ትከፋፈላላችሁ።'),
  ('d9176f56-3a4c-5686-a5b8-bd44ea6da412', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 10, 22, 'ለእናንተና በእናንተ መካከል ለሚቀመጡ፥ በእናንተም መካከል ልጆችን ለሚወልዱ መጻተኞች ርስት አድርጋችሁ በዕጣ ትካፈሉአታላችሁ፤ እነርሱም በእስራኤል ልጆች መካከል እንደ አሉ የሀገር ልጆች ይሆኑላችኋል፤ በእስራኤልም ነገዶች መካከል ከእናንተ ጋር ርስትን ይወርሳሉ።'),
  ('f73f570e-8988-5a8d-a3f1-ded766cc2864', '5ebc311f-c3b2-5168-afd1-0376bf7708cf', '940729bb-d74a-5042-a917-d043d004072c', 11, 23, 'መጻተኛውም በማናቸውም ነገድ መካከል ቢቀመጥ በዚያ ርስትን ትሰጡታላችሁ፤ ይላል ጌታ እግዚአብሔር።'),
  ('f569c5b0-c5de-5e16-a793-0c9a8d559adc', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 1, 1, '“የነገዶችም ስም ይህ ነው። በሔትሎን መንገድ አጠገብ ወደ ሐማት መግቢያ፥ በደማስቆም ድንበር በአለው በሐጸርዔናን በሐማትም አጠገብ በሰሜን በኩል ይጀምራል። ድንበራቸውም ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ይሆናል። ለዳን አንድ የዕጣ ክፍል ይሆናል።'),
  ('425f8ef2-e5c7-593b-a403-53b775e75078', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 2, 2, 'ከዳንም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለአሴር አንድ የዕጣ ክፍል ይሆናል።'),
  ('a8433c4b-7049-5b45-a79f-7f7ec81fe02e', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 3, 3, 'ከአሴርም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለንፍታሌም አንድ የዕጣ ክፍል ይሆናል።'),
  ('c57233e3-3dfa-5b9f-a256-9c1b1596f0e7', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 4, 4, 'ከንፍታሌም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለምናሴ አንድ የዕጣ ክፍል ይሆናል።'),
  ('5c9e4e51-afe4-58c6-af2c-23dcef7035cc', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 5, 5, 'ከምናሴም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለኤፍሬም አንድ የዕጣ ክፍል ይሆናል።'),
  ('9602a700-c142-5755-a63b-775df99e8c73', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 6, 6, 'ከኤፍሬምም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለሮቤል አንድ የዕጣ ክፍል ይሆናል።'),
  ('5cb5d4ad-b3be-5fb2-a66c-40374d87bf6b', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 7, 7, 'ከሮቤልም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለይሁዳ አንድ የዕጣ ክፍል ይሆናል።'),
  ('e8ae14f3-c36e-5225-ae28-52eba69bcb11', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 8, 8, '“ከይሁዳም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለመባ የተለየ ክፍል ይሆናል፤ ወርዱ ሃያ አምስት ሺህ ክንድ ይሆናል፤ ርዝመቱም ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ከዕጣ ክፍሎች እንደ አንዱ ይሆናል፤ ቤተ መቅደሱም በመካከሉ ይሆናል።'),
  ('f9d19e03-7b58-5211-ae5f-c9ac12233920', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 9, 9, 'ለእግዚአብሔር የምትለዩት መባ ርዝመቱ ሃያ አምስት ሺህ ወርዱም ዐሥር ሺህ ክንድ ይሆናል።'),
  ('892e6d13-4a2d-545a-a3d1-afa0a705d380', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 10, 10, 'የመቅደሱም ቀዳምያት ለካህናቱ ይሆናል፤ በሰሜን በኩል ርዝመቱ ሃያ አምስት ሺህ፥ በምዕራብም በኩል ወርዱ ዐሥር ሺህ፥ በምሥራቅም በኩል ወርዱ ዐሥር ሺህ፥ በደቡብም በኩል ርዝመቱ ሃያ አምስት ሺህ ክንድ ይሆናል። የእግዚአብሔርም ቤተ መቅደስ በመካከሉ ይሆናል።'),
  ('b791b52e-de34-51f1-a214-c5a53716f34d', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 11, 11, 'የእስራኤልም ልጆች በሳቱ ጊዜ፥ ሌዋውያን እንደ ሳቱ ላልሳቱት፥ ሥርዐቴን ለጠበቁት፥ ከሳዶቅ ልጆች ወገን ለተቀደሱት ካህናት ይሆናል።'),
  ('42402699-aff9-5948-aca5-5b869c2a66c8', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 12, 12, 'ከምድርም መባ የተለየ ሌላ መባ ይሆንላቸዋል፤ ከተቀደሱትም ይልቅ የተቀደሰ ይሆናል፤ በሌዋውያን ድንበር አጠገብ ይሆናል።'),
  ('cf708d40-7384-5d8f-a426-3d9d82758633', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 13, 13, 'በካህናቱም ድንበር አቅራቢያ ርዝመቱ ሃያ አምስት ሺህ፥ ወርዱም ዐሥር ሺህ የሆነ ዕጣ ለሌዋውያን ይሆናል፤ ርዝመቱ ሁሉ ሃያ አምስት ሺህ፥ ወርዱም ሃያ ሺህ ክንድ ይሆናል።'),
  ('7b225e32-940d-5f67-a89e-4b342e5812ba', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 14, 14, 'ለእግዚአብሔርም የተቀደሰ ነውና ከእርሱ ምንም አይሸጡም፤ አይለውጡምም፤ የምድሩም ቀዳምያት አይፋለስም።'),
  ('3eef8f9a-f6a4-5a12-a34f-774f95b693b6', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 15, 15, 'በሃያ አምስቱ ሺህ አንጻር አምስት ሺህ ወርድ ያለው የቀረ ቅዱስ ያይደለ ስፍራ ለከተማዪቱ ለጋራ ጉዳይዋ፥ ለመኖሪያ፥ ለማሰማርያም ይሆናል፤ ከተማዪቱም በመካከሉ ትሆናለች።'),
  ('6c51808c-8986-5ef1-ad07-d3db121bbe12', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 16, 16, 'ልክዋም ይህ ነው፤ በሰሜን በኩል አራት ሺህ አምስት መቶ፥ በደቡብም በኩል አራት ሺህ አምስት መቶ፥ በምሥራቅም በኩል አራት ሺህ አምስት መቶ፥ በምዕራብም በኩል አራት ሺህ አምስት መቶ ክንድ ይሆናል።'),
  ('070de47e-785a-56d8-acf8-a14cf1c8128a', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 17, 17, 'ለከተማዪቱም ማሰማርያ ይኖራታል፤ በሰሜን በኩል ሁለት መቶ አምሳ፥ በደቡብም በኩል ሁለት መቶ አምሳ፥ በምሥራቅም በኩል ሁለት መቶ አምሳ፥ በምዕራብም በኩል ሁለት መቶ አምሳ ክንድ ይሆናል።'),
  ('3015c89a-579f-572d-a4be-306275f82156', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 18, 18, '“በተቀደሰው መባ አንጻር የተረፈው ርዝመቱ ወደ ምሥራቅ ዐሥር ሺህ፥ ወደ ምዕራብም ዐሥር ሺህ ክንድ ይሆናል። በተቀደሰው መባ አንጻር ይሆናል። ፍሬውም ከተማዪቱን ለሚያገለግሉ መብል ይሆናል።'),
  ('7148cb19-bfa5-5e4e-a151-1ce5ee9c45ba', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 19, 19, 'ከእስራኤል ነገድ ሁሉ ከተማዪቱን የሚያገለግሉ ያርሱታል።'),
  ('c993c291-5733-5501-a65a-ce54c1202663', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 20, 20, 'መባው ሁሉ ርዝመቱ ሃያ አምስት ሺህ፥ ወርዱም ሃያ አምስት ሺህ ክንድ ይሆናል፤ የተቀደሰውን መባ ከከተማዪቱ ይዞታ ጋር አራት ማዕዘን አድርጋችሁ ትሰጣላችሁ።'),
  ('2ef3b9c0-b4a0-5068-aed0-af68dd6b2507', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 21, 21, '“በተቀደሰው መባና በከተማዪቱ ይዞታ፥ በዚህና በዚያ ወገን የቀረው ለአለቃው ይሆናል፤ በመባው በሃያ አምስት ሺህ ፊት እስከ ምሥራቁ ድንበር፥ በምዕራብም በኩል በሃያ አምስት ሺህ ፊት እስከ ምዕራቡ ድንበር፥ እንደ ዕጣ ክፍል ሁሉ መጠን፥ ለአለቃው ይሆናል፤ የተቀደሰውም መባና ቤተ መቅደሱ በመካከሉ ይሆናል።'),
  ('5bc064ae-3687-596a-a124-2bc041da871d', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 22, 22, 'የሌዋውያን ርስት፥ የከተማዪቱም ይዞታ ለአለቃው በሆነው መካከል ይሆናል፤ በይሁዳ ድንበርና በብንያም ድንበር መካከል የአለቃው ዕጣ ክፍል ይሆናል።'),
  ('092c24f0-1f17-537e-a95f-cf8343932a94', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 23, 23, '“ለቀሩትም ነገዶች እንዲህ ይሆናል፤ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለብንያም አንድ የዕጣ ክፍል ይሆናል።'),
  ('e30bdcbe-07bb-5b2f-abcf-51b429b468e7', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 24, 24, 'ከብንያምም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለስምዖን አንድ የዕጣ ክፍል ይሆናል።'),
  ('4aebdb96-3e5b-58c7-a998-ffc6747bcbcd', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 25, 25, 'ከስምዖንም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለይሳኮር አንድ የዕጣ ክፍል ይሆናል።'),
  ('faf9962e-c3d4-5e2f-ad31-384dcb0dc368', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 26, 26, 'ከይሳኮርም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለዛብሎን አንድ የዕጣ ክፍል ይሆናል።'),
  ('c61f895b-2fe1-5d6c-ae72-6d24165e99e2', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 27, 27, 'ከዛብሎንም ድንበር ቀጥሎ ከምሥራቅ ጀምሮ እስከ ምዕራብ ድረስ ለጋድ አንድ የዕጣ ክፍል ይሆናል።'),
  ('ff2886a3-24c8-56a0-ab7f-b6ca51ef63fe', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 28, 28, 'ከጋድም ድንበር ቀጥሎ በደቡብ በኩል ድንበሩ ከታማር ጀምሮ እስከ ሜሪባ ቃዴስ ውኃ እስከ ታላቁ ባሕር ድረስ ይሆናል።'),
  ('ca8e257f-1f73-5da5-a8e5-21a76f312d97', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', '00ee36dd-8e9d-5db1-a474-4f7170857c75', 29, 29, 'ርስት አድርጋችሁ ለእስራኤል ነገዶች በዕጣ የምታካፍሉአት ምድር ይህች ናት፤ የእያንዳንዱም ዕጣ እንደዚህ ነው፥ ይላል ጌታ እግዚአብሔር።'),
  ('21cdd3f8-b7ee-5b5f-ab46-60775ef2afc7', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', 'b928f965-5d4d-50dd-aa16-9e9d64299aeb', 1, 30, '“የከተማዪቱም መውጫዎች እነዚህ ናቸው። በሰሜን ወገን ልኩ አራት ሺህ አምስት መቶ ክንድ ነው።'),
  ('0ee1a265-32f4-5df9-afa2-b375752ab715', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', 'b928f965-5d4d-50dd-aa16-9e9d64299aeb', 2, 31, 'የከተማዪቱ በሮች እንደ እስራኤል ነገዶች ስም ይሆናሉ፤ በሰሜን በኩል አንዱ የሮቤል በር፤ አንዱም የይሁዳ በር፥ አንዱም የሌዊ በር ሦስት በሮች ይሆናሉ።'),
  ('8ba2d152-c0f2-5ea6-a5a9-d47f3812fcb9', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', 'b928f965-5d4d-50dd-aa16-9e9d64299aeb', 3, 32, 'በምሥራቁም ወገን አራት ሺህ አምስት መቶ ክንድ፥ ሦስትም በሮች አሉ፤ አንዱ የዮሴፍ በር፥ አንዱም የብንያም በር፥ አንዱም የዳን በር ነው።'),
  ('dc983cbb-bfea-5815-aaf7-44b5fb7e53c1', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', 'b928f965-5d4d-50dd-aa16-9e9d64299aeb', 4, 33, 'በደቡቡም ወገን ልኩ አራት ሺህ አምስት መቶ ክንድ፥ ሦስትም በሮች አሉ፤ አንዱ የስምዖን በር፥ አንዱም የይሳኮር በር፥ አንዱም የዛብሎን በር ነው።'),
  ('4bcadd9b-740b-5ccf-a531-4f0fe2400228', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', 'b928f965-5d4d-50dd-aa16-9e9d64299aeb', 5, 34, 'በምዕራቡም ወገን ልኩ አራት ሺህ አምስት መቶ ክንድ፥ ሦስትም በሮች አሉ፤ አንዱ የጋድ በር፥ አንዱም የአሴር በር፥ አንዱም የንፍታሌም በር ነው።'),
  ('a23edd3e-c50a-5656-a793-b45be3f8d1d0', 'a7f64e7c-d51d-5e3e-a824-6579a1da58ca', 'b928f965-5d4d-50dd-aa16-9e9d64299aeb', 6, 35, 'ዙሪያዋም ዐሥራ ስምንት ሺህ ክንድ ይሆናል፥ ከዚያም ቀን ጀምሮ የከተማዪቱ ስም፦ ‘እግዚአብሔር በዚያ አለ’ ተብሎ ይጠራል።”'),
  ('7df52d25-a403-5404-a19d-a29f949cd12b', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 1, 1, 'የይሁዳ ንጉሥ ኢዮአቄም በነገሠ በሦስተኛው ዓመት የባቢሎን ንጉሥ ናቡከደነፆር ወደ ኢየሩሳሌም መጥቶ ከበባት።'),
  ('3828a1a9-be70-5032-a937-59c81dee19a3', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 2, 2, 'እግዚአብሔርም የይሁዳን ንጉሥ ኢዮአቄምን፥ ከእግዚአብሔርም ቤት ዕቃ ከፍሎ በእጁ አሳልፎ ሰጠው፤ እርሱም ወደ ሰናዖር ምድር ወደ ጣዖቱ ቤት ወሰደው፥ ዕቃውንም ወደ ጣዖቱ ግምጃ ቤት አገባው።'),
  ('45136aa0-bb2d-5bbe-af4d-bcc848c1d46e', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 3, 3, 'ንጉሡም ለጃንደረቦቹ አለቃ ለአስፋኒዝ፦ ከተማረኩት ከእስራኤል ልጆች ከነገሥታቱና ከመሳፍንቱ ዘር፥'),
  ('8415fcde-57ae-513f-a945-55407f26185d', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 4, 4, 'ነውር የሌለባቸውንና መልከ መልካሞቹን፥ በጥበብ ሁሉ የሚያስተውሉትን፥ ዕውቀትም የሞላባቸውን፥ አስተዋዮች የሆኑትን፥ በንጉሡም ቤት መቆም የሚችሉትን ብላቴኖች ያመጣና የከለዳውያንንም ትምህርትና ቋንቋ ያስተምሩአቸው ዘንድ ነገረው።'),
  ('1a3e6a78-0c6f-5bd4-a71b-b4e6684b8344', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 5, 5, 'ንጉሡም ሦስት ዓመት ያሳድጉአቸው ዘንድ፥ ከዚያም በኋላ በንጉሡ ፊት ይቆሙ ዘንድ ከንጉሡ ማዕድ፥ ከሚጠጣውም ጠጅ በየዕለቱ ድርጎአቸውን አዘዘላቸው።'),
  ('2d999f54-7c8c-5f07-a71f-833c933b2e0e', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 6, 6, 'ከእነዚህም መካከል ከይሁዳ ልጆች ዳንኤልና አናንያ ሚሳኤልና አዛርያ ነበሩ።'),
  ('e36d6c71-dd7e-5dc1-aa6c-99deea3f17f7', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 7, 7, 'የጃንደረቦቹም አለቃ ስማቸውን ለውጦ፤ ዳንኤልን ብልጣሶር፥ አናንያንም ሲድራቅ፥ ሚሳኤልንም ሚሳቅ፥ አዛርያንም አብደናጎ ብሎ ጠራቸው።'),
  ('d3960a80-7209-532e-a6f1-065cc738eca2', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 8, 8, 'ዳንኤልም ከንጉሡ ማዕድ እንዳይበላ፥ ከሚጠጣውም ጠጅ እንዳይጠጣ በልቡ ጨከነ፤ እንዳያበላውም የጃንደረቦቹን አለቃ ለመነው።'),
  ('58f5da73-2e98-59b9-a513-960f171bb820', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 9, 9, 'እግዚአብሔርም በጃንደረቦቹ አለቃ ፊት ለዳንኤል ሞገስንና ምሕረትን ሰጠው።'),
  ('782b1b6a-6db7-55e0-a7c0-e23bce258c16', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 10, 10, 'የጃንደረቦቹም አለቃ ዳንኤልን፥ “መብሉንና መጠጡን ያዘዘላችሁን ጌታዬን ንጉሡን እፈራለሁ፤ በዕድሜ እንደ እናንተ ከአሉ ብላቴኖች ይልቅ ፊታችሁ ከስቶ ያየ እንደ ሆነ፥ ከንጉሡ ዘንድ በራሴ ታስፈርዱብኛላችሁ” አለው።'),
  ('a8e37ec8-1d19-5549-ac05-476f8f04aa9d', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 11, 11, 'ዳንኤልም የጃንደረቦቹ አለቃ በዳንኤልና በአናንያ፥ በሚሳኤልና በአዛርያ ላይ የሾመውን አሚሳድን፦'),
  ('9726b6b3-b4c6-55d0-a6d1-3405353e557a', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 12, 12, '“እኛን አገልጋዮችህን ዐሥር ቀን ያህል ፈትነን፤ የምንበላውንም ጥራጥሬ፥ የምንጠጣውንም ውኃ ይስጡን፤'),
  ('c02de1f5-2ef7-51c2-a7a9-a016f88c8856', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 13, 13, 'ከዚያም በኋላ የእኛን ሰውነትና ከንጉሡ ማዕድ የሚበሉትን የብላቴኖችን ሰውነት ተመልከት፤ እንደ አየኸውም ሁሉ ከአገልጋዮችህ ጋር የወደድኸውን አድርግ” አለው።'),
  ('2459a53d-2d0b-5744-a2a4-f00816ca4261', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 14, 14, 'ይህንም ነገራቸውን ሰምቶ ዐሥር ቀን ፈተናቸው።'),
  ('04a6fea8-678f-5d86-a337-5525d85e9fcd', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 15, 15, 'ከዐሥር ቀንም በኋላ ከንጉሡ ማዕድ ከበሉ ብላቴኖች ሁሉ ይልቅ ሰውነታቸው አምሮ፥ ሥጋቸውም ወፍሮ ታየ።'),
  ('fadaa829-a5ae-509c-a70a-c829f95adc80', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 16, 16, 'አሚሳድም መብላቸውንና የሚጠጡትን ጠጅ አስቀርቶ ጥራጥሬውን ሰጣቸው።'),
  ('a6a1f1de-65c4-5a20-a1aa-badb0f1d0626', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 17, 17, 'ለእነዚህም ለአራቱ ብላቴኖች እግዚአብሔር በትምህርትና በጥበብ ሁሉ ዕውቀትንና ማስተዋልን ሰጣቸው፤ ዳንኤልም በራእይና ሕልምን በመተርጐም ሁሉ አስተዋይ ነበረ።'),
  ('3424ebf3-f3fd-5b70-a190-cf54946bebf2', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 18, 18, 'እነርሱ ይገቡ ዘንድ ንጉሡ ያዘዘው ቀን በተፈጸመ ጊዜ፥ የጃንደረቦቹ አለቃ ወደ ናቡከደነፆር አገባቸው።'),
  ('bd1fae4b-154c-584a-a2ea-9acdf58fb0d5', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 19, 19, 'ንጉሡም በአነጋገራቸው ጊዜ ከብላቴኖቹ ሁሉ እንደ ዳንኤልና እንደ አናንያ እንደ ሚሳኤልና እንደ አዛርያ ያለ አልተገኘም፤ በንጉሡም ፊት ቆሙ።'),
  ('865cbd69-c7a2-5197-a40b-1b1233613151', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 20, 20, 'ንጉሡም በጠየቃቸው ጊዜ በጥበብና በማስተዋል ነገር ሁሉ፥ በግዛቱ ሁሉ ከሚኖሩ የሕልም ተርጓሚዎችና አስማተኞች ሁሉ እነርሱ ዐሥር እጅ የበለጡ ሆነው አገኛቸው።'),
  ('93c53ed2-3f20-5ff8-a6d0-cd0f14385cf5', '264ca7fb-10e6-5668-adc3-0e28d6f1007b', '815ecd45-a7df-5cdc-a3d9-5437fb7042e2', 21, 21, 'ዳንኤልም እስከ ንጉሡ እስከ ቂሮስ መጀመሪያ ዓመተ መንግሥት ተቀመጠ።'),
  ('c9aa88ab-1418-5ce3-a51f-1fc86326826f', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 1, 1, 'ናቡከደነፆርም በነገሠ በሁለተኛው ዓመት ሕልም አለመ፤ መንፈሱም ታወከ፤ ሕልሙንም ዘነጋው።'),
  ('5b255d34-c5cb-53f2-a60e-66f97f0618eb', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 2, 2, 'ንጉሡም ሕልሙን እንዲነግሩት የሕልም ተርጓሚዎቹንና አስማተኞቹን፥ መተተኞቹንና ከለዳውያኑንም ይጠሩ ዘንድ አዘዘ፤ እነርሱም ገብተው በንጉሡ ፊት ቆሙ።'),
  ('860ba200-0581-57e4-a42e-89476e1b3c99', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 3, 3, 'ንጉሡም፥ “ሕልም አልሜአለሁ፤ መንፈሴም ታወከብኝ፤ ሕልሜንም ዘነጋሁት” አላቸው።'),
  ('f80053f7-859c-5f6a-a52a-43a704563063', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 4, 4, 'ከለዳውያኑም ንጉሡን በሱርስት ቋንቋ፥ “ንጉሥ ሆይ! ለዘለዓለም ኑር፤ ለአገልጋዮችህ ሕልምህን ንገር፤ እኛም ፍቺውን እንነግርሃለን” ብለው ተናገሩት።'),
  ('42141a76-2727-5cf8-a86f-0b17be518cd9', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 5, 5, 'ንጉሡም መለሰ፤ ከለዳውያኑንም፥ “ነገሩ ከእኔ ዘንድ ርቆአል፤ ሕልሙንና ፍቺውን ባታስታውቁኝ፥ ትገደላላችሁ፤ ቤቶቻችሁም የጉድፍ መጣያ ይደረጋሉ።'),
  ('88bced8e-c910-5bf9-a6d5-2ce4deade9ba', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 6, 6, 'ሕልሙንና ፍቺውን ግን ብትነግሩኝ፥ ከእኔ ዘንድ ስጦታና ዋጋ፥ ብዙ ክብርም ትቀበላላችሁ፤ ስለዚህም ሕልሙንና ፍቺውን ንገሩኝ” አላቸው።'),
  ('7e2d8c6d-9a38-534c-ac9b-af6d0212b2e0', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 7, 7, 'ሁለተኛም ጊዜ መልሰው፥ “ንጉሡ ለአገልጋዮቹ ሕልሙን ይንገር፥ እኛም ፍቺውን እንናገራለን” አሉት።'),
  ('f4731504-b9de-5f1f-acc3-f22d7429cca2', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 8, 8, 'ንጉሡም መልሶ፥ “ነገሩ ከእኔ ዘንድ እንደ ራቀ ታውቃላችሁና ጊዜውን እንደምታስረዝሙ እኔ አውቃለሁ።'),
  ('95e96085-38b4-51f6-af42-0fea36dca8ab', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 9, 9, 'ሕልሙንም አሁን ባትነግሩኝ አንድ ፍርድ አለባችሁ፥ ጊዜውን ለማሳለፍ የሐሰትንና የተንኰልን ቃል ልትነግሩኝ አዘጋጅታችኋል፤ ስለዚህ ሕልሙን ንገሩኝ፤ ፍቺውንም መናገር እንደምትችሉ አውቃለሁ።”'),
  ('f8c0e680-02fc-5e42-afd8-f39336b4e078', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 10, 10, 'ከለዳውያኑም በንጉሡ ፊት መልሰው፥ “የንጉሡን ነገር ያሳይ ዘንድ የሚችል ሰው በምድር ላይ የለም፤ ታላቅ ንጉሥና አለቃ የሆነ እንደዚያ ያለ ነገር የሕልም ተርጓሚንና አስማተኛን፥ ከለዳዊንም የሚጠይቅ የለም።'),
  ('8557ebf4-b568-5d90-aef6-a791c6d523d6', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 11, 11, 'ንጉሡም የሚጠይቀው ነገር ከባድ ነው፤ መኖሪያቸው ከሥጋ ለባሽ ጋር ካልሆነ ከአማልክት በቀር በንጉሡ ፊት የሚያሳየው ማንም የለም” አሉ።'),
  ('8be1b5d2-8878-5790-a62c-e856a74cc0df', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 12, 12, 'ያንጊዜ ንጉሡ ፈጽሞ ተቈጣ፤ የባቢሎንንም ጠቢባን ሁሉ ያጠፉ ዘንድ አዘዘ።'),
  ('a26efca2-e9e1-5a6e-ae60-074f70368cdb', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 13, 13, 'ከንጉሡም ዘንድ ትእዛዝ ወጣ፤ ጠቢባንንም ይገድሉ ዘንድ ጀመሩ፤ ዳንኤልንና ባልንጀሮቹንም ይገድሉአቸው ዘንድ ፈለጉአቸው።'),
  ('a5129279-2e94-5be4-a5cf-05296c8f9e45', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 14, 14, 'የዚያን ጊዜም ዳንኤል የባቢሎንን ጠቢባን ይገድል ዘንድ የወጣውን የንጉሡን የዘብ አለቃ አርዮክን በፈሊጥና በማስተዋል ተናገረው፤'),
  ('afce6813-c425-58cb-a5c4-b4aef53b0909', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 15, 15, 'የንጉሡ የዘብ አለቃ አርዮክን፥ “ይህ ጭንቅ ትእዛዝ ከንጉሡ ዘንድ ስለ ምን ወጣ?” ብሎ ጠየቀው፤ አርዮክም ነገሩን ለዳንኤል ነገረው።'),
  ('e86def47-f39c-5158-a305-9407b780fec8', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 16, 16, 'ዳንኤልም ገብቶ ፍቺውን ለንጉሡ የሚያስታውቅበት ጊዜ ይሰጠው ዘንድ ንጉሡን ለመነ።'),
  ('21618275-893c-53f5-ac5e-831576777979', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 17, 17, 'የዚያን ጊዜም ዳንኤል ወደ ቤቱ ገባ። ነገሩንም ለባልንጀሮቹ ለአናንያና ለሚሳኤል፥ ለአዛርያም አስታወቃቸው።'),
  ('10b2e96a-ed6d-546d-a34e-f1b702be0edb', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 18, 18, 'ዳንኤልና ባልንጀሮቹም ከቀሩት ከባቢሎን ጠቢባን ጋር እንዳይሞቱ ስለዚህ ምሥጢር ምሕረትን ከሰማይ አምላክ ለመኑ።'),
  ('ea3e5cd7-b991-51bf-a44d-0db05af6821a', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 19, 19, 'የዚያን ጊዜም ምሥጢሩ በሌሊት ራእይ ለዳንኤል ተገለጠለት። ዳንኤልም የሰማይ አምላክን አመሰገነ።'),
  ('3f8e96ed-534d-5b93-a932-269f963f0df6', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 20, 20, 'እንዲህም አለ፥ “ጥበብና ምክር፥ ኀይልም ለእርሱ ነውና የእግዚአብሔር ስም ከዘለዓለም እስከ ዘለዓለም ይመስገን።'),
  ('2793a280-6ac9-51ba-a316-09b71df4ae5d', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 21, 21, 'እሱም ጊዜያትንና ዘመናትን ይለውጣል፤ ነገሥታትን ያስነሣል፤ ነገሥታትንም ይሽራል፤ ጥበብን ለጠቢባን፥ ዕውቀትንም ለአስተዋዮች ይሰጣል።'),
  ('21ecb723-ff71-5b26-a855-95d430d9bb66', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 22, 22, 'የጠለቀውንና የተሰወረውን ይገልጣል፤ በጨለማ ያለውን ያውቃል፤ ብርሃንም ከእርሱ ጋር አለ።'),
  ('d3ddffab-a07c-594f-a12a-82b0e57c32f8', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a2873114-804a-5b2e-ae16-369a8666f7a6', 23, 23, 'አንተ የአባቶቻችን ፈጣሪ! እውቀትንና ጥበብን ሰጥተኸኛልና፥ የለመንሁህንም ነግረኸኛልና፥ የንጉሡን ሕልም፥ ትርጓሜውንም ገልጠህልኛልና እገዛልሃለሁ፤ አመሰግንህምአለሁ።”'),
  ('b7243df2-97de-5139-a7f1-93ce989d7796', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 1, 24, 'ከዚህም በኋላ ዳንኤል ንጉሡ የባቢሎንን ጠቢባን ያጠፋ ዘንድ ወደ አዘዘው ወደ አርዮክ ገባ፤ “የባቢሎንን ጠቢባን አታጥፋቸው፤ ወደ ንጉሡ አስገባኝ፥ እኔም ሕልሙንና ፍቺውን ለንጉሡ እነግረዋለሁ” አለው'),
  ('cba816eb-8d2b-540b-a7cd-c9a9030f25d7', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 2, 25, 'የዚያን ጊዜም አርዮክ ዳንኤልን ፈጥኖ ወደ ንጉሡ አስገባውና፥ “ከይሁዳ የምርኮ ልጆች ለንጉሡ ሕልሙንና ፍቺውን የሚነግረውን ሰው አግኝቼአለሁ” አለው።'),
  ('384edf8a-f21d-56d9-ade1-58ff33f653f1', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 3, 26, 'ንጉሡም መለሰ፤ ብልጣሶርም የሚባለውን ዳንኤልን፥ “ያየሁትን ሕልምና ፍቺውንም ትነግረኝ ዘንድ ትችላለህን?” አለው።'),
  ('60fd67ff-5941-5ea6-a47a-3f4a0e420bc5', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 4, 27, 'ዳንኤልም በንጉሡ ፊት እንዲህ ሲል መለሰ፥ “ንጉሥ የሚጠይቀው ይህ ምሥጢር ለአዋቂዎችና ለፈላስፎች፥ ለሟርተኞችና ለጠንቋዮች የሚገለጥ አይደለም።”'),
  ('9f7d21f2-7a0e-5c43-a0eb-4b084c1efd6e', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 5, 28, 'ነገር ግን ምሥጢርን የሚገልጥ አምላክ በሰማይ ውስጥ አለ፤ እርሱም በኋለኛው ዘመን የሚሆነውን ለንጉሡ ለናቡከደነፆር አሳይቶታል። በአልጋህ ላይ የሆነው ሕልምና የራስህ ራእይ ይህ ነው።'),
  ('d7b1ca08-320d-5304-af7c-e5e1d6b5b909', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 6, 29, 'ንጉሥ ሆይ! ከአንተ በኋላ የሚሆነው ምን እንደ ሆነ በአልጋህ ላይ ታስብ ነበር፤ ምሥጢርንም የሚገልጠው የሚሆነውን ነገር አሳይቶሃል።'),
  ('21be81f0-6688-533a-a4d5-947b9e5450d2', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 7, 30, 'ነገር ግን ይህ ምሥጢር ለእኔ መገለጡ ፍቺው ለንጉሡ ይታወቅ ዘንድ፥ አንተም የልብህን አሳብ ታውቅ ዘንድ ነው እንጂ በዚህ ዓለም ከአሉ ሰዎች ይልቅ በጥበብ ስለ በለጥሁ አይደለም።'),
  ('295f20d4-b108-5835-ad17-7ff229cecaa1', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 8, 31, '“ንጉሥ ሆይ! አንተ አየህ፤ እነሆ ይኸውም አንድ ታላቅ ምስል ነበር፤ እርሱም በፊትህ ቆሞ ነበር፤ መልኩም ግሩም ነበር።'),
  ('179c6f98-452c-593e-adbd-27604415b067', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 9, 32, 'የዚህም ምስል ራስ ጥሩ ወርቅ፥ እጆቹ፥ ደረቱና ክንዶቹም ብር፥ ሆዱና ወገቡም ናስ፤'),
  ('05321a4c-0526-5ff6-ac8d-4b3adce957d8', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 10, 33, 'ጭኖቹም ብረት፥ እግሮቹም እኩሉ ብረት እኩሉም ሸክላ ነበረ።'),
  ('b95be7a2-0e10-59ef-af8e-3e15fe7612e7', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 11, 34, 'እጅም ሳይነካው ታላቅ ድንጋይ ከተራራው ተፈንቅሎ ከብረትና ከሸክላ የሆነውን የምስሉን እግሮች እስከ መጨረሻው ሲመታና ሲፈጭ አየህ።'),
  ('b501329f-524f-5750-a32a-02383caeb1a1', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 12, 35, 'የዚያን ጊዜም ብረቱና ሸክላው፥ ናሱና ብሩ፥ ወርቁም በአንድነት ተፈጨ፤ በመከርም ጊዜ በአውድማ ላይ እንደአለ እብቅ ሆነ፤ ነፋስም ወሰደው፤ ቦታውም አልታወቀም፤ ምስሉንም የመታው ድንጋይ ታላቅ ተራራ ሆነ፤ ምድርንም ሁሉ ሞላ።'),
  ('13efae85-43d7-5736-a4b1-f39dbe407aaa', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 13, 36, '“ሕልምህ ይህ ነው፤ ፍቺውንም በንጉሡ ፊት እናገራለሁ።'),
  ('c70fb7de-3000-5ea4-a1c0-e192a263565a', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 14, 37, 'ንጉሥ ሆይ! የሰማይ አምላክ ጠንካራ መንግሥትን፥ ኀይልንና ክብርን የሰጠህ የነገሥታት ንጉሥ አንተ ነህ።'),
  ('4c0597af-469e-5b58-add1-d72074edb9c3', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 15, 38, 'የሰው ልጆች በሚኖሩበት ስፍራ ሁሉ የምድር አራዊትን፥ የሰማይ ወፎችን፥ የባሕር ዓሣዎችንም በእጅህ ሰጥቶሃል፤ ለሁሉም ገዢ አድርጎ ሹሞሃል፤ የወርቁ ራስ አንተ ነህ።'),
  ('855a41f9-e9db-5973-a2b7-3b9529865086', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 16, 39, 'ከአንተም በኋላ ከአንተ የሚያንስ ሌላ መንግሥት ይነሣል፤ እርሱም የብሩ ነው። ከዚያም በኋላ በምድር ሁሉ ላይ የሚገዛ ሌላ ሦስተኛ መንግሥት ይነሣል፤ እርሱም የናሱ ነው።'),
  ('c8d7b18a-0e81-556e-af8d-2f536465c7d2', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 17, 40, 'አራተኛውም መንግሥት ሁሉን እንደሚቀጠቅጥና እንደሚያደቅቅ ብረት ይበረታል፤ እነዚህንም ሁሉ እንደሚፈጭ ብረት ይቀጠቅጣል፤ ይፈጭማል።'),
  ('b20a2e51-ae77-5e1b-a42f-bb2d5d92c37d', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 18, 41, 'እግሮቹና ጣቶቹም እኩሉ ሸክላ፥ እኩሉም ብረት ሆኖ እንደአየህ፥ እንዲሁ የተከፋፈለ መንግሥት ይሆናል፤ ብረቱም ከሸክላው ጋር ተደባልቆ እንደ አየኸው፥ የብረት ብርታት ለእርሱ ይሆናል።'),
  ('adb5e13d-2f82-56e2-a3fb-42ca1b790d16', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 19, 42, 'የእግሮቹም ጣቶች እኩሉ ብረት፥ እኩሉም ሸክላ እንደ ነበሩ፥ እንዲሁ መንግሥቱ እኩሉ ብርቱ፥ እኩሉ ደካማ ይሆናል።'),
  ('8908ce17-b2cb-5d47-a7e3-fc700bd91be2', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 20, 43, 'ብረቱም ከሸክላው ጋር ተደባልቆ እንዳየህ፥ እንዲሁ ከሰው ዘር ጋር ይደባለቃሉ፤ ነገር ግን ብረት ከሸክላ ጋር እንደማይጣበቅ እንዲሁ እርስ በርሳቸው አይጣበቁም'),
  ('a7c187ff-e571-59c2-a235-116234e0746a', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 21, 44, 'በእነዚያም ነገሥታት ዘመን የሰማይ አምላክ ለዘለዓለም የማይፈርስ መንግሥት ያስነሣል፤ ለሌላ ሕዝብም የማይሰጥ መንግሥት ይሆናል፤ እነዚያንም መንግሥታት ሁሉ ድል ታደርጋቸዋለች፤ ታጠፋቸውማለች፤ ለዘለዓለምም ትቆማለች።'),
  ('c878af59-e278-59b6-afa1-a1221ae6f84f', 'c21edf27-584a-59b1-a274-54d6a01a6754', '6de742d7-166c-5549-a105-b1176166ba33', 22, 45, 'ድንጋዩም እጅ ሳይነካው ከተራራ ተፈንቅሎ ብረቱንና ናሱን፥ ሸክላውንና ብሩን፥ ወርቁንም ሲፈጨው እንደ አየህ፥ እንዲሁ ከዚህ በኋላ የሚሆነውን ታላቁ አምላክ ለንጉሡ አሳይቶታል፤ ሕልሙም እውነተኛ፥ ፍቺውም የታመነ ነው።”'),
  ('3b80ed80-de51-526b-a069-c77e1b7d9553', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a66338da-5c28-5521-a6d3-a9df43b588eb', 1, 46, 'የዚያን ጊዜም ንጉሡ ናቡከደነፆር በግምባሩ ተደፍቶ ለዳንኤል ሰገደለት። ፈጽሞም አከበረው፥ ገጸ በረከትም ሰጠው፤ መልካም መዓዛም ያቀርቡለት ዘንድ አዘዘ።'),
  ('8325fbb4-94c5-515f-afb7-35221c6bdfdb', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a66338da-5c28-5521-a6d3-a9df43b588eb', 2, 47, 'ንጉሡም ዳንኤልን፥ “ይህን ምሥጢር ትገልጥ ዘንድ ተችሎሃልና በእውነት አምላካችሁ የአማልክት አምላክ፥ የነገሥታትም ጌታ፥ ምሥጢርም ገላጭ ነው” ብሎ ተናገረው።'),
  ('fbf69ad9-f37f-56eb-a7fd-2c3929142390', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a66338da-5c28-5521-a6d3-a9df43b588eb', 3, 48, 'ንጉሡም ዳንኤልን ከፍ ከፍ አደረገው፤ ብዙም ታላቅ ስጦታ ሰጠው፤ በባቢሎንም አውራጃዎች ሁሉ ላይ ሾመው፤ በባቢሎንም ጠቢባን ሁሉ ላይ ዋነኛ አለቃ አደረገው።'),
  ('58fd4f13-ed96-5070-a47c-74bb0c84f532', 'c21edf27-584a-59b1-a274-54d6a01a6754', 'a66338da-5c28-5521-a6d3-a9df43b588eb', 4, 49, 'ዳንኤልም ንጉሡን ለመነ፤ እርሱም ሲድራቅንና ሚሳቅን፥ አብደናጎንም በባቢሎን አውራጃ ሥራ ላይ ሾማቸው፤ ዳንኤል ግን በንጉሡ አደባባይ ነበረ።'),
  ('7ca26fbe-0342-57d7-a735-f28dc0b8d5d8', '919c09cf-725c-5b33-ae47-325eb397ba20', 'd1f9bb6d-ebc5-5344-a367-9d56a1a89f01', 1, 1, 'ንጉሡ ናቡከደነፆር በነገሠ በዐሥራ ስምንተኛው ዓመት ቁመቱ ስድሳ ክንድ፥ ወርዱም ስድስት ክንድ የሆነ የወርቅ ምስል አሠራ፤ በባቢሎንም አውራጃ በዱራ ሜዳ አቆመው።'),
  ('fb43b3a6-df94-5b0d-a2fd-b94046fbf333', '919c09cf-725c-5b33-ae47-325eb397ba20', 'd1f9bb6d-ebc5-5344-a367-9d56a1a89f01', 2, 2, 'ንጉሡም ናቡከደነፆር መኳንንትንና ሹሞችን፥ አዛዦችንና አዛውንቶችን፥ በጅሮንዶችንና አማካሪዎችን፥ መጋቢዎችንም፥ አውራጃ ገዢዎችንም ሁሉ ይሰበስቡ ዘንድ፥ ንጉሡ ናቡከደነፆርም ላቆመው ምስል ምረቃ ይመጡ ዘንድ ላከ።'),
  ('1e24a25b-9796-5eec-a1f0-7acc780451a0', '919c09cf-725c-5b33-ae47-325eb397ba20', 'd1f9bb6d-ebc5-5344-a367-9d56a1a89f01', 3, 3, 'በዚያን ጊዜም መኳንንቱና ሹሞቹ፥ አዛዦቹና አዛውንቶቹ፥ በጅሮንዶቹና አማካሪዎቹ፥ መጋቢዎቹና አውራጃ ገዢዎቹ ሁሉ ንጉሡ ናቡከደነፆር ላቆመው ምስል ምረቃ ተሰበሰቡ፤ ናቡከደነፆርም ባቆመው ምስል ፊት ቆሙ።'),
  ('d7aa6281-ccce-5783-a526-fd32e3cc5351', '919c09cf-725c-5b33-ae47-325eb397ba20', 'd1f9bb6d-ebc5-5344-a367-9d56a1a89f01', 4, 4, 'አዋጅ ነጋሪውም እየጮኸ እንዲህ አለ፥ “ሕዝብና አሕዛብ፥ በልዩ ልዩ ቋንቋም የምትናገሩ ሆይ! ንጉሥ ይላችኋል፥'),
  ('864b4579-0af7-5377-ae74-8e58eb1274be', '919c09cf-725c-5b33-ae47-325eb397ba20', 'd1f9bb6d-ebc5-5344-a367-9d56a1a89f01', 5, 5, 'የመለከትንና የእንቢልታን፥ የመሰንቆንና የክራርን፥ የበገናንና የዋሽንትን፥ የዘፈንንም ሁሉ ድምፅ በሰማችሁ ጊዜ ወድቃችሁ ንጉሡ ናቡከደነፆር ላቆመው ለወርቁ ምስል ስገዱ፤'),
  ('ebbfa248-51b7-5d45-a257-cfba77a38a39', '919c09cf-725c-5b33-ae47-325eb397ba20', 'd1f9bb6d-ebc5-5344-a367-9d56a1a89f01', 6, 6, 'ወድቆም የማይሰግድ በዚያን ጊዜ በሚነድድ እሳት እቶን ውስጥ ይጣላል።”'),
  ('a1938f50-b662-50e3-a578-71fa0b5b6e76', '919c09cf-725c-5b33-ae47-325eb397ba20', 'd1f9bb6d-ebc5-5344-a367-9d56a1a89f01', 7, 7, 'ስለዚህ በዚያን ጊዜ አሕዛብ ሁሉ የመለከቱንና የእንቢልታውን፥ የመሰንቆውንና የክራሩን፥ የበገናውንና የዘፈኑንም ሁሉ ድምፅ በሰሙ ጊዜ፥ ወገኖችና አሕዛብ፥ በልዩ ልዩ ቋንቋም የሚናገሩ ሁሉ ወድቀው፤ ንጉሡ ናቡከደነፆር ላቆመው ለወርቅ ምስል ሰገዱ።')
